import{m as e}from"./merge-BmcoofH2.js";const t={"grundlagen-des-wirtschaftens":[{type:"text",level:1,de:{q:"Wie nennt man ein Gefühl des Mangels, verbunden mit dem Wunsch, diesen Mangel zu beseitigen?",a:["Bedürfnis","Bedürfnisse"],e:"Ein Bedürfnis ist das Gefühl eines Mangels mit dem Wunsch, ihn zu beseitigen."},en:{q:"What do you call a feeling of lack combined with the wish to remove it?",a:["need","needs","want"],e:"A need is the feeling of lacking something combined with the wish to remove that lack."},hu:{q:"Hogyan nevezzük a hiányérzetet, amely azzal a vággyal jár, hogy ezt a hiányt megszüntessük?",a:["szükséglet","szükségletek"],e:"A szükséglet hiányérzet, amely a hiány megszüntetésének vágyával jár."}},{type:"text",level:2,de:{q:"Wie heißt das ökonomische Prinzip, bei dem ein vorgegebenes Ziel mit möglichst wenig Mitteln erreicht werden soll?",a:["Minimalprinzip","Sparprinzip"],e:"Minimalprinzip: Das Ziel ist fix, der Einsatz soll so gering wie möglich sein."},en:{q:"What is the economic principle called where a fixed goal should be reached using as few resources as possible?",a:["minimum principle","minimal principle","economy principle"],e:"Minimum principle: the goal is fixed, the input should be as small as possible."},hu:{q:"Hogyan nevezzük azt a gazdasági elvet, amelynél egy adott célt a lehető legkevesebb eszközzel kell elérni?",a:["minimumelv","minimum elv","takarékossági elv"],e:"Minimumelv: a cél rögzített, a ráfordítás legyen a lehető legkisebb."}},{type:"mc",level:3,correctIndex:0,de:{q:"Loopy will mit einem fixen Werbebudget von 2.000 € möglichst viele neue Kund:innen gewinnen. Danach möchte sie dieselbe Menge Pralinen mit möglichst geringen Verpackungskosten verpacken. Welche Prinzipien wendet sie in dieser Reihenfolge an?",o:["Zuerst Maximalprinzip, dann Minimalprinzip","Zuerst Minimalprinzip, dann Maximalprinzip","Beide Male das Maximalprinzip","Beide Male das Minimalprinzip"],e:"Fixes Budget, möglichst viel Ergebnis = Maximalprinzip. Fixe Menge, möglichst geringe Kosten = Minimalprinzip."},en:{q:"Loopy wants to win as many new customers as possible with a fixed advertising budget of €2,000. Then she wants to pack the same number of chocolates at the lowest possible packaging cost. Which principles does she apply, in this order?",o:["First the maximum principle, then the minimum principle","First the minimum principle, then the maximum principle","The maximum principle both times","The minimum principle both times"],e:"Fixed budget, as much result as possible = maximum principle. Fixed quantity, as little cost as possible = minimum principle."},hu:{q:"Loopy rögzített, 2000 €-s reklámköltségvetéssel a lehető legtöbb új vásárlót szeretné megnyerni. Utána ugyanannyi bonbont a lehető legkisebb csomagolási költséggel szeretne becsomagolni. Milyen elveket alkalmaz ebben a sorrendben?",o:["Először maximumelv, aztán minimumelv","Először minimumelv, aztán maximumelv","Mindkétszer maximumelv","Mindkétszer minimumelv"],e:"Rögzített költségvetés, a lehető legnagyobb eredmény = maximumelv. Rögzített mennyiség, a lehető legkisebb költség = minimumelv."}}],"der-markt":[{type:"text",level:1,de:{q:"Wie nennt man den Preis, bei dem die angebotene Menge genau der nachgefragten Menge entspricht?",a:["Gleichgewichtspreis","Marktpreis","Marktgleichgewicht"],e:"Beim Gleichgewichtspreis schneiden sich Angebots- und Nachfragekurve."},en:{q:"What do you call the price at which the quantity supplied equals the quantity demanded?",a:["equilibrium price","market price","market equilibrium"],e:"At the equilibrium price the supply and demand curves intersect."},hu:{q:"Hogyan nevezzük azt az árat, amelynél a kínált mennyiség pontosan megegyezik a keresett mennyiséggel?",a:["egyensúlyi ár","piaci ár","piaci egyensúly"],e:"Az egyensúlyi árnál metszi egymást a kínálati és a keresleti görbe."}},{type:"text",level:2,de:{q:"Wie heißt die Marktform, bei der es nur einen einzigen Anbieter gibt?",a:["Monopol","Angebotsmonopol"],e:"Ein einziger Anbieter = Monopol, wenige Anbieter = Oligopol, viele Anbieter = Polypol."},en:{q:"What is the market form called where there is only a single supplier?",a:["monopoly","supply monopoly"],e:"One supplier = monopoly, few suppliers = oligopoly, many suppliers = polypoly."},hu:{q:"Hogyan nevezzük azt a piaci formát, amelyben csak egyetlen kínáló van?",a:["monopólium","kínálati monopólium"],e:"Egy kínáló = monopólium, kevés kínáló = oligopólium, sok kínáló = polipólium."}},{type:"number",level:3,value:4,tol:.01,unit:{de:"€",en:"€",hu:"€"},de:{q:"Auf einem Markt gilt: Nachfrage = 300 − 40 · Preis und Angebot = 60 · Preis − 100 (Mengen in Stück, Preis in €). Berechne den Gleichgewichtspreis.",e:"300 − 40p = 60p − 100 → 400 = 100p → p = 4 €. Dann werden 140 Stück verkauft."},en:{q:"On a market: demand = 300 − 40 · price and supply = 60 · price − 100 (quantities in pieces, price in €). Calculate the equilibrium price.",e:"300 − 40p = 60p − 100 → 400 = 100p → p = €4. Then 140 pieces are sold."},hu:{q:"Egy piacon: kereslet = 300 − 40 · ár és kínálat = 60 · ár − 100 (mennyiség darabban, ár €-ban). Számítsd ki az egyensúlyi árat.",e:"300 − 40p = 60p − 100 → 400 = 100p → p = 4 €. Ekkor 140 darabot adnak el."}}],"unternehmen-und-umfeld":[{type:"text",level:1,de:{q:"Wie nennt man alle Personen und Gruppen, die ein Interesse am Unternehmen haben (z. B. Kund:innen, Mitarbeitende, Staat)?",a:["Stakeholder","Anspruchsgruppen","Interessengruppen"],e:"Stakeholder (Anspruchsgruppen) haben Erwartungen an das Unternehmen und werden von ihm beeinflusst."},en:{q:"What do you call all people and groups that have an interest in the company (e.g. customers, employees, the state)?",a:["stakeholders","stakeholder","interest groups"],e:"Stakeholders have expectations of the company and are affected by it."},hu:{q:"Hogyan nevezzük mindazokat a személyeket és csoportokat, akiknek érdekük fűződik a vállalathoz (pl. vevők, munkavállalók, állam)?",a:["érintettek","stakeholderek","érintett csoportok","érdekcsoportok"],e:"Az érintettek (stakeholderek) elvárásokat támasztanak a vállalattal szemben, és hatással van rájuk."}},{type:"text",level:2,de:{q:"Ein Unternehmen will seinen CO₂-Ausstoß um 20 % senken. Zu welcher Art von Unternehmenszielen gehört das?",a:["ökologische Ziele","ökologisches Ziel","ökologisch","Umweltziel"],e:"Ziele zum Schutz der Umwelt sind ökologische Ziele (daneben gibt es ökonomische und soziale Ziele)."},en:{q:"A company wants to cut its CO₂ emissions by 20%. Which kind of company goal is this?",a:["ecological goal","ecological goals","ecological","environmental goal"],e:"Goals that protect the environment are ecological goals (besides economic and social goals)."},hu:{q:"Egy vállalat 20%-kal szeretné csökkenteni a CO₂-kibocsátását. Milyen vállalati célról van szó?",a:["ökológiai cél","ökológiai célok","ökológiai","környezetvédelmi cél"],e:"A környezet védelmét szolgáló célok ökológiai célok (emellett vannak gazdasági és társadalmi célok)."}},{type:"mc",level:3,correctIndex:0,de:{q:"Loopy will die Löhne ihrer Mitarbeitenden erhöhen und gleichzeitig den Gewinn steigern – ohne die Preise anzuheben und ohne mehr zu verkaufen. Welche Zielbeziehung liegt vor?",o:["Zielkonflikt","Zielharmonie","Zielneutralität","Zielidentität"],e:"Höhere Löhne erhöhen die Kosten und senken – bei gleichen Preisen und Mengen – den Gewinn. Die Ziele behindern sich: Zielkonflikt."},en:{q:"Loopy wants to raise her employees' wages and increase profit at the same time – without raising prices and without selling more. What relationship between the goals is this?",o:["Goal conflict","Goal harmony","Goal neutrality","Goal identity"],e:"Higher wages raise costs and – with the same prices and quantities – lower profit. The goals hinder each other: goal conflict."},hu:{q:"Loopy emelni szeretné munkatársai bérét, és egyidejűleg növelni a nyereséget – áremelés és több eladás nélkül. Milyen célkapcsolatról van szó?",o:["Célkonfliktus","Célharmónia","Célsemlegesség","Célazonosság"],e:"A magasabb bérek növelik a költségeket, és – azonos árak és mennyiségek mellett – csökkentik a nyereséget. A célok akadályozzák egymást: célkonfliktus."}}],"leistungserstellung-1jg":[{type:"text",level:1,de:{q:"Wie nennt man einen Betrieb, der Sachgüter herstellt (das Gegenteil ist ein Dienstleistungsbetrieb)?",a:["Sachleistungsbetrieb","Produktionsbetrieb","Herstellungsbetrieb","Industriebetrieb"],e:"Betriebe, die Sachgüter erzeugen, sind Sachleistungs- bzw. Produktionsbetriebe."},en:{q:"What do you call a business that produces physical goods (the opposite is a service business)?",a:["manufacturing business","production business","goods-producing business","manufacturer"],e:"Businesses that produce physical goods are production or manufacturing businesses."},hu:{q:"Hogyan nevezzük a tárgyi javakat előállító üzemet (az ellentéte a szolgáltató üzem)?",a:["termelő üzem","termelő vállalat","gyártó üzem","gyártó vállalat"],e:"A tárgyi javakat előállító üzemek termelő, illetve gyártó üzemek."}},{type:"number",level:2,value:60,tol:0,unit:{de:"Stück/Std.",en:"pcs/hr",hu:"db/óra"},de:{q:"Loopy stellt mit 2 Mitarbeitenden in 8 Stunden 960 Pralinen her. Wie hoch ist die Arbeitsproduktivität (Pralinen pro Arbeitsstunde)?",e:"Arbeitsstunden: 2 · 8 = 16. Produktivität = 960 ÷ 16 = 60 Pralinen pro Arbeitsstunde."},en:{q:"Loopy's 2 employees make 960 chocolates in 8 hours. What is the labour productivity (chocolates per working hour)?",e:"Working hours: 2 · 8 = 16. Productivity = 960 ÷ 16 = 60 chocolates per working hour."},hu:{q:"Loopy 2 munkatársa 8 óra alatt 960 bonbont készít. Mekkora a munkatermelékenység (bonbon munkaóránként)?",e:"Munkaórák: 2 · 8 = 16. Termelékenység = 960 ÷ 16 = 60 bonbon munkaóránként."}},{type:"number",level:3,value:1.25,tol:.005,de:{q:"Loopys Pralinenproduktion bringt in einem Monat 12.000 € Erträge bei 9.600 € Aufwänden. Berechne die Wirtschaftlichkeit (Ertrag ÷ Aufwand) auf 2 Kommastellen.",e:"Wirtschaftlichkeit = 12.000 ÷ 9.600 = 1,25. Werte über 1 bedeuten: Es wird wirtschaftlich gearbeitet."},en:{q:"In one month Loopy's chocolate production brings €12,000 in income with €9,600 in expenses. Calculate the efficiency (income ÷ expenses) to 2 decimal places.",e:"Efficiency = 12,000 ÷ 9,600 = 1.25. Values above 1 mean the business is working efficiently."},hu:{q:"Loopy bonbongyártása egy hónapban 12 000 € bevételt hoz 9600 € ráfordítás mellett. Számítsd ki a gazdaságosságot (bevétel ÷ ráfordítás) 2 tizedesjegyre.",e:"Gazdaságosság = 12 000 ÷ 9600 = 1,25. Az 1 feletti érték azt jelenti, hogy gazdaságosan dolgoznak."}}],"phasen-kaufen-verkaufen":[{type:"text",level:1,de:{q:"Wie nennt man die unverbindliche Bitte eines Käufers um Informationen zu Waren, Preisen und Bedingungen?",a:["Anfrage"],e:"Mit der Anfrage holt der Käufer unverbindlich Informationen ein – sie verpflichtet zu nichts."},en:{q:"What do you call a buyer's non-binding request for information about goods, prices and conditions?",a:["enquiry","inquiry","request for quotation"],e:"With an enquiry the buyer collects information without obligation – it does not commit anyone to anything."},hu:{q:"Hogyan nevezzük a vevő kötelezettség nélküli kérését az árukról, árakról és feltételekről?",a:["ajánlatkérés","érdeklődés","tudakozódás"],e:"Az ajánlatkéréssel a vevő kötelezettség nélkül szerez információt – senkit sem kötelez semmire."}},{type:"text",level:2,de:{q:"Wie nennt man ein „Angebot“ an die Allgemeinheit (z. B. im Schaufenster oder Prospekt), das rechtlich nur eine Aufforderung zur Angebotsstellung ist?",a:["Anpreisung","Anpreisungen"],e:"Anpreisungen richten sich an viele Menschen und sind unverbindlich – erst die Bestellung des Kunden ist ein Angebot."},en:{q:'What do you call an "offer" to the general public (e.g. in a shop window or brochure) that legally is only an invitation to make an offer?',a:["invitation to treat","advertisement","advertising"],e:"An invitation to treat is aimed at many people and is not binding – only the customer's order is an offer."},hu:{q:"Hogyan nevezzük a nagyközönségnek szóló „ajánlatot” (pl. kirakatban vagy prospektusban), amely jogilag csak ajánlattételre való felhívás?",a:["ajánlattételi felhívás","reklám","hirdetés"],e:"Az ajánlattételi felhívás sok embernek szól és nem kötelező – csak a vevő rendelése számít ajánlatnak."}},{type:"mc",level:3,correctIndex:2,de:{q:"Welche Reihenfolge der Phasen beim Kaufen und Verkaufen ist richtig?",o:["Angebot – Anfrage – Bestellung – Lieferung – Auftragsbestätigung – Zahlung","Anfrage – Bestellung – Angebot – Auftragsbestätigung – Zahlung – Lieferung","Anfrage – Angebot – Bestellung – Auftragsbestätigung – Lieferung – Zahlung","Anfrage – Angebot – Auftragsbestätigung – Bestellung – Lieferung – Zahlung"],e:"Zuerst fragt der Käufer an, dann folgen Angebot, Bestellung, Auftragsbestätigung, Lieferung und schließlich die Zahlung."},en:{q:"Which order of the phases of buying and selling is correct?",o:["Offer – enquiry – order – delivery – order confirmation – payment","Enquiry – order – offer – order confirmation – payment – delivery","Enquiry – offer – order – order confirmation – delivery – payment","Enquiry – offer – order confirmation – order – delivery – payment"],e:"First the buyer makes an enquiry, then come the offer, order, order confirmation, delivery and finally payment."},hu:{q:"Melyik a vétel és eladás szakaszainak helyes sorrendje?",o:["Ajánlat – ajánlatkérés – rendelés – szállítás – rendelésvisszaigazolás – fizetés","Ajánlatkérés – rendelés – ajánlat – rendelésvisszaigazolás – fizetés – szállítás","Ajánlatkérés – ajánlat – rendelés – rendelésvisszaigazolás – szállítás – fizetés","Ajánlatkérés – ajánlat – rendelésvisszaigazolás – rendelés – szállítás – fizetés"],e:"Először a vevő ajánlatot kér, majd jön az ajánlat, a rendelés, a rendelésvisszaigazolás, a szállítás és végül a fizetés."}}],"gesetzliche-grundlagen-kauf":[{type:"text",level:1,de:{q:"Welches österreichische Gesetzbuch regelt Kaufverträge zwischen Privatpersonen? (Abkürzung reicht)",a:["ABGB","Allgemeines Bürgerliches Gesetzbuch"],e:"Das ABGB (Allgemeines Bürgerliches Gesetzbuch) regelt Verträge zwischen Privatpersonen."},en:{q:"Which Austrian code regulates purchase contracts between private persons? (The abbreviation is enough)",a:["ABGB","Austrian Civil Code","General Civil Code"],e:"The ABGB (Austrian General Civil Code) regulates contracts between private persons."},hu:{q:"Melyik osztrák törvénykönyv szabályozza a magánszemélyek közötti adásvételi szerződéseket? (A rövidítés is elég)",a:["ABGB","Osztrák Polgári Törvénykönyv","Általános Polgári Törvénykönyv"],e:"Az ABGB (Általános Polgári Törvénykönyv) szabályozza a magánszemélyek közötti szerződéseket."}},{type:"number",level:2,value:18,tol:0,unit:{de:"Jahre",en:"years",hu:"év"},de:{q:"Ab welchem Alter ist man in Österreich voll geschäftsfähig?",e:"Mit 18 Jahren (Volljährigkeit) ist man voll geschäftsfähig und kann alle Verträge selbst abschließen."},en:{q:"From what age does a person have full legal capacity to contract in Austria?",e:"At 18 (coming of age) a person has full legal capacity and can conclude any contract themselves."},hu:{q:"Hány éves kortól teljesen cselekvőképes valaki Ausztriában?",e:"18 éves kortól (nagykorúság) teljesen cselekvőképes, és minden szerződést maga köthet meg."}},{type:"mc",level:3,correctIndex:1,de:{q:"Loopy (Unternehmerin) kauft bei einem Großhändler 50 kg Kakao für ihren Candy Store. Welches Geschäft liegt vor und welches Gesetz gilt vorrangig?",o:["Verbrauchergeschäft – KSchG","Beiderseitiges Unternehmergeschäft – UGB","Bürgerliches Geschäft – ausschließlich ABGB","Einseitiges Unternehmergeschäft – KSchG"],e:"Beide Vertragspartner sind Unternehmer (B2B): beiderseitiges Unternehmergeschäft, für das vorrangig das UGB gilt."},en:{q:"Loopy (a business owner) buys 50 kg of cocoa from a wholesaler for her Candy Store. What kind of transaction is this and which law mainly applies?",o:["Consumer transaction – KSchG","Two-sided business transaction – UGB","Civil transaction – ABGB exclusively","One-sided business transaction – KSchG"],e:"Both partners are businesses (B2B): a two-sided business transaction, for which mainly the UGB (Austrian Commercial Code) applies."},hu:{q:"Loopy (vállalkozó) 50 kg kakaót vásárol egy nagykereskedőtől a Candy Store számára. Milyen ügyletről van szó, és melyik törvény érvényes elsősorban?",o:["Fogyasztói ügylet – KSchG","Kétoldalú vállalkozói ügylet – UGB","Polgári ügylet – kizárólag ABGB","Egyoldalú vállalkozói ügylet – KSchG"],e:"Mindkét fél vállalkozó (B2B): kétoldalú vállalkozói ügylet, amelyre elsősorban az UGB (osztrák vállalati törvénykönyv) vonatkozik."}}],"fernabsatz-ecommerce":[{type:"text",level:1,de:{q:"Wie nennt man Verträge, die ohne gleichzeitige Anwesenheit der Vertragspartner geschlossen werden (z. B. über Internet oder Telefon)?",a:["Fernabsatzvertrag","Fernabsatzverträge","Fernabsatz","Fernabsatzgeschäft"],e:"Fernabsatzverträge werden nur über Fernkommunikationsmittel wie Internet, Telefon oder Katalog geschlossen."},en:{q:"What do you call contracts concluded without the partners being present at the same time (e.g. via the internet or phone)?",a:["distance contract","distance contracts","distance selling"],e:"Distance contracts are concluded only via means of distance communication such as the internet, phone or catalogue."},hu:{q:"Hogyan nevezzük azokat a szerződéseket, amelyeket a felek egyidejű jelenléte nélkül kötnek (pl. interneten vagy telefonon)?",a:["távollévők közötti szerződés","távértékesítési szerződés","távértékesítés"],e:"A távollévők közötti szerződéseket csak távközlési eszközökkel – internet, telefon, katalógus – kötik meg."}},{type:"number",level:2,value:14,tol:0,unit:{de:"Tage",en:"days",hu:"nap"},de:{q:"Wie viele Tage dauert die gesetzliche Rücktrittsfrist bei einem Online-Kauf als Verbraucher:in in der EU?",e:"Bei Fernabsatzverträgen können Verbraucher:innen innerhalb von 14 Tagen ohne Angabe von Gründen zurücktreten."},en:{q:"How many days does the legal withdrawal period last when a consumer buys online in the EU?",e:"For distance contracts consumers can withdraw within 14 days without giving reasons."},hu:{q:"Hány napig tart a törvényes elállási határidő, ha fogyasztóként online vásárolsz az EU-ban?",e:"Távollévők közötti szerződéseknél a fogyasztók 14 napon belül indoklás nélkül elállhatnak."}},{type:"text",level:3,de:{q:"Wie heißt das österreichische Gesetz, das Fernabsatz- und Auswärtsgeschäfte regelt? (Abkürzung reicht)",a:["FAGG","Fern- und Auswärtsgeschäfte-Gesetz"],e:"Das FAGG (Fern- und Auswärtsgeschäfte-Gesetz) regelt Informationspflichten und das Rücktrittsrecht bei solchen Geschäften."},en:{q:"What is the Austrian law called that regulates distance and off-premises contracts? (The abbreviation is enough)",a:["FAGG","Distance and Off-Premises Contracts Act"],e:"The FAGG (Distance and Off-Premises Contracts Act) regulates information duties and the right of withdrawal for such contracts."},hu:{q:"Hogy hívják azt az osztrák törvényt, amely a távollévők közötti és az üzlethelyiségen kívül kötött szerződéseket szabályozza? (A rövidítés is elég)",a:["FAGG"],e:"Az FAGG szabályozza az ilyen ügyletek tájékoztatási kötelezettségeit és az elállási jogot."}}],ruecktrittsrechte:[{type:"text",level:1,de:{q:"Wie nennt man ein Geschäft, das außerhalb der Geschäftsräume des Unternehmens geschlossen wird (z. B. an der Haustür)?",a:["Auswärtsgeschäft","Haustürgeschäft","Auswärtsgeschäfte"],e:"Auswärtsgeschäfte (z. B. Haustürgeschäfte) finden außerhalb der Geschäftsräume statt – Verbraucher:innen haben ein Rücktrittsrecht."},en:{q:"What do you call a contract concluded outside the company's business premises (e.g. at the front door)?",a:["off-premises contract","doorstep sale","doorstep selling"],e:"Off-premises contracts (e.g. doorstep sales) take place outside the business premises – consumers have a right of withdrawal."},hu:{q:"Hogyan nevezzük azt az ügyletet, amelyet a vállalat üzlethelyiségén kívül kötnek (pl. az ajtóban)?",a:["üzlethelyiségen kívül kötött szerződés","házaló kereskedelem","házalás"],e:"Az üzlethelyiségen kívül kötött szerződéseknél (pl. házalás) a fogyasztóknak elállási joguk van."}},{type:"text",level:2,de:{q:"Welches Gesetz schützt in Österreich Verbraucher:innen bei Geschäften mit Unternehmen ganz allgemein? (Abkürzung reicht)",a:["KSchG","Konsumentenschutzgesetz"],e:"Das KSchG (Konsumentenschutzgesetz) schützt Verbraucher:innen gegenüber Unternehmen."},en:{q:"Which Austrian law generally protects consumers in transactions with businesses? (The abbreviation is enough)",a:["KSchG","Consumer Protection Act"],e:"The KSchG (Consumer Protection Act) protects consumers against businesses."},hu:{q:"Melyik osztrák törvény védi általában a fogyasztókat a vállalkozásokkal kötött ügyletekben? (A rövidítés is elég)",a:["KSchG","fogyasztóvédelmi törvény"],e:"A KSchG (fogyasztóvédelmi törvény) védi a fogyasztókat a vállalkozásokkal szemben."}},{type:"number",level:3,value:12,tol:0,unit:{de:"Monate",en:"months",hu:"hónap"},de:{q:"Ein Onlineshop hat seine Kundin NICHT über ihr Rücktrittsrecht informiert. Um wie viele Monate verlängert sich dadurch die Rücktrittsfrist?",e:"Fehlt die Belehrung über das Rücktrittsrecht, verlängert sich die Frist um 12 Monate (FAGG). Wird die Information nachgeholt, beginnen ab dann 14 Tage."},en:{q:"An online shop did NOT inform its customer about her right of withdrawal. By how many months is the withdrawal period extended?",e:"If the information on the right of withdrawal is missing, the period is extended by 12 months (FAGG). If the information is given later, 14 days start from then."},hu:{q:"Egy webáruház NEM tájékoztatta vásárlóját az elállási jogáról. Hány hónappal hosszabbodik meg emiatt az elállási határidő?",e:"Ha hiányzik az elállási jogról szóló tájékoztatás, a határidő 12 hónappal meghosszabbodik (FAGG). Ha a tájékoztatást pótolják, attól kezdve 14 nap jár."}}]},n={"bestandteile-kaufvertrag":[{type:"text",level:1,de:{q:"Wie nennt man die Vereinbarung darüber, wer Kosten und Risiko des Transports trägt (z. B. „ab Werk“, „frei Haus“)?",a:["Lieferbedingung","Lieferbedingungen","Lieferklausel"],e:"Lieferbedingungen regeln, wer Transportkosten und -risiko trägt – z. B. „ab Werk“ (Käufer) oder „frei Haus“ (Verkäufer)."},en:{q:'What do you call the agreement on who bears the cost and risk of transport (e.g. "ex works", "free domicile")?',a:["delivery terms","terms of delivery","delivery conditions"],e:'Delivery terms regulate who bears transport costs and risk – e.g. "ex works" (buyer) or "free domicile" (seller).'},hu:{q:"Hogyan nevezzük azt a megállapodást, amely rögzíti, ki viseli a szállítás költségét és kockázatát (pl. „gyárból”, „házhoz szállítva”)?",a:["szállítási feltételek","szállítási feltétel","szállítási záradék"],e:"A szállítási feltételek szabályozzák, ki viseli a szállítás költségét és kockázatát."}},{type:"number",level:2,value:2352,tol:.01,unit:{de:"€",en:"€",hu:"€"},de:{q:"Eine Rechnung über 2.400 € gewährt 2 % Skonto bei Zahlung innerhalb von 10 Tagen. Wie viel zahlt Loopy, wenn sie das Skonto nutzt?",e:"Skonto = 2.400 · 2 % = 48 €. Zahlbetrag = 2.400 − 48 = 2.352 €."},en:{q:"An invoice of €2,400 offers a 2% cash discount for payment within 10 days. How much does Loopy pay if she uses the discount?",e:"Discount = 2,400 · 2% = €48. Amount to pay = 2,400 − 48 = €2,352."},hu:{q:"Egy 2400 €-s számla 10 napon belüli fizetés esetén 2% skontót ad. Mennyit fizet Loopy, ha él a skontóval?",e:"Skontó = 2400 · 2% = 48 €. Fizetendő = 2400 − 48 = 2352 €."}},{type:"number",level:3,value:4365,tol:.01,unit:{de:"€",en:"€",hu:"€"},de:{q:"Der Listenpreis beträgt 5.000 €. Loopy erhält 10 % Mengenrabatt und zahlt danach innerhalb der Skontofrist mit 3 % Skonto. Wie hoch ist der Zahlbetrag?",e:"Zuerst Rabatt: 5.000 − 10 % = 4.500 €. Dann Skonto vom verbilligten Preis: 4.500 − 3 % (135 €) = 4.365 €."},en:{q:"The list price is €5,000. Loopy gets a 10% quantity discount and then pays within the discount period with a 3% cash discount. How much does she pay?",e:"First the quantity discount: 5,000 − 10% = €4,500. Then the cash discount on the reduced price: 4,500 − 3% (€135) = €4,365."},hu:{q:"A listaár 5000 €. Loopy 10% mennyiségi engedményt kap, majd a skontóhatáridőn belül 3% skontóval fizet. Mennyi a fizetendő összeg?",e:"Először az engedmény: 5000 − 10% = 4500 €. Aztán a skontó a csökkentett árból: 4500 − 3% (135 €) = 4365 €."}}],"schriftverkehr-kaufvertrag":[{type:"text",level:1,de:{q:"Wie heißt das Schreiben, mit dem ein Verkäufer eine Bestellung schriftlich annimmt?",a:["Auftragsbestätigung","Bestellbestätigung"],e:"Mit der Auftragsbestätigung bestätigt der Verkäufer die Bestellung schriftlich."},en:{q:"What is the letter called with which a seller accepts an order in writing?",a:["order confirmation","confirmation of order","acknowledgement of order"],e:"With the order confirmation the seller confirms the order in writing."},hu:{q:"Hogyan nevezzük azt a levelet, amellyel az eladó írásban elfogadja a rendelést?",a:["rendelésvisszaigazolás","megrendelés-visszaigazolás","rendelés visszaigazolás"],e:"A rendelésvisszaigazolással az eladó írásban megerősíti a rendelést."}},{type:"text",level:2,de:{q:"Ein Lieferant bietet Kakao um 8 €/kg an. Loopy bestellt – aber zu 7 €/kg. Wie nennt man ihre Bestellung rechtlich?",a:["neues Angebot","Gegenangebot"],e:"Eine Bestellung mit geänderten Bedingungen ist keine Annahme, sondern ein neues Angebot (Gegenangebot). Erst wenn der Lieferant zustimmt, gibt es einen Vertrag."},en:{q:"A supplier offers cocoa at €8/kg. Loopy orders – but at €7/kg. What is her order legally?",a:["counter-offer","counter offer","new offer"],e:"An order with changed conditions is not an acceptance but a new offer (counter-offer). Only if the supplier agrees is there a contract."},hu:{q:"Egy beszállító 8 €/kg áron kínál kakaót. Loopy rendel – de 7 €/kg áron. Jogilag minek számít a rendelése?",a:["ellenajánlat","új ajánlat"],e:"A megváltoztatott feltételekkel leadott rendelés nem elfogadás, hanem új ajánlat (ellenajánlat). Csak ha a beszállító elfogadja, jön létre szerződés."}},{type:"mc",level:3,correctIndex:1,de:{q:"Ein Lieferant schickt Loopy per Brief ein Angebot ohne Annahmefrist. Wie lange ist er daran gebunden?",o:["Nur bis zum Ende des Tages, an dem der Brief beim Käufer ankommt","So lange, wie er normalerweise mit einer Antwort rechnen kann","Genau 14 Tage","Unbegrenzt, bis er das Angebot ausdrücklich schriftlich widerruft"],e:"Unter Abwesenden gilt ein Angebot ohne Frist so lange, wie der Anbieter unter normalen Umständen (Postweg, Überlegungszeit) mit einer Antwort rechnen darf."},en:{q:"A supplier sends Loopy an offer by letter without a deadline for acceptance. How long is he bound by it?",o:["Only until the end of the day the letter reaches the buyer","As long as he can normally expect an answer","Exactly 14 days","Indefinitely, until he expressly withdraws the offer in writing"],e:"Between absent parties an offer without a deadline is binding for as long as the offeror can normally expect an answer (postal time, time to think)."},hu:{q:"Egy beszállító levélben, elfogadási határidő nélkül küld ajánlatot Loopynak. Meddig kötik őt az ajánlata?",o:["Csak annak a napnak a végéig, amikor a levél megérkezik a vevőhöz","Addig, ameddig normális körülmények között választ várhat","Pontosan 14 napig","Korlátlanul, amíg kifejezetten írásban vissza nem vonja"],e:"Távollévők között a határidő nélküli ajánlat addig köt, ameddig az ajánlattevő normális körülmények között (postai út, gondolkodási idő) választ várhat."}}],"zahlungsformen-1jg":[{type:"text",level:1,de:{q:"Wie nennt man die Zahlung, bei der Geld von einem Bankkonto auf ein anderes übertragen wird?",a:["Überweisung","Banküberweisung"],e:"Bei der Überweisung wird Geld unbar von Konto zu Konto übertragen."},en:{q:"What do you call a payment where money is moved from one bank account to another?",a:["bank transfer","transfer","credit transfer"],e:"In a bank transfer money is moved cashless from account to account."},hu:{q:"Hogyan nevezzük azt a fizetést, amelynél a pénz egyik bankszámláról a másikra kerül?",a:["átutalás","banki átutalás"],e:"Átutalásnál a pénz készpénz nélkül kerül számláról számlára."}},{type:"text",level:2,de:{q:"Wie heißt die internationale Kontonummer, die man für Überweisungen im SEPA-Raum braucht? (Abkürzung)",a:["IBAN"],e:"Die IBAN (International Bank Account Number) identifiziert ein Konto eindeutig – in Österreich beginnt sie mit AT."},en:{q:"What is the international account number called that you need for transfers in the SEPA area? (Abbreviation)",a:["IBAN"],e:"The IBAN (International Bank Account Number) uniquely identifies an account – in Austria it starts with AT."},hu:{q:"Hogy hívják azt a nemzetközi számlaszámot, amely a SEPA-térségben az átutalásokhoz kell? (Rövidítés)",a:["IBAN"],e:"Az IBAN (nemzetközi bankszámlaszám) egyértelműen azonosít egy számlát – Ausztriában AT-vel kezdődik."}},{type:"mc",level:3,correctIndex:1,de:{q:"Loopy erlaubt ihrem Energieversorger, jeden Monat einen unterschiedlich hohen Betrag von ihrem Konto abzubuchen. Welche Zahlungsform ist das?",o:["Dauerauftrag","SEPA-Lastschrift","Überweisung per Online-Banking","Nachnahme"],e:"Bei der Lastschrift holt sich der Zahlungsempfänger den (auch wechselnden) Betrag. Ein Dauerauftrag überweist dagegen regelmäßig einen gleichbleibenden Betrag."},en:{q:"Loopy allows her energy supplier to debit a different amount from her account every month. Which form of payment is this?",o:["Standing order","SEPA direct debit","Bank transfer via online banking","Cash on delivery"],e:"With a direct debit the payee collects the (even changing) amount. A standing order, on the other hand, regularly transfers a fixed amount."},hu:{q:"Loopy megengedi az energiaszolgáltatójának, hogy havonta eltérő összeget terheljen a számlájára. Milyen fizetési forma ez?",o:["Állandó átutalási megbízás","SEPA beszedési megbízás","Átutalás netbankon keresztül","Utánvét"],e:"Beszedési megbízásnál a kedvezményezett szedi be a (változó) összeget. Az állandó átutalás viszont rendszeresen azonos összeget utal."}}],"unzuverlaessige-verkaeufer":[{type:"text",level:1,de:{q:"Wie nennt man es, wenn der Verkäufer nicht zum vereinbarten Termin liefert?",a:["Lieferverzug","Lieferungsverzug","Verzug"],e:"Liefert der Verkäufer nicht rechtzeitig, ist er im Lieferverzug."},en:{q:"What do you call it when the seller does not deliver on the agreed date?",a:["late delivery","delay in delivery","delivery delay","default in delivery"],e:"If the seller does not deliver on time, there is a delay in delivery (late delivery)."},hu:{q:"Hogyan nevezzük, ha az eladó nem a megbeszélt időpontban szállít?",a:["szállítási késedelem","késedelem","késedelmes szállítás"],e:"Ha az eladó nem szállít időben, szállítási késedelembe esik."}},{type:"number",level:2,value:2,tol:0,unit:{de:"Jahre",en:"years",hu:"év"},de:{q:"Wie lange dauert in Österreich die gesetzliche Gewährleistungsfrist für bewegliche Sachen?",e:"Für bewegliche Sachen gilt eine Gewährleistungsfrist von 2 Jahren ab Übergabe (für unbewegliche Sachen 3 Jahre)."},en:{q:"How long is the legal warranty period for movable goods in Austria?",e:"For movable goods the warranty period is 2 years from handover (3 years for immovable property)."},hu:{q:"Mennyi ideig tart Ausztriában a törvényes szavatossági idő ingó dolgoknál?",e:"Ingó dolgoknál a szavatossági idő az átadástól számított 2 év (ingatlanoknál 3 év)."}},{type:"mc",level:3,correctIndex:1,de:{q:"Ein Kunde reklamiert einen kaputten Mixer, der noch in der Gewährleistungsfrist ist. Was kann er grundsätzlich ZUERST verlangen?",o:["Preisminderung oder Wandlung (Vertragsauflösung)","Verbesserung (Reparatur) oder Austausch","Sofort Schadenersatz in Geld","Nur einen Gutschein"],e:"Zuerst gelten die primären Rechtsbehelfe Verbesserung oder Austausch. Erst wenn das nicht möglich ist oder scheitert: Preisminderung oder Wandlung."},en:{q:"A customer complains about a broken mixer that is still under warranty. What can he basically demand FIRST?",o:["Price reduction or cancellation of the contract","Repair or replacement","Immediate damages in money","Only a voucher"],e:"First the primary remedies apply: repair or replacement. Only if that is impossible or fails: price reduction or cancellation of the contract."},hu:{q:"Egy vevő reklamál egy elromlott mixer miatt, amely még szavatossági időn belül van. Mit követelhet alapvetően ELŐSZÖR?",o:["Árleszállítást vagy elállást (a szerződés felbontását)","Kijavítást vagy kicserélést","Azonnali kártérítést pénzben","Csak utalványt"],e:"Először az elsődleges szavatossági jogok érvényesek: kijavítás vagy kicserélés. Csak ha ez nem lehetséges vagy nem sikerül: árleszállítás vagy elállás."}}],"unzuverlaessige-kaeufer":[{type:"text",level:1,de:{q:"Wie nennt man eine schriftliche Zahlungserinnerung an einen Kunden, der nicht pünktlich zahlt?",a:["Mahnung","Zahlungserinnerung"],e:"Mit einer Mahnung wird der Kunde an die offene Zahlung erinnert."},en:{q:"What do you call a written payment reminder to a customer who does not pay on time?",a:["reminder","payment reminder","dunning letter"],e:"With a reminder the customer is reminded of the open payment."},hu:{q:"Hogyan nevezzük az írásos fizetési emlékeztetőt egy olyan vevőnek, aki nem fizet időben?",a:["fizetési felszólítás","felszólítás","fizetési emlékeztető"],e:"Fizetési felszólítással emlékeztetik a vevőt a nyitott tartozásra."}},{type:"text",level:2,de:{q:"Wie heißt der Verzug, wenn der Käufer die ordnungsgemäß gelieferte Ware nicht annimmt?",a:["Annahmeverzug"],e:"Nimmt der Käufer die richtige Ware zum richtigen Zeitpunkt nicht an, ist er im Annahmeverzug."},en:{q:"What is the default called when the buyer does not accept goods that were delivered properly?",a:["default of acceptance","acceptance default","delay in acceptance","default in acceptance"],e:"If the buyer does not accept the right goods at the right time, there is a default of acceptance."},hu:{q:"Hogyan nevezzük a késedelmet, ha a vevő nem veszi át a szabályosan leszállított árut?",a:["átvételi késedelem"],e:"Ha a vevő nem veszi át a megfelelő árut a megfelelő időben, átvételi késedelembe esik."}},{type:"number",level:3,value:184,tol:.5,unit:{de:"€",en:"€",hu:"€"},de:{q:"Ein Unternehmer zahlt Loopy eine Rechnung über 10.000 € um 73 Tage zu spät. Berechne die Verzugszinsen bei 9,2 % p. a. (Zinstage ÷ 365).",e:"Zinsen = Kapital · Zinssatz · Tage ÷ 365 = 10.000 · 0,092 · 73 ÷ 365 = 184 €."},en:{q:"A business pays Loopy an invoice of €10,000 73 days late. Calculate the default interest at 9.2% p.a. (interest days ÷ 365).",e:"Interest = capital · rate · days ÷ 365 = 10,000 · 0.092 · 73 ÷ 365 = €184."},hu:{q:"Egy vállalkozó 73 nap késéssel fizet ki Loopynak egy 10 000 €-s számlát. Számítsd ki a késedelmi kamatot évi 9,2%-kal (kamatnapok ÷ 365).",e:"Kamat = tőke · kamatláb · napok ÷ 365 = 10 000 · 0,092 · 73 ÷ 365 = 184 €."}}],rechtsdurchsetzung:[{type:"text",level:1,de:{q:"Wie heißt das vereinfachte gerichtliche Verfahren, mit dem Geldforderungen in Österreich eingetrieben werden?",a:["Mahnverfahren","gerichtliches Mahnverfahren"],e:"Im Mahnverfahren erlässt das Gericht einen Zahlungsbefehl, ohne zuerst zu verhandeln."},en:{q:"What is the simplified court procedure called that is used to collect money claims in Austria?",a:["payment order procedure","summary payment procedure","dunning procedure","order for payment procedure"],e:"In this procedure the court issues a payment order without a hearing first."},hu:{q:"Hogy hívják azt az egyszerűsített bírósági eljárást, amellyel Ausztriában pénzköveteléseket hajtanak be?",a:["fizetési meghagyásos eljárás","fizetési meghagyás"],e:"A fizetési meghagyásos eljárásban a bíróság tárgyalás nélkül bocsát ki fizetési meghagyást."}},{type:"text",level:2,de:{q:"Wie nennt man die zwangsweise Durchsetzung eines Anspruchs durch das Gericht, z. B. durch Pfändung?",a:["Exekution","Zwangsvollstreckung","Exekutionsverfahren"],e:"Zahlt der Schuldner trotz Urteil oder Zahlungsbefehl nicht, kann Exekution (Zwangsvollstreckung) beantragt werden."},en:{q:"What do you call the compulsory enforcement of a claim by the court, e.g. by seizing property?",a:["enforcement","execution","compulsory enforcement"],e:"If the debtor does not pay despite a judgment or payment order, enforcement can be applied for."},hu:{q:"Hogyan nevezzük egy követelés bíróság általi kényszerű érvényesítését, pl. lefoglalással?",a:["végrehajtás","bírósági végrehajtás"],e:"Ha az adós ítélet vagy fizetési meghagyás ellenére sem fizet, végrehajtást lehet kérni."}},{type:"number",level:3,value:4,tol:0,unit:{de:"Wochen",en:"weeks",hu:"hét"},de:{q:"Innerhalb wie vieler Wochen kann man in Österreich Einspruch gegen einen Zahlungsbefehl erheben?",e:"Gegen den Zahlungsbefehl kann innerhalb von 4 Wochen Einspruch erhoben werden – sonst wird er rechtskräftig und vollstreckbar."},en:{q:"Within how many weeks can you object to a payment order in Austria?",e:"An objection to the payment order can be raised within 4 weeks – otherwise it becomes final and enforceable."},hu:{q:"Hány héten belül lehet Ausztriában ellentmondással élni egy fizetési meghagyás ellen?",e:"A fizetési meghagyás ellen 4 héten belül lehet ellentmondással élni – különben jogerőssé és végrehajthatóvá válik."}}],"unternehmensgruendung-schritte":[{type:"text",level:1,de:{q:"Wie nennt man die Berechtigung, ein Gewerbe auszuüben, die man durch die Gewerbeanmeldung erhält?",a:["Gewerbeberechtigung","Gewerbeschein"],e:"Mit der Gewerbeanmeldung erhält man die Gewerbeberechtigung (früher „Gewerbeschein“)."},en:{q:"What do you call the right to run a trade that you get by registering the trade?",a:["trade licence","trade license","business licence","business license"],e:"By registering the trade you receive the trade licence."},hu:{q:"Hogyan nevezzük az ipar gyakorlására szóló jogosultságot, amelyet az iparbejelentéssel kapunk?",a:["iparjogosultság","ipari jogosultság","iparengedély"],e:"Az iparbejelentéssel megkapjuk az iparjogosultságot."}},{type:"text",level:2,de:{q:"In welcher Interessenvertretung sind alle Gewerbetreibenden in Österreich automatisch Mitglied? (Abkürzung reicht)",a:["WKO","Wirtschaftskammer","Wirtschaftskammer Österreich"],e:"Mit der Gewerbeberechtigung wird man automatisch Mitglied der Wirtschaftskammer (WKO)."},en:{q:"Which representative body are all traders in Austria automatically members of? (Abbreviation is enough)",a:["WKO","Chamber of Commerce","Austrian Economic Chambers","Austrian Chamber of Commerce"],e:"With the trade licence you automatically become a member of the Chamber of Commerce (WKO)."},hu:{q:"Melyik érdekképviseletnek tagja automatikusan minden iparűző Ausztriában? (A rövidítés is elég)",a:["WKO","gazdasági kamara","osztrák gazdasági kamara"],e:"Az iparjogosultsággal automatikusan a gazdasági kamara (WKO) tagja leszel."}},{type:"mc",level:3,correctIndex:1,de:{q:"Loopy will als Konditorin selbst Torten herstellen und verkaufen. Welche Art von Gewerbe ist das und was braucht sie dafür?",o:["Freies Gewerbe – nur die Anmeldung","Reglementiertes Gewerbe – einen Befähigungsnachweis","Freies Gewerbe – eine Konzession","Gar kein Gewerbe – nur eine Steuernummer beim Finanzamt"],e:"Konditor ist ein reglementiertes Gewerbe (Handwerk). Man muss die Befähigung nachweisen, z. B. durch Meisterprüfung oder einschlägige Ausbildung und Praxis."},en:{q:"Loopy wants to make and sell cakes herself as a confectioner. What kind of trade is this and what does she need?",o:["Free trade – only registration","Regulated trade – proof of qualification","Free trade – a concession","No trade at all – only a tax number from the tax office"],e:"Confectioner is a regulated trade (craft). You have to prove your qualification, e.g. with a master craftsman's examination or relevant training and experience."},hu:{q:"Loopy cukrászként maga szeretne tortákat készíteni és eladni. Milyen iparról van szó, és mire van szüksége?",o:["Szabad ipar – csak bejelentés","Szabályozott ipar – képesítés igazolása","Szabad ipar – koncesszió","Egyáltalán nem ipar – csak adószám az adóhivataltól"],e:"A cukrász szabályozott ipar (kézműipar). Igazolni kell a képesítést, pl. mestervizsgával vagy szakirányú képzéssel és gyakorlattal."}}],"wahl-der-rechtsform-1jg":[{type:"text",level:1,de:{q:"Wie heißt die Rechtsform, bei der eine einzelne Person das Unternehmen allein führt und mit ihrem gesamten Vermögen haftet?",a:["Einzelunternehmen","Einzelunternehmer","Einzelunternehmung"],e:"Beim Einzelunternehmen führt eine Person das Unternehmen allein und haftet unbeschränkt mit ihrem Privatvermögen."},en:{q:"What is the legal form called where a single person runs the business alone and is liable with all their assets?",a:["sole proprietorship","sole trader","sole proprietor"],e:"In a sole proprietorship one person runs the business alone and is liable without limit with their private assets."},hu:{q:"Hogy hívják azt a jogi formát, amelyben egyetlen személy egyedül vezeti a vállalkozást, és teljes vagyonával felel?",a:["egyéni vállalkozás","egyéni vállalkozó","egyéni cég"],e:"Egyéni vállalkozásnál egy személy egyedül vezeti a vállalkozást, és korlátlanul felel a magánvagyonával."}},{type:"number",level:2,value:2,tol:0,unit:{de:"Personen",en:"persons",hu:"fő"},de:{q:"Wie viele Gesellschafter braucht man mindestens, um eine OG (offene Gesellschaft) zu gründen?",e:"Eine OG braucht mindestens 2 Gesellschafter, die alle unbeschränkt haften."},en:{q:"What is the minimum number of partners needed to found an OG (general partnership)?",e:"An OG needs at least 2 partners, all of whom are liable without limit."},hu:{q:"Legalább hány tag kell egy OG (közkereseti társaság) alapításához?",e:"Egy OG-hez legalább 2 tag kell, akik mind korlátlanul felelnek."}},{type:"mc",level:3,correctIndex:1,de:{q:"Bei welcher Rechtsform gibt es mindestens einen unbeschränkt haftenden (Komplementär) und mindestens einen beschränkt haftenden Gesellschafter (Kommanditist)?",o:["OG","KG","GmbH","Einzelunternehmen"],e:"Die KG hat zwei Arten von Gesellschaftern: Komplementäre haften unbeschränkt, Kommanditisten nur bis zur Höhe ihrer Einlage."},en:{q:"Which legal form has at least one partner with unlimited liability (general partner) and at least one with limited liability (limited partner)?",o:["OG","KG","GmbH","Sole proprietorship"],e:"A KG has two kinds of partners: general partners are liable without limit, limited partners only up to their contribution."},hu:{q:"Melyik jogi formában van legalább egy korlátlanul felelős (beltag) és legalább egy korlátozottan felelős (kültag) tag?",o:["OG","KG","GmbH","Egyéni vállalkozás"],e:"A KG-ban kétféle tag van: a beltagok korlátlanul, a kültagok csak a betétjük erejéig felelnek."}}],"businessplan-1jg":[{type:"text",level:1,de:{q:"Wie heißt die kurze Zusammenfassung ganz am Anfang eines Businessplans? (englischer Begriff)",a:["Executive Summary"],e:"Die Executive Summary fasst den ganzen Businessplan auf 1–2 Seiten zusammen – sie wird oft als Erstes gelesen."},en:{q:"What is the short summary at the very beginning of a business plan called?",a:["executive summary"],e:"The executive summary summarises the whole business plan on 1–2 pages – it is often read first."},hu:{q:"Hogy hívják az üzleti terv legelején álló rövid összefoglalót?",a:["vezetői összefoglaló","executive summary"],e:"A vezetői összefoglaló 1–2 oldalon foglalja össze az egész üzleti tervet – gyakran ezt olvassák el először."}},{type:"text",level:2,de:{q:"Wie nennt man das Alleinstellungsmerkmal eines Produkts, das es von der Konkurrenz abhebt? (Abkürzung)",a:["USP","Unique Selling Proposition","Alleinstellungsmerkmal"],e:"Die USP (Unique Selling Proposition) ist das, was das Angebot einzigartig macht."},en:{q:"What do you call the unique feature of a product that sets it apart from the competition? (Abbreviation)",a:["USP","unique selling proposition","unique selling point"],e:"The USP (unique selling proposition) is what makes the offer unique."},hu:{q:"Hogyan nevezzük egy termék egyedi jellemzőjét, amely kiemeli a versenytársak közül? (Rövidítés)",a:["USP","egyedi értékesítési ajánlat"],e:"Az USP (egyedi értékesítési ajánlat) az, ami egyedivé teszi az ajánlatot."}},{type:"number",level:3,value:2500,tol:0,unit:{de:"Stück",en:"pcs",hu:"db"},de:{q:"Loopy hat 6.000 € Fixkosten pro Monat. Eine Packung Pralinen kostet 4 €, die variablen Kosten betragen 1,60 € pro Packung. Ab wie vielen Packungen pro Monat macht sie keinen Verlust mehr (Break-even)?",e:"Deckungsbeitrag pro Packung = 4,00 − 1,60 = 2,40 €. Break-even-Menge = 6.000 ÷ 2,40 = 2.500 Packungen."},en:{q:"Loopy has €6,000 fixed costs per month. A box of chocolates costs €4 and variable costs are €1.60 per box. From how many boxes per month does she stop making a loss (break-even)?",e:"Contribution margin per box = 4.00 − 1.60 = €2.40. Break-even quantity = 6,000 ÷ 2.40 = 2,500 boxes."},hu:{q:"Loopy fix költsége havi 6000 €. Egy doboz bonbon 4 €, a változó költség dobozonként 1,60 €. Havi hány doboztól nem termel már veszteséget (fedezeti pont)?",e:"Fedezeti hozzájárulás dobozonként = 4,00 − 1,60 = 2,40 €. Fedezeti mennyiség = 6000 ÷ 2,40 = 2500 doboz."}}],"vertraege-mitarbeiter":[{type:"text",level:1,de:{q:"Wie nennt man den Vertrag, in dem Arbeitgeber und Arbeitnehmer:in das Arbeitsverhältnis vereinbaren?",a:["Arbeitsvertrag","Dienstvertrag"],e:"Im Arbeitsvertrag (Dienstvertrag) werden u. a. Tätigkeit, Arbeitszeit und Entgelt vereinbart."},en:{q:"What is the contract called in which employer and employee agree on the employment relationship?",a:["employment contract","contract of employment","work contract"],e:"In the employment contract things like the job, working hours and pay are agreed."},hu:{q:"Hogyan nevezzük azt a szerződést, amelyben a munkáltató és a munkavállaló megállapodik a munkaviszonyról?",a:["munkaszerződés"],e:"A munkaszerződésben többek között a tevékenységet, a munkaidőt és a bért rögzítik."}},{type:"text",level:2,de:{q:"Wie heißt der Vertrag, den die Sozialpartner für eine ganze Branche abschließen (z. B. mit Mindestlöhnen)?",a:["Kollektivvertrag","KV"],e:"Der Kollektivvertrag gilt für eine ganze Branche und regelt z. B. Mindestlöhne, Sonderzahlungen und Arbeitszeit."},en:{q:"What is the contract called that the social partners conclude for a whole industry (e.g. with minimum wages)?",a:["collective agreement","collective bargaining agreement"],e:"The collective agreement applies to a whole industry and regulates e.g. minimum wages, special payments and working hours."},hu:{q:"Hogy hívják azt a szerződést, amelyet a szociális partnerek egy egész ágazatra kötnek (pl. minimálbérekkel)?",a:["kollektív szerződés"],e:"A kollektív szerződés egy egész ágazatra érvényes, és szabályozza pl. a minimálbéreket, a különjuttatásokat és a munkaidőt."}},{type:"mc",level:3,correctIndex:2,de:{q:"Ein Grafiker soll für Loopy bis 1. Mai ein fertiges Logo liefern. Er arbeitet selbstständig, mit eigenen Mitteln und schuldet ein bestimmtes Ergebnis. Welcher Vertrag liegt vor?",o:["Dienstvertrag","Freier Dienstvertrag","Werkvertrag","Lehrvertrag"],e:"Beim Werkvertrag schuldet man ein bestimmtes Ergebnis (das Werk). Beim (freien) Dienstvertrag schuldet man dagegen die Arbeitsleistung über eine Zeit."},en:{q:"A graphic designer is to deliver a finished logo to Loopy by 1 May. He works independently, with his own equipment, and owes a specific result. Which contract is this?",o:["Employment contract","Freelance service contract","Contract for work","Apprenticeship contract"],e:"In a contract for work you owe a specific result (the work). In a (freelance) service contract you owe work over a period of time instead."},hu:{q:"Egy grafikusnak május 1-jéig kész logót kell átadnia Loopynak. Önállóan, saját eszközeivel dolgozik, és meghatározott eredménnyel tartozik. Milyen szerződésről van szó?",o:["Munkaszerződés","Szabad szolgáltatási szerződés","Vállalkozási szerződés","Tanulószerződés"],e:"Vállalkozási szerződésnél meghatározott eredménnyel (a művel) tartozik az ember. A (szabad) szolgáltatási szerződésnél viszont egy időszakon át végzett munkával."}}]},a={"grundlagen-des-wirtschaftens":[{type:"tf",level:1,correct:!1,de:{q:"Dienstleistungen kann man genauso wie Sachgüter auf Vorrat produzieren und lagern",e:"Falsch. Dienstleistungen sind immateriell und nicht lagerbar: Ein Haarschnitt entsteht erst in dem Moment, in dem er erbracht wird. Lagern und transportieren kann man nur Sachgüter."},en:{q:"Services can be produced in advance and stored just like physical goods",e:"False. Services are intangible and cannot be stored: a haircut only comes into being at the moment it is provided. Only physical goods can be stored and transported."},hu:{q:"A szolgáltatásokat ugyanúgy előre el lehet készíteni és raktározni, mint a tárgyi javakat",e:"Hamis. A szolgáltatások nem anyagiak, és nem raktározhatók: egy hajvágás csak abban a pillanatban jön létre, amikor elvégzik. Raktározni és szállítani csak a tárgyi javakat lehet."}},{type:"tf",level:2,correct:!1,de:{q:"Ob ein Gut ein Konsumgut oder ein Investitionsgut ist, hängt allein davon ab, um welchen Gegenstand es sich handelt",e:"Falsch. Entscheidend ist, WER das Gut WOFÜR verwendet: Ein Auto ist für eine Familie ein Konsumgut, für einen Pizzalieferdienst ein Investitionsgut."},en:{q:"Whether a good is a consumer good or a capital good depends only on what kind of object it is",e:"False. What matters is WHO uses the good and FOR WHAT: a car is a consumer good for a family but a capital good for a pizza delivery service."},hu:{q:"Az, hogy egy jószág fogyasztási vagy beruházási jószág-e, kizárólag attól függ, milyen tárgyról van szó",e:"Hamis. Az a döntő, hogy KI és MIRE használja: egy autó egy családnak fogyasztási jószág, egy pizzafutár-szolgálatnak viszont beruházási jószág."}},{type:"tf",level:3,correct:!0,de:{q:"Ein freies Gut kann zu einem Wirtschaftsgut werden, wenn es knapp wird",e:"Richtig. Freie Güter sind nur so lange gratis, wie sie unbegrenzt vorhanden sind. Wird z. B. sauberes Trinkwasser in einer Region knapp, bekommt es einen Preis und wird zum Wirtschaftsgut – je knapper, desto teurer."},en:{q:"A free good can become an economic good if it becomes scarce",e:"True. Free goods are only free as long as they are available without limit. If, for example, clean drinking water becomes scarce in a region, it gets a price and becomes an economic good – the scarcer, the more expensive."},hu:{q:"Egy szabad jószág gazdasági jószággá válhat, ha szűkössé válik",e:"Igaz. A szabad javak csak addig ingyenesek, amíg korlátlanul rendelkezésre állnak. Ha például egy térségben szűkössé válik a tiszta ivóvíz, ára lesz, és gazdasági jószággá válik – minél szűkösebb, annál drágább."}},{type:"multi",level:2,correct:[0,2,4],de:{q:"Welche der folgenden Güter sind Investitionsgüter? Wähle alle zutreffenden aus.",o:["Die Kühlvitrine in Loopys Candy Store","Pralinen, die eine Kundin zu Hause isst","Der Lieferwagen einer Bäckerei","Ein Laptop, mit dem ein Schüler privat Serien schaut","Das Bürogebäude einer Versicherung"],e:"Investitionsgüter verwendet ein Unternehmen, um Leistungen zu erstellen (Vitrine, Lieferwagen, Bürogebäude). Die gegessenen Pralinen und der privat genutzte Laptop dienen dem Endverbrauch – sie sind Konsumgüter."},en:{q:"Which of the following goods are capital goods? Select all that apply.",o:["The refrigerated display case in Loopy's Candy Store","Chocolates a customer eats at home","A bakery's delivery van","A laptop a student uses privately to watch series","An insurance company's office building"],e:"Capital goods are used by a business to produce its output (display case, delivery van, office building). The chocolates eaten and the privately used laptop serve final consumption – they are consumer goods."},hu:{q:"Az alábbi javak közül melyek beruházási javak? Jelöld meg az összes helyeset.",o:["A hűtővitrin Loopy édességboltjában","A bonbon, amelyet egy vásárló otthon megeszik","Egy pékség kisteherautója","Egy laptop, amelyen egy diák magáncélra sorozatokat néz","Egy biztosító irodaháza"],e:"Beruházási javakat egy vállalkozás a teljesítménye előállítására használ (vitrin, kisteherautó, irodaház). A megevett bonbon és a magáncélra használt laptop a végső fogyasztást szolgálja – ezek fogyasztási javak."}},{type:"multi",level:3,correct:[0,1,3],de:{q:"Welche Aussagen zum Wirtschaftskreislauf treffen zu? Wähle alle zutreffenden aus.",o:["Haushalte stellen den Unternehmen Arbeitskraft zur Verfügung und erhalten dafür Einkommen.","Banken nehmen Ersparnisse an und vergeben Kredite an Unternehmen und Haushalte.","Schon im einfachen Wirtschaftskreislauf sind Banken und Staat enthalten.","Der Staat nimmt Steuern ein und zahlt z. B. Subventionen an Unternehmen.","Haushalte zahlen den Banken Zinsen dafür, dass diese ihr Erspartes aufbewahren."],e:"Der einfache Kreislauf zeigt nur Unternehmen ↔ Haushalte; Banken kommen im erweiterten, der Staat erst im vollständigen Kreislauf dazu. Für Ersparnisse BEKOMMEN Haushalte Zinsen von der Bank – Zinsen zahlt, wer einen Kredit aufnimmt."},en:{q:"Which statements about the circular flow of the economy are correct? Select all that apply.",o:["Households provide businesses with labour and receive income in return.","Banks accept savings and grant loans to businesses and households.","The simple circular flow already includes banks and the state.","The state collects taxes and pays, for example, subsidies to businesses.","Households pay banks interest for keeping their savings."],e:"The simple circular flow only shows businesses ↔ households; banks are added in the extended model and the state only in the complete one. Households RECEIVE interest on savings – interest is paid by whoever takes out a loan."},hu:{q:"Mely állítások igazak a gazdasági körforgásra? Jelöld meg az összes helyeset.",o:["A háztartások munkaerőt biztosítanak a vállalkozásoknak, és ezért jövedelmet kapnak.","A bankok befogadják a megtakarításokat, és hitelt nyújtanak vállalkozásoknak és háztartásoknak.","Már az egyszerű gazdasági körforgásban is szerepelnek a bankok és az állam.","Az állam adókat szed be, és például támogatásokat fizet a vállalkozásoknak.","A háztartások kamatot fizetnek a bankoknak azért, hogy megőrzik a megtakarításaikat."],e:"Az egyszerű körforgás csak a vállalkozások ↔ háztartások kapcsolatot mutatja; a bankok a bővített, az állam csak a teljes modellben jelenik meg. A megtakarításaik után a háztartások KAPNAK kamatot – kamatot az fizet, aki hitelt vesz fel."}},{type:"order",level:1,de:{q:"Ordne die Stufen der Maslowschen Bedürfnispyramide von unten (dringendste) nach oben.",o:["Grundbedürfnisse","Sicherheit","Soziale Bedürfnisse","Anerkennung","Selbstverwirklichung"],e:"Zuerst müssen die Grundbedürfnisse (Essen, Trinken, Schlafen) erfüllt sein, dann folgen Sicherheit, soziale Bedürfnisse, Anerkennung und ganz oben die Selbstverwirklichung."},en:{q:"Put the levels of Maslow's hierarchy of needs in order from the bottom (most urgent) to the top.",o:["Basic needs","Safety","Social needs","Esteem","Self-actualisation"],e:"Basic needs (food, drink, sleep) must be met first, followed by safety, social needs, esteem and, at the very top, self-actualisation."},hu:{q:"Rendezd sorba a Maslow-féle szükségleti piramis szintjeit alulról (legsürgetőbb) felfelé.",o:["Alapvető szükségletek","Biztonság","Társas szükségletek","Elismerés","Önmegvalósítás"],e:"Először az alapvető szükségleteket (evés, ivás, alvás) kell kielégíteni, ezt követi a biztonság, a társas szükségletek, az elismerés, és legfelül az önmegvalósítás."}},{type:"match",level:2,de:{q:"Ordne jedes Beispiel der passenden Güterart zu.",p:[["Sonnenlicht","Freies Gut"],["Haarschnitt beim Friseur","Personenbezogene Dienstleistung"],["Reparatur eines Fahrrads","Sachbezogene Dienstleistung"],["Nähmaschine in einer Schneiderei","Investitionsgut"],["Schokolade zum Naschen","Konsumgut"]],e:"Sonnenlicht ist unbegrenzt und gratis. Dienstleistungen werden an einem Menschen (Haarschnitt) oder an einer Sache (Fahrradreparatur) erbracht. Die Nähmaschine dient der Herstellung, die Schokolade dem Verbrauch."},en:{q:"Match each example to the correct type of good.",p:[["Sunlight","Free good"],["A haircut at the hairdresser's","Person-related service"],["Repairing a bicycle","Object-related service"],["Sewing machine in a tailor's shop","Capital good"],["Chocolate as a snack","Consumer good"]],e:"Sunlight is unlimited and free. Services are performed on a person (haircut) or on an object (bike repair). The sewing machine is used for production, the chocolate for consumption."},hu:{q:"Párosítsd az egyes példákat a megfelelő jószágtípussal.",p:[["Napfény","Szabad jószág"],["Hajvágás a fodrásznál","Személyhez kötött szolgáltatás"],["Egy kerékpár javítása","Tárgyhoz kötött szolgáltatás"],["Varrógép egy szabóműhelyben","Beruházási jószág"],["Csokoládé nassolásra","Fogyasztási jószág"]],e:"A napfény korlátlan és ingyenes. A szolgáltatást egy emberen (hajvágás) vagy egy tárgyon (kerékpárjavítás) végzik. A varrógép termelésre szolgál, a csokoládé fogyasztásra."}},{type:"mc",level:2,correctIndex:2,de:{q:"Ein Taxiunternehmer aus Graz kauft einen neuen Kombi, um damit Fahrgäste zu befördern. Seine Nachbarin kauft genau dasselbe Modell für Familienausflüge. Wie sind die beiden Autos einzuordnen?",o:["Beide sind Konsumgüter, weil es dasselbe Modell ist","Beide sind Investitionsgüter, weil Autos langlebig sind","Taxi: Investitionsgut – Auto der Nachbarin: Konsumgut","Taxi: Konsumgut – Auto der Nachbarin: Investitionsgut"],e:"Der Unternehmer erstellt mit dem Auto seine Leistung (Fahrten) – Investitionsgut. Die Nachbarin nutzt es privat – Konsumgut. Dass das Modell gleich ist oder lange hält, spielt keine Rolle."},en:{q:"A taxi operator from Graz buys a new estate car to transport passengers. His neighbour buys exactly the same model for family trips. How should the two cars be classified?",o:["Both are consumer goods because it is the same model","Both are capital goods because cars are durable","Taxi: capital good – neighbour's car: consumer good","Taxi: consumer good – neighbour's car: capital good"],e:"The operator uses the car to produce his service (rides) – capital good. The neighbour uses it privately – consumer good. The fact that it is the same model or lasts long is irrelevant."},hu:{q:"Egy grazi taxis vállalkozó új kombit vásárol utasszállításra. A szomszédja pontosan ugyanezt a modellt veszi meg családi kirándulásokhoz. Hogyan kell besorolni a két autót?",o:["Mindkettő fogyasztási jószág, mert ugyanaz a modell","Mindkettő beruházási jószág, mert az autó tartós","Taxi: beruházási jószág – a szomszéd autója: fogyasztási jószág","Taxi: fogyasztási jószág – a szomszéd autója: beruházási jószág"],e:"A vállalkozó az autóval állítja elő a szolgáltatását (fuvarok) – beruházási jószág. A szomszéd magáncélra használja – fogyasztási jószág. Az, hogy ugyanaz a modell vagy sokáig tart, nem számít."}},{type:"mc",level:3,correctIndex:1,de:{q:"Der Geschäftsführer einer Tischlerei sagt in einer Besprechung: „Wir wollen mit möglichst geringen Kosten möglichst viele Möbel herstellen.“ Wie ist diese Zielformulierung zu beurteilen?",o:["Sie beschreibt das Maximalprinzip, weil viel produziert wird","Sie ist so nicht umsetzbar, weil eine Größe fix sein muss","Sie beschreibt das Minimalprinzip, weil Kosten gering sind","Sie ist das Wirtschaftlichkeitsprinzip in seiner Idealform"],e:"Beim Wirtschaftlichkeitsprinzip muss immer eine Größe fix sein: entweder das Ziel (Minimalprinzip) oder der Einsatz (Maximalprinzip). Beides gleichzeitig zu optimieren ist unlogisch – null Kosten und unendlich viele Möbel gibt es nicht."},en:{q:"In a meeting, the managing director of a joinery says: “We want to make as much furniture as possible at the lowest possible cost.” How should this goal be assessed?",o:["It describes the maximum principle because a lot is produced","It cannot be put into practice because one quantity must be fixed","It describes the minimum principle because costs are low","It is the economic principle in its ideal form"],e:"With the economic principle, one quantity must always be fixed: either the goal (minimum principle) or the input (maximum principle). Optimising both at once is illogical – zero costs and unlimited furniture do not exist."},hu:{q:"Egy asztalosüzem ügyvezetője egy megbeszélésen ezt mondja: „A lehető legkisebb költséggel a lehető legtöbb bútort akarjuk gyártani.” Hogyan értékelhető ez a célmegfogalmazás?",o:["A maximumelvet írja le, mert sokat gyártanak","Nem megvalósítható, mert egy tényezőnek fixnek kell lennie","A minimumelvet írja le, mert a költségek alacsonyak","Ez a gazdaságossági elv ideális formája"],e:"A gazdaságossági elvnél mindig az egyik tényezőnek rögzítettnek kell lennie: vagy a cél (minimumelv), vagy a ráfordítás (maximumelv). Mindkettőt egyszerre optimalizálni logikátlan – nulla költség és végtelen sok bútor nem létezik."}},{type:"text",level:1,de:{q:"Wie nennt man Geld, mit dem der Staat Unternehmen für einen bestimmten Zweck unterstützt (z. B. Förderung für Photovoltaik)?",a:["Subvention","Subventionen","Förderung","Förderungen"],e:"Subventionen sind zweckgebundene Zahlungen des Staates an Unternehmen, etwa für Forschung oder Photovoltaik. Steuern fließen dagegen in die umgekehrte Richtung – vom Unternehmen zum Staat."},en:{q:"What do you call money with which the state supports businesses for a specific purpose (e.g. funding for solar panels)?",a:["subsidy","subsidies","grant","grants","state aid"],e:"Subsidies are earmarked payments from the state to businesses, e.g. for research or solar power. Taxes flow the other way – from businesses to the state."},hu:{q:"Hogyan nevezzük azt a pénzt, amellyel az állam egy meghatározott célra támogatja a vállalkozásokat (pl. napelemes támogatás)?",a:["támogatás","támogatások","szubvenció","szubvenciók","állami támogatás"],e:"A támogatások (szubvenciók) az állam célhoz kötött kifizetései a vállalkozásoknak, például kutatásra vagy napenergiára. Az adók fordított irányba áramlanak – a vállalkozástól az államhoz."}}],"der-markt":[{type:"tf",level:1,correct:!0,de:{q:"Der Arbeitsmarkt zählt zu den Faktormärkten",e:"Richtig. Faktormärkte sind Märkte für Produktionsfaktoren: Arbeit (Arbeitsmarkt), Boden (Immobilienmarkt) und Kapital (Kapitalmarkt)."},en:{q:"The labour market is one of the factor markets",e:"True. Factor markets are markets for factors of production: labour (labour market), land (real estate market) and capital (capital market)."},hu:{q:"A munkaerőpiac a tényezőpiacok közé tartozik",e:"Igaz. A tényezőpiacok a termelési tényezők piacai: munka (munkaerőpiac), föld (ingatlanpiac) és tőke (tőkepiac)."}},{type:"tf",level:2,correct:!0,de:{q:"Auch in der ökosozialen Marktwirtschaft bilden sich die Preise grundsätzlich durch Angebot und Nachfrage",e:"Richtig. Wie in der freien Marktwirtschaft entsteht der Preis am Markt; der Staat greift aber zusätzlich sozial und ökologisch ein (z. B. Familienbeihilfe, Umweltgesetze). Nur in der Planwirtschaft bestimmt der Staat die Preise."},en:{q:"In the eco-social market economy, prices are also basically formed by supply and demand",e:"True. As in the free market economy, the price is formed on the market; however, the state also intervenes socially and ecologically (e.g. family allowance, environmental laws). Only in a planned economy does the state set prices."},hu:{q:"Az ökoszociális piacgazdaságban is alapvetően a kereslet és a kínálat alakítja ki az árakat",e:"Igaz. A szabad piacgazdasághoz hasonlóan az ár a piacon alakul ki, de az állam emellett szociális és ökológiai szempontból is beavatkozik (pl. családi pótlék, környezetvédelmi törvények). Csak a tervgazdaságban határozza meg az állam az árakat."}},{type:"tf",level:3,correct:!1,de:{q:"Liegt der Marktpreis über dem Gleichgewichtspreis, entsteht ein Nachfrageüberschuss",e:"Falsch. Bei einem zu hohen Preis bieten die Verkäufer:innen mehr an (Angebotsgesetz) und die Käufer:innen fragen weniger nach (Nachfragegesetz) – es entsteht ein Angebotsüberschuss. Ein Nachfrageüberschuss entsteht bei einem Preis UNTER dem Gleichgewichtspreis."},en:{q:"If the market price is above the equilibrium price, there is excess demand",e:"False. At a price that is too high, sellers offer more (law of supply) and buyers demand less (law of demand) – this creates excess supply. Excess demand arises at a price BELOW the equilibrium price."},hu:{q:"Ha a piaci ár az egyensúlyi ár felett van, keresleti többlet keletkezik",e:"Hamis. Túl magas árnál az eladók többet kínálnak (kínálati törvény), a vevők kevesebbet keresnek (keresleti törvény) – kínálati többlet keletkezik. Keresleti többlet az egyensúlyi ár ALATTI árnál alakul ki."}},{type:"multi",level:1,correct:[0,2,4],de:{q:"Welche Faktoren beeinflussen den Preis auf der Seite der Käufer:innen? Wähle alle zutreffenden aus.",o:["Einkommen","Produktionskosten","Nutzen des Gutes","Preise der Konkurrenz","Dringender Bedarf (z. B. Medikamente)","Technologie"],e:"Käufer:innen zahlen umso eher einen Preis, je höher ihr Einkommen, der Nutzen des Gutes oder die Dringlichkeit ist. Produktionskosten, Konkurrenzpreise und Technologie wirken auf der Seite der Verkäufer:innen."},en:{q:"Which factors influence the price on the buyers' side? Select all that apply.",o:["Income","Production costs","Usefulness of the good","Competitors' prices","Urgent need (e.g. medicines)","Technology"],e:"Buyers are more willing to pay a price the higher their income, the usefulness of the good or the urgency. Production costs, competitors' prices and technology act on the sellers' side."},hu:{q:"Mely tényezők befolyásolják az árat a vevők oldalán? Jelöld meg az összes helyeset.",o:["Jövedelem","Termelési költségek","A jószág hasznossága","A versenytársak árai","Sürgős szükséglet (pl. gyógyszerek)","Technológia"],e:"A vevők annál inkább hajlandók megfizetni egy árat, minél magasabb a jövedelmük, a jószág hasznossága vagy a szükséglet sürgőssége. A termelési költségek, a versenytársak árai és a technológia az eladók oldalán hatnak."}},{type:"multi",level:2,correct:[0,1,3],de:{q:"Welche Merkmale gehören zur freien Marktwirtschaft? Wähle alle zutreffenden aus.",o:["Privateigentum an Produktionsfaktoren","Freie Berufs- und Arbeitsplatzwahl","Der Staat legt die Preise in einem Gesamtplan fest","Der Staat gibt nur den rechtlichen Rahmen vor","Soziale Steuerung, z. B. durch Familienbeihilfe"],e:"In der freien Marktwirtschaft plant jede:r selbst, es gibt Privateigentum und freie Berufswahl, der Staat setzt nur den Rahmen. Der Gesamtplan gehört zur Planwirtschaft, die soziale Steuerung zur (öko-)sozialen Marktwirtschaft."},en:{q:"Which features belong to the free market economy? Select all that apply.",o:["Private ownership of the factors of production","Free choice of occupation and workplace","The state sets prices in an overall plan","The state only sets the legal framework","Social steering, e.g. through family allowance"],e:"In the free market economy everyone plans for themselves, there is private property and free choice of occupation, and the state only sets the framework. The overall plan belongs to the planned economy, social steering to the (eco-)social market economy."},hu:{q:"Mely jellemzők tartoznak a szabad piacgazdasághoz? Jelöld meg az összes helyeset.",o:["A termelési tényezők magántulajdona","A foglalkozás és a munkahely szabad megválasztása","Az állam egy központi tervben határozza meg az árakat","Az állam csak a jogi kereteket szabja meg","Szociális irányítás, pl. családi pótlékkal"],e:"A szabad piacgazdaságban mindenki maga tervez, van magántulajdon és szabad pályaválasztás, az állam csak a kereteket adja meg. A központi terv a tervgazdasághoz, a szociális irányítás az (öko)szociális piacgazdasághoz tartozik."}},{type:"order",level:2,de:{q:"Bringe die Stufen der vertikalen Arbeitsteilung bei der Herstellung einer Jeans in die richtige Reihenfolge.",o:["Baumwolle anbauen und ernten","Baumwolle zur Spinnerei transportieren","Garn spinnen und Stoff weben","Jeans in der Kleiderfabrik nähen","Jeans im Einzelhandel an Kund:innen verkaufen"],e:"Bei der vertikalen Arbeitsteilung arbeiten Firmen auf verschiedenen Stufen nacheinander am selben Produkt: Urproduktion → Dienstleistung (Transport) → Produktion (Spinnerei, Weberei, Kleiderfabrik) → Dienstleistung (Einzelhandel)."},en:{q:"Put the stages of the vertical division of labour in making a pair of jeans in the correct order.",o:["Grow and harvest cotton","Transport the cotton to the spinning mill","Spin yarn and weave fabric","Sew the jeans in the clothing factory","Sell the jeans to customers in retail"],e:"In the vertical division of labour, firms at different stages work one after another on the same product: primary production → service (transport) → production (spinning, weaving, clothing factory) → service (retail)."},hu:{q:"Rendezd helyes sorrendbe a vertikális munkamegosztás lépéseit egy farmernadrág előállításánál.",o:["Gyapot termesztése és betakarítása","A gyapot elszállítása a fonodába","Fonal fonása és szövet szövése","A farmer megvarrása a ruhagyárban","A farmer értékesítése a kiskereskedelemben"],e:"Vertikális munkamegosztásnál különböző termelési fokozaton lévő cégek egymás után dolgoznak ugyanazon a terméken: őstermelés → szolgáltatás (szállítás) → termelés (fonoda, szövöde, ruhagyár) → szolgáltatás (kiskereskedelem)."}},{type:"match",level:1,de:{q:"Ordne jeden Vorgang dem Markt zu, auf dem er stattfindet.",p:[["Loopy nimmt bei der Bank einen Kredit auf","Kapitalmarkt"],["Eine Schülerin bewirbt sich um eine Lehrstelle","Arbeitsmarkt"],["Ein Paar kauft eine Eigentumswohnung","Immobilienmarkt"],["Eine Tischlerei kauft eine CNC-Fräse","Investitionsgütermarkt"],["Ein Kunde lässt sich beim Friseur die Haare schneiden","Dienstleistungsmarkt"]],e:"Märkte werden nach dem gehandelten Gut eingeteilt: Geld → Kapitalmarkt, Arbeitskraft → Arbeitsmarkt, Grundstücke/Gebäude → Immobilienmarkt, Maschinen für Firmen → Investitionsgütermarkt, Haarschnitt → Dienstleistungsmarkt."},en:{q:"Match each transaction to the market where it takes place.",p:[["Loopy takes out a loan from the bank","Capital market"],["A student applies for an apprenticeship","Labour market"],["A couple buys a flat","Real estate market"],["A joinery buys a CNC milling machine","Capital goods market"],["A customer gets a haircut","Services market"]],e:"Markets are classified by what is traded: money → capital market, labour → labour market, land/buildings → real estate market, machines for firms → capital goods market, haircut → services market."},hu:{q:"Párosítsd az egyes ügyleteket azzal a piaccal, ahol lezajlanak.",p:[["Loopy hitelt vesz fel a banknál","Tőkepiac"],["Egy diáklány tanulóhelyre jelentkezik","Munkaerőpiac"],["Egy pár lakást vásárol","Ingatlanpiac"],["Egy asztalosüzem CNC-marógépet vesz","Beruházási javak piaca"],["Egy vásárló levágatja a haját a fodrásznál","Szolgáltatások piaca"]],e:"A piacokat a forgalmazott jószág szerint osztjuk fel: pénz → tőkepiac, munkaerő → munkaerőpiac, telek/épület → ingatlanpiac, gépek vállalkozásoknak → beruházási javak piaca, hajvágás → szolgáltatások piaca."}},{type:"mc",level:2,correctIndex:3,de:{q:"In der Steiermark fällt ein Forstbetrieb Bäume, ein Sägewerk schneidet daraus Bretter und ein Möbelhaus verkauft die fertigen Tische. Welche Zuordnung zu den Wirtschaftssektoren stimmt?",o:["Forst: sekundär – Sägewerk: primär – Möbelhaus: tertiär","Forst: primär – Sägewerk: tertiär – Möbelhaus: sekundär","Forst: primär – Sägewerk: sekundär – Möbelhaus: sekundär","Forst: primär – Sägewerk: sekundär – Möbelhaus: tertiär"],e:"Der Forst gewinnt Rohstoffe (primär), das Sägewerk verarbeitet sie (sekundär) und das Möbelhaus stellt die Güter bereit (tertiär, Dienstleistung). Ein Händler stellt nichts her – er gehört daher nicht zum sekundären Sektor."},en:{q:"In Styria, a forestry business fells trees, a sawmill cuts them into boards and a furniture store sells the finished tables. Which assignment to the economic sectors is correct?",o:["Forestry: secondary – sawmill: primary – furniture store: tertiary","Forestry: primary – sawmill: tertiary – furniture store: secondary","Forestry: primary – sawmill: secondary – furniture store: secondary","Forestry: primary – sawmill: secondary – furniture store: tertiary"],e:"Forestry extracts raw materials (primary), the sawmill processes them (secondary) and the furniture store makes the goods available (tertiary, service). A retailer does not manufacture anything, so it does not belong to the secondary sector."},hu:{q:"Stájerországban egy erdőgazdaság fákat dönt ki, egy fűrészüzem deszkát vág belőlük, egy bútoráruház pedig eladja a kész asztalokat. Melyik besorolás helyes a gazdasági szektorok szerint?",o:["Erdőgazdaság: szekunder – fűrészüzem: primer – bútoráruház: tercier","Erdőgazdaság: primer – fűrészüzem: tercier – bútoráruház: szekunder","Erdőgazdaság: primer – fűrészüzem: szekunder – bútoráruház: szekunder","Erdőgazdaság: primer – fűrészüzem: szekunder – bútoráruház: tercier"],e:"Az erdőgazdaság nyersanyagot termel ki (primer), a fűrészüzem feldolgozza (szekunder), a bútoráruház pedig elérhetővé teszi a javakat (tercier, szolgáltatás). A kereskedő nem gyárt semmit, ezért nem a szekunder szektorhoz tartozik."}},{type:"mc",level:3,correctIndex:0,de:{q:"In Österreich gibt es für Railjet-Züge nur einen einzigen Käufer: die ÖBB. Welche Marktform liegt hier vor und was bedeutet das?",o:["Monopol auf der Nachfrageseite – die ÖBB haben große Marktmacht","Monopol auf der Angebotsseite – der Hersteller bestimmt den Preis","Oligopol auf der Nachfrageseite – wenige Käufer teilen sich den Markt","Polypol – Angebot und Nachfrage gleichen sich frei aus"],e:"Gibt es nur EINEN Nachfrager, spricht man von einem Monopol auf der Nachfrageseite. Wer als Einziger kauft, hat viel Marktmacht und kann Preise und Bedingungen stark beeinflussen. Ein Angebotsmonopol hätte nur einen Verkäufer."},en:{q:"In Austria there is only one single buyer of Railjet trains: ÖBB (Austrian Federal Railways). Which market form is this and what does it mean?",o:["Monopoly on the demand side – ÖBB has great market power","Monopoly on the supply side – the manufacturer sets the price","Oligopoly on the demand side – a few buyers share the market","Polypoly – supply and demand balance out freely"],e:"If there is only ONE buyer, it is a monopoly on the demand side. Whoever is the only buyer has a lot of market power and can strongly influence prices and conditions. A supply monopoly would have only one seller."},hu:{q:"Ausztriában a Railjet-vonatoknak egyetlen vevője van: az ÖBB (Osztrák Szövetségi Vasutak). Milyen piaci forma ez, és mit jelent?",o:["Keresleti oldali monopólium – az ÖBB-nek nagy a piaci ereje","Kínálati oldali monopólium – a gyártó határozza meg az árat","Keresleti oldali oligopólium – néhány vevő osztozik a piacon","Polipólium – a kereslet és a kínálat szabadon kiegyenlítődik"],e:"Ha csak EGY vevő van, keresleti oldali monopóliumról beszélünk. Aki egyedüli vevő, annak nagy a piaci ereje, és erősen befolyásolhatja az árakat és a feltételeket. Kínálati monopóliumnál egyetlen eladó lenne."}},{type:"number",level:3,value:80,tol:0,unit:{de:"Stück",en:"pieces",hu:"darab"},de:{q:"Auf dem Markt für Pralinenschachteln gilt: Nachfrage = 500 − 50 · Preis und Angebot = 100 + 30 · Preis (Menge in Stück, Preis in €). Ein Händlerverband setzt den Preis auf 6 € fest. Wie groß ist der Überschuss (in Stück)?",e:"Nachfrage = 500 − 50 · 6 = 200 Stück. Angebot = 100 + 30 · 6 = 280 Stück. Überschuss = 280 − 200 = 80 Stück – ein Angebotsüberschuss, weil 6 € über dem Gleichgewichtspreis von 5 € liegt (500 − 50p = 100 + 30p → p = 5)."},en:{q:"On the market for chocolate boxes: demand = 500 − 50 · price and supply = 100 + 30 · price (quantity in pieces, price in €). A traders' association fixes the price at €6. How large is the surplus (in pieces)?",e:"Demand = 500 − 50 · 6 = 200 pieces. Supply = 100 + 30 · 6 = 280 pieces. Surplus = 280 − 200 = 80 pieces – excess supply, because €6 is above the equilibrium price of €5 (500 − 50p = 100 + 30p → p = 5)."},hu:{q:"A bonbonosdobozok piacán: kereslet = 500 − 50 · ár és kínálat = 100 + 30 · ár (mennyiség darabban, ár €-ban). Egy kereskedői szövetség 6 €-ban rögzíti az árat. Mekkora a többlet (darabban)?",e:"Kereslet = 500 − 50 · 6 = 200 darab. Kínálat = 100 + 30 · 6 = 280 darab. Többlet = 280 − 200 = 80 darab – kínálati többlet, mert a 6 € az 5 €-s egyensúlyi ár felett van (500 − 50p = 100 + 30p → p = 5)."}}],"unternehmen-und-umfeld":[{type:"tf",level:1,correct:!1,de:{q:"Der Satz „Ich gehe jetzt in die Firma“ ist betriebswirtschaftlich korrekt, weil die Firma der Ort ist, an dem gearbeitet wird",e:"Falsch. Die Firma ist der Name des Unternehmens (im Firmenbuch eingetragen). Der Ort, an dem die Leistung erstellt wird, ist der Betrieb – korrekt wäre also „Ich gehe in den Betrieb“."},en:{q:"In German, saying “Ich gehe in die Firma” (“I'm going to the Firma”) is correct in business terms, because the Firma is the place where people work",e:"False. The Firma is the name of the business (registered in the commercial register). The place where the output is produced is the Betrieb (operating site) – so “I'm going to the Betrieb” would be correct."},hu:{q:"Az „Most bemegyek a cégbe” mondat üzleti szempontból helyes, mert a cég (cégnév) az a hely, ahol dolgoznak",e:"Hamis. A cég (Firma) a vállalkozás neve, amelyet a cégjegyzékbe bejegyeznek. A hely, ahol a teljesítményt előállítják, az üzem (Betrieb) – helyesen tehát „bemegyek az üzembe”."}},{type:"tf",level:2,correct:!1,de:{q:"Ein Unternehmen mit 49 Mitarbeiter:innen zählt bereits zu den Mittelbetrieben",e:"Falsch. Mit 10 bis 49 Mitarbeiter:innen ist es ein Kleinbetrieb. Mittelbetriebe haben 50 bis 249, Großbetriebe ab 250 Mitarbeiter:innen."},en:{q:"A business with 49 employees already counts as a medium-sized business",e:"False. With 10 to 49 employees it is a small business. Medium-sized businesses have 50 to 249 employees, large businesses 250 or more."},hu:{q:"Egy 49 munkavállalót foglalkoztató vállalkozás már középvállalkozásnak számít",e:"Hamis. 10–49 munkavállalóval kisvállalkozás. A középvállalkozások 50–249, a nagyvállalatok legalább 250 főt foglalkoztatnak."}},{type:"tf",level:3,correct:!0,de:{q:"Auch ein Verein, der keinen Gewinn erzielen will, muss seine Zahlungsfähigkeit sichern",e:"Richtig. Non-Profit-Organisationen reicht zwar Kostendeckung, aber die Zahlungsfähigkeit (Liquidität) gilt für ALLE Unternehmen: Wer fällige Rechnungen nicht pünktlich zahlen kann, gefährdet seine Existenz."},en:{q:"Even an association that does not aim to make a profit must ensure its solvency",e:"True. Non-profit organisations only need to cover their costs, but solvency (liquidity) applies to ALL organisations: anyone who cannot pay bills on time puts their existence at risk."},hu:{q:"Még egy nyereségre nem törekvő egyesületnek is biztosítania kell a fizetőképességét",e:"Igaz. A nonprofit szervezeteknek elég a költségfedezet, de a fizetőképesség (likviditás) MINDEN szervezetre vonatkozik: aki nem tudja időben kifizetni az esedékes számláit, a létét veszélyezteti."}},{type:"multi",level:2,correct:[0,2,4],de:{q:"Welche der folgenden Unternehmensziele sind nicht monetäre Formalziele? Wähle alle zutreffenden aus.",o:["Kundenzufriedenheit steigern","Kosten senken","Arbeitsklima verbessern","Zahlungsfähigkeit sichern","Marktanteil ausbauen","Umsatz erhöhen"],e:"Nicht monetäre Ziele lassen sich nicht direkt in Geld messen: Kundenzufriedenheit, Arbeitsklima, Image, Marktanteil, Umweltschutz. Kosten, Zahlungsfähigkeit und Umsatz sind Geldgrößen – also monetäre Formalziele."},en:{q:"Which of the following business goals are non-monetary formal goals? Select all that apply.",o:["Increase customer satisfaction","Reduce costs","Improve the working atmosphere","Ensure solvency","Expand market share","Increase sales revenue"],e:"Non-monetary goals cannot be measured directly in money: customer satisfaction, working atmosphere, image, market share, environmental protection. Costs, solvency and revenue are money figures – so they are monetary formal goals."},hu:{q:"Az alábbi vállalati célok közül melyek nem pénzben mérhető formális célok? Jelöld meg az összes helyeset.",o:["Az ügyfél-elégedettség növelése","A költségek csökkentése","A munkahelyi légkör javítása","A fizetőképesség biztosítása","A piaci részesedés bővítése","Az árbevétel növelése"],e:"A nem pénzben mérhető célokat nem lehet közvetlenül pénzben kifejezni: ügyfél-elégedettség, munkahelyi légkör, imázs, piaci részesedés, környezetvédelem. A költség, a fizetőképesség és az árbevétel pénzbeli mutatók – tehát pénzben mérhető formális célok."}},{type:"multi",level:1,correct:[0,2,4],de:{q:"Welche Stakeholder zählen zu den externen Anspruchsgruppen eines Unternehmens? Wähle alle zutreffenden aus.",o:["Fremdkapitalgeber (z. B. die Hausbank)","Management","Konkurrenz","Eigentümer:innen","Gesellschaft","Mitarbeiter:innen"],e:"Externe Stakeholder stehen außerhalb des Unternehmens: Lieferanten, Kund:innen, Fremdkapitalgeber, Konkurrenz, Staat und Gesellschaft. Eigentümer:innen, Management und Mitarbeiter:innen sind interne Stakeholder."},en:{q:"Which stakeholders are external stakeholder groups of a business? Select all that apply.",o:["Lenders (e.g. the company's bank)","Management","Competitors","Owners","Society","Employees"],e:"External stakeholders are outside the business: suppliers, customers, lenders, competitors, the state and society. Owners, management and employees are internal stakeholders."},hu:{q:"Mely érintettek tartoznak egy vállalkozás külső érdekcsoportjai közé? Jelöld meg az összes helyeset.",o:["Hitelezők (pl. a számlavezető bank)","Menedzsment","Versenytársak","Tulajdonosok","Társadalom","Munkavállalók"],e:"A külső érintettek a vállalkozáson kívül állnak: szállítók, vevők, hitelezők, versenytársak, állam és társadalom. A tulajdonosok, a menedzsment és a munkavállalók belső érintettek."}},{type:"order",level:1,de:{q:"Ordne die Betriebe nach ihrer Betriebsgröße – vom kleinsten zum größten.",o:["Friseursalon mit 4 Mitarbeiter:innen (Kleinstbetrieb)","Tischlerei mit 18 Mitarbeiter:innen (Kleinbetrieb)","Hotel mit 120 Mitarbeiter:innen (Mittelbetrieb)","Bank mit 900 Mitarbeiter:innen (Großbetrieb)"],e:"Nach Mitarbeiter:innen gilt: Kleinstbetrieb bis 9, Kleinbetrieb 10–49, Mittelbetrieb 50–249, Großbetrieb ab 250."},en:{q:"Put the businesses in order of size – from smallest to largest.",o:["Hair salon with 4 employees (micro business)","Joinery with 18 employees (small business)","Hotel with 120 employees (medium-sized business)","Bank with 900 employees (large business)"],e:"By number of employees: micro business up to 9, small business 10–49, medium-sized business 50–249, large business 250 or more."},hu:{q:"Rendezd az üzemeket méretük szerint – a legkisebbtől a legnagyobbig.",o:["Fodrászszalon 4 munkavállalóval (mikrovállalkozás)","Asztalosüzem 18 munkavállalóval (kisvállalkozás)","Szálloda 120 munkavállalóval (középvállalkozás)","Bank 900 munkavállalóval (nagyvállalat)"],e:"A munkavállalók száma szerint: mikrovállalkozás legfeljebb 9, kisvállalkozás 10–49, középvállalkozás 50–249, nagyvállalat legalább 250 fő."}},{type:"match",level:2,de:{q:"Ordne jede Entwicklung dem Unternehmensumfeld zu, aus dem sie stammt.",p:[["Die Kreditzinsen der Banken steigen","Ökonomisches Umfeld"],["Ein neues Gesetz verschärft die Kennzeichnungspflicht","Gesellschaftliches Umfeld"],["Ein Pralinen-Roboter wird marktreif","Technologisches Umfeld"],["Eine Dürre verknappt die Kakaoernte","Ökologisches Umfeld"]],e:"Ökonomisch = wirtschaftliche Lage und Preise (Zinsen); gesellschaftlich = Politik, Recht, Kultur (Gesetze); technologisch = neue Technik und Prozesse; ökologisch = Natur, Rohstoffe, Umwelt (Dürre)."},en:{q:"Match each development to the business environment it comes from.",p:[["Banks' lending rates rise","Economic environment"],["A new law tightens labelling requirements","Social environment"],["A chocolate-making robot is ready for market","Technological environment"],["A drought reduces the cocoa harvest","Ecological environment"]],e:"Economic = economic situation and prices (interest rates); social = politics, law, culture (laws); technological = new technology and processes; ecological = nature, raw materials, environment (drought)."},hu:{q:"Párosítsd az egyes fejleményeket azzal a vállalati környezettel, amelyből származnak.",p:[["Emelkednek a bankok hitelkamatai","Gazdasági környezet"],["Új törvény szigorítja a címkézési kötelezettséget","Társadalmi környezet"],["Piacra kerül egy bonbonkészítő robot","Technológiai környezet"],["Az aszály csökkenti a kakaótermést","Ökológiai környezet"]],e:"Gazdasági = gazdasági helyzet és árak (kamatok); társadalmi = politika, jog, kultúra (törvények); technológiai = új technika és eljárások; ökológiai = természet, nyersanyagok, környezet (aszály)."}},{type:"mc",level:3,correctIndex:2,de:{q:"Die Bäckerei Mayer GmbH betreibt eine Backstube in Linz und drei Filialen in Linz, Wels und Steyr. Wie viele Unternehmen, Betriebe und Firmen liegen vor?",o:["4 Unternehmen – 4 Betriebe – 4 Firmen","1 Unternehmen – 1 Betrieb – 4 Firmen","1 Unternehmen – 4 Betriebe – 1 Firma","1 Unternehmen – 3 Betriebe – 1 Firma"],e:"Es gibt einen rechtlichen Rahmen (1 Unternehmen) mit einem Namen im Firmenbuch (1 Firma: Bäckerei Mayer GmbH). Leistung wird aber an vier Orten erstellt – Backstube plus drei Filialen = 4 Betriebe. Die Backstube darf man nicht vergessen."},en:{q:"Bäckerei Mayer GmbH runs a bakehouse in Linz and three branches in Linz, Wels and Steyr. How many businesses (Unternehmen), operating sites (Betriebe) and company names (Firmen) are there?",o:["4 businesses – 4 sites – 4 company names","1 business – 1 site – 4 company names","1 business – 4 sites – 1 company name","1 business – 3 sites – 1 company name"],e:"There is one legal framework (1 business) with one name in the commercial register (1 company name: Bäckerei Mayer GmbH). But output is produced at four locations – bakehouse plus three branches = 4 sites. Don't forget the bakehouse."},hu:{q:"A Bäckerei Mayer GmbH egy sütödét üzemeltet Linzben, valamint három fióküzletet Linzben, Welsben és Steyrben. Hány vállalkozásról, üzemről és cégnévről van szó?",o:["4 vállalkozás – 4 üzem – 4 cégnév","1 vállalkozás – 1 üzem – 4 cégnév","1 vállalkozás – 4 üzem – 1 cégnév","1 vállalkozás – 3 üzem – 1 cégnév"],e:"Egy jogi keret van (1 vállalkozás), egy névvel a cégjegyzékben (1 cégnév: Bäckerei Mayer GmbH). A teljesítményt viszont négy helyen állítják elő – a sütöde és a három fióküzlet = 4 üzem. A sütödét nem szabad kifelejteni."}},{type:"mc",level:3,correctIndex:1,de:{q:"Ein öffentliches Krankenhaus in Tirol schließt das Jahr ohne Gewinn ab: Die Erträge decken genau die Aufwände. Wie ist das betriebswirtschaftlich zu beurteilen?",o:["Nicht erfolgreich – jedes Unternehmen muss Gewinn machen","Erfolgreich – als Non-Profit-Organisation reicht Kostendeckung","Nicht erfolgreich – Erträge müssen die Aufwände übersteigen","Erfolgreich – weil Liquidität im Krankenhaus keine Rolle spielt"],e:"Ein öffentliches Krankenhaus arbeitet im Interesse der Allgemeinheit (Non-Profit) – Kostendeckung reicht, Verluste trägt z. B. der Staat. „Erträge > Aufwände“ ist der Maßstab für gewinnorientierte Unternehmen; die Zahlungsfähigkeit ist aber für alle wichtig."},en:{q:"A public hospital in Tyrol ends the year without a profit: its income exactly covers its expenses. How should this be assessed in business terms?",o:["Not successful – every business must make a profit","Successful – as a non-profit, covering costs is enough","Not successful – income must exceed expenses","Successful – because liquidity plays no role in a hospital"],e:"A public hospital works in the public interest (non-profit) – covering costs is enough, and losses are borne e.g. by the state. “Income > expenses” is the yardstick for profit-oriented businesses; solvency, however, matters for everyone."},hu:{q:"Egy tiroli közkórház nyereség nélkül zárja az évet: a bevételei pontosan fedezik a ráfordításait. Hogyan értékelhető ez üzleti szempontból?",o:["Nem sikeres – minden vállalkozásnak nyereséget kell termelnie","Sikeres – nonprofit szervezetként elég a költségfedezet","Nem sikeres – a bevételeknek meg kell haladniuk a ráfordításokat","Sikeres – mert a likviditás egy kórházban nem számít"],e:"A közkórház a közösség érdekében működik (nonprofit) – elég a költségfedezet, a veszteséget pl. az állam állja. A „bevétel > ráfordítás” a nyereségorientált vállalkozások mércéje; a fizetőképesség viszont mindenkinek fontos."}},{type:"number",level:2,value:91800,tol:.5,unit:{de:"€",en:"€",hu:"€"},de:{q:"Loopys Candy Store hatte im Vorjahr einen Umsatz von 85.000 €. Loopy formuliert das SMART-Ziel: „Wir steigern den Umsatz innerhalb von 12 Monaten um 8 %.“ Welchen Umsatz muss sie erreichen?",e:"8 % von 85.000 € = 85.000 · 0,08 = 6.800 €. Zielumsatz = 85.000 + 6.800 = 91.800 € (oder direkt 85.000 · 1,08). Es ist ein monetäres Formalziel – messbar und terminiert."},en:{q:"Last year Loopy's Candy Store had sales revenue of €85,000. Loopy sets the SMART goal: “We will increase sales revenue by 8% within 12 months.” What revenue does she need to reach?",e:"8% of €85,000 = 85,000 · 0.08 = €6,800. Target revenue = 85,000 + 6,800 = €91,800 (or directly 85,000 · 1.08). It is a monetary formal goal – measurable and time-bound."},hu:{q:"Loopy édességboltjának tavaly 85 000 € volt az árbevétele. Loopy ezt a SMART-célt tűzi ki: „12 hónapon belül 8%-kal növeljük az árbevételt.” Mekkora árbevételt kell elérnie?",e:"85 000 € 8%-a = 85 000 · 0,08 = 6800 €. Célárbevétel = 85 000 + 6800 = 91 800 € (vagy közvetlenül 85 000 · 1,08). Ez pénzben mérhető formális cél – mérhető és határidőhöz kötött."}}],"leistungserstellung-1jg":[{type:"tf",level:1,correct:!0,de:{q:"Roh-, Hilfs- und Betriebsstoffe werden zusammen als Werkstoffe bezeichnet",e:"Richtig. Werkstoffe ist der Sammelbegriff für Rohstoffe (Hauptbestandteil), Hilfsstoffe (Nebenbestandteil) und Betriebsstoffe (werden verbraucht, sind aber nicht im Produkt). Sie gehören zum Umlaufvermögen."},en:{q:"Raw materials, auxiliary materials and operating supplies are together called materials (Werkstoffe)",e:"True. Materials is the umbrella term for raw materials (main component), auxiliary materials (minor component) and operating supplies (used up but not part of the product). They belong to current assets."},hu:{q:"A nyersanyagokat, segédanyagokat és üzemanyagokat együttesen anyagoknak nevezzük",e:"Igaz. Az anyagok gyűjtőfogalom a nyersanyagokra (fő alkotórész), a segédanyagokra (mellékes alkotórész) és az üzemanyagokra (elhasználódnak, de nem részei a terméknek). A forgóeszközök közé tartoznak."}},{type:"tf",level:2,correct:!1,de:{q:"Das Schmieröl für Loopys Gießmaschine ist ein Hilfsstoff, weil es bei der Produktion nur eine Nebenrolle spielt",e:"Falsch. Das Öl wird bei der Produktion verbraucht, steckt aber nicht in den Pralinen – es ist ein Betriebsstoff. Hilfsstoffe sind Nebenbestandteile, die im fertigen Produkt enthalten sind (z. B. Zwirn in der Jeans)."},en:{q:"The lubricating oil for Loopy's moulding machine is an auxiliary material because it only plays a minor role in production",e:"False. The oil is used up in production but is not contained in the chocolates – it is an operating supply. Auxiliary materials are minor components that are part of the finished product (e.g. thread in jeans)."},hu:{q:"Loopy öntőgépének kenőolaja segédanyag, mert a termelésben csak mellékes szerepet játszik",e:"Hamis. Az olaj a termelés során elhasználódik, de nincs benne a bonbonban – ezért üzemanyag (üzemi anyag). A segédanyagok a késztermékben is megtalálható mellékes alkotórészek (pl. a cérna a farmerben)."}},{type:"tf",level:3,correct:!0,de:{q:"Ein Lieferwagen, den ein Autohändler zum Weiterverkauf auf seinem Hof stehen hat, gehört bei diesem Händler zum Umlaufvermögen",e:"Richtig. Der Händler will den Wagen bald unverändert verkaufen – er ist Handelsware und damit Umlaufvermögen. Nutzt eine Bäckerei denselben Wagen jahrelang zum Ausliefern, ist er dort Anlagevermögen. Entscheidend ist die Verwendung, nicht der Gegenstand."},en:{q:"A delivery van that a car dealer has on the lot for resale belongs to that dealer's current assets",e:"True. The dealer wants to sell the van soon without changing it – it is merchandise and therefore a current asset. If a bakery uses the same van for deliveries for years, it is a fixed asset there. What counts is the use, not the object."},hu:{q:"Egy kisteherautó, amelyet egy autókereskedő továbbértékesítésre tart az udvarán, ennél a kereskedőnél a forgóeszközök közé tartozik",e:"Igaz. A kereskedő hamarosan változatlan formában el akarja adni – ez kereskedelmi áru, tehát forgóeszköz. Ha egy pékség ugyanezt az autót évekig kiszállításra használja, ott befektetett eszköz. A felhasználás a döntő, nem a tárgy."}},{type:"multi",level:1,correct:[0,2,4],de:{q:"Welche Vermögensteile von Loopys Candy Store gehören zum Anlagevermögen? Wähle alle zutreffenden aus.",o:["Die Kühlvitrine im Verkaufsraum","Kakaobohnen im Lager","Die eingetragene Marke „Loopys“","Das Guthaben am Bankkonto","Der Lieferwagen","Offene Rechnungen von Kund:innen (Forderungen)"],e:"Anlagevermögen bleibt länger als ein Jahr im Unternehmen: Sachanlagen (Vitrine, Lieferwagen) und immaterielle Anlagen (Marke). Kakaobohnen werden verbraucht, Bankguthaben und Forderungen sind Finanzumlaufvermögen."},en:{q:"Which assets of Loopy's Candy Store are fixed assets? Select all that apply.",o:["The refrigerated display case in the shop","Cocoa beans in the storeroom","The registered trademark “Loopy's”","The balance on the bank account","The delivery van","Unpaid customer invoices (receivables)"],e:"Fixed assets stay in the business for more than a year: tangible assets (display case, van) and intangible assets (trademark). Cocoa beans are used up; bank balances and receivables are financial current assets."},hu:{q:"Loopy édességboltjának mely vagyonelemei tartoznak a befektetett eszközök közé? Jelöld meg az összes helyeset.",o:["A hűtővitrin az eladótérben","A raktárban lévő kakaóbab","A bejegyzett „Loopys” védjegy","A bankszámla egyenlege","A kisteherautó","A vevők kifizetetlen számlái (követelések)"],e:"A befektetett eszközök egy évnél tovább maradnak a vállalkozásban: tárgyi eszközök (vitrin, kisteherautó) és immateriális javak (védjegy). A kakaóbab elfogy, a bankszámla-egyenleg és a követelések pénzügyi forgóeszközök."}},{type:"multi",level:3,correct:[0,2,4],de:{q:"Welche Faktoren beeinflussen die Leistungsbereitschaft (das „Wollen“) von Mitarbeiter:innen? Wähle alle zutreffenden aus.",o:["Betriebsklima","Begabung","Lob durch die Vorgesetzten","Berufserfahrung","Höhe des Lohns","Ausbildung"],e:"Die Leistungsbereitschaft ist die Motivation – sie hängt von Lohn, Arbeitsplatz, Betriebsklima, Arbeitszeiten und Lob ab. Begabung, Ausbildung und Berufserfahrung bestimmen dagegen die Leistungsfähigkeit, also das „Können“."},en:{q:"Which factors influence employees' willingness to perform (their “wanting”)? Select all that apply.",o:["Working atmosphere","Talent","Praise from supervisors","Professional experience","Level of pay","Training"],e:"Willingness to perform is motivation – it depends on pay, workplace, working atmosphere, working hours and praise. Talent, training and professional experience, on the other hand, determine the ability to perform, i.e. “being able to”."},hu:{q:"Mely tényezők befolyásolják a munkavállalók teljesítményhajlandóságát (az „akarást”)? Jelöld meg az összes helyeset.",o:["Munkahelyi légkör","Tehetség","Dicséret a felettesektől","Szakmai tapasztalat","A bér nagysága","Képzettség"],e:"A teljesítményhajlandóság a motiváció – a bértől, a munkahelytől, a légkörtől, a munkaidőtől és a dicsérettől függ. A tehetség, a képzettség és a szakmai tapasztalat viszont a teljesítőképességet, vagyis a „tudást” határozza meg."}},{type:"order",level:1,de:{q:"Bringe die Aufgaben der Unternehmensführung im Managementkreis in die richtige Reihenfolge.",o:["Ziele formulieren und planen","Entscheiden","Organisieren und steuern","Kontrollieren"],e:"Zuerst werden Ziele gesetzt und geplant, dann Maßnahmen beschlossen, mit den Abteilungen umgesetzt und am Ende kontrolliert. Die Kontrolle liefert die Grundlage für die nächste Planung – deshalb „Kreis“."},en:{q:"Put the tasks of management in the management cycle in the correct order.",o:["Set goals and plan","Decide","Organise and steer","Control"],e:"First goals are set and planned, then measures are decided, implemented with the departments and finally checked. The control step provides the basis for the next round of planning – hence “cycle”."},hu:{q:"Rendezd helyes sorrendbe a vállalatvezetés feladatait a vezetési ciklusban.",o:["Célok megfogalmazása és tervezés","Döntéshozatal","Szervezés és irányítás","Ellenőrzés"],e:"Először célokat tűznek ki és terveznek, majd döntenek az intézkedésekről, végrehajtják azokat az osztályokkal, végül ellenőriznek. Az ellenőrzés adja a következő tervezés alapját – ezért „ciklus”."}},{type:"match",level:2,de:{q:"Eine Tischlerei fertigt Kästen. Ordne jedes Gut der richtigen Art des Umlaufvermögens zu.",p:[["Holzplatten","Rohstoffe"],["Leim und Schrauben","Hilfsstoffe"],["Strom für die Kreissäge","Betriebsstoffe"],["Zugekaufte Türgriffe, unverändert verkauft","Handelswaren"],["Fertige Kästen im Lager","Fertige Erzeugnisse"]],e:"Holz ist der Hauptbestandteil (Rohstoff), Leim und Schrauben sind Nebenbestandteile (Hilfsstoffe), Strom wird verbraucht, steckt aber nicht im Kasten (Betriebsstoff). Unverändert weiterverkaufte Ware ist Handelsware, selbst Hergestelltes ist ein Erzeugnis."},en:{q:"A joinery makes wardrobes. Match each item to the correct type of current asset.",p:[["Wooden boards","Raw materials"],["Glue and screws","Auxiliary materials"],["Electricity for the circular saw","Operating supplies"],["Bought-in door handles, resold unchanged","Merchandise"],["Finished wardrobes in stock","Finished products"]],e:"Wood is the main component (raw material), glue and screws are minor components (auxiliary materials), electricity is used up but not part of the wardrobe (operating supply). Goods resold unchanged are merchandise; self-made goods are products."},hu:{q:"Egy asztalosüzem szekrényeket gyárt. Párosítsd az egyes javakat a forgóeszköz megfelelő fajtájával.",p:[["Falapok","Nyersanyagok"],["Ragasztó és csavarok","Segédanyagok"],["Áram a körfűrészhez","Üzemanyagok"],["Vásárolt, változatlanul eladott ajtófogantyúk","Kereskedelmi áruk"],["Kész szekrények a raktárban","Késztermékek"]],e:"A fa a fő alkotórész (nyersanyag), a ragasztó és a csavar mellékes alkotórész (segédanyag), az áram elhasználódik, de nincs benne a szekrényben (üzemanyag). A változatlanul továbbadott áru kereskedelmi áru, a saját gyártású termék késztermék."}},{type:"mc",level:2,correctIndex:0,de:{q:"In einer Tischlerei werden zugeschnittene, aber noch unlackierte Tischplatten aufbewahrt, bis die Lackiererei Zeit hat. Um welche Lagerart handelt es sich?",o:["Zwischenlager","Beschaffungslager","Verkaufs- und Versandlager","Handelswarenlager"],e:"Unfertige Güter zwischen zwei Produktionsschritten liegen im Zwischenlager. Im Beschaffungslager liegen gekaufte Materialien vor der Produktion, im Verkaufs- und Versandlager fertige Produkte vor dem Verkauf."},en:{q:"In a joinery, tabletops that have been cut but not yet varnished are stored until the paint shop has time. Which type of storage is this?",o:["Intermediate storage","Procurement storage","Sales and dispatch storage","Merchandise storage"],e:"Unfinished goods between two production steps are kept in intermediate storage. Procurement storage holds purchased materials before production; sales and dispatch storage holds finished products before sale."},hu:{q:"Egy asztalosüzemben a már kiszabott, de még lakkozatlan asztallapokat addig tárolják, amíg a lakkozóműhelynek ideje lesz. Milyen raktártípusról van szó?",o:["Közbenső raktár","Beszerzési raktár","Értékesítési és szállítási raktár","Kereskedelmiáru-raktár"],e:"A két gyártási lépés közötti félkész termékek a közbenső raktárban vannak. A beszerzési raktárban a gyártás előtti vásárolt anyagok, az értékesítési és szállítási raktárban az eladás előtti késztermékek vannak."}},{type:"mc",level:3,correctIndex:3,de:{q:"Die Geschäftsführung eines Modehauses hatte geplant, den Umsatz bei Damenjeans um 5 % zu steigern. Am Jahresende stellt sie fest, dass es nur 2 % geworden sind. In welcher Phase des Managementkreises befindet sie sich und was folgt?",o:["Organisieren – danach wird kontrolliert","Entscheiden – danach wird organisiert","Planen – danach wird entschieden","Kontrollieren – danach wird neu geplant"],e:"Der Vergleich von Plan (5 %) und Ergebnis (2 %) ist die Kontrolle. Weil der Managementkreis ein Kreislauf ist, fließen die Erkenntnisse daraus in die nächste Planung ein (z. B. neue Ziele oder andere Maßnahmen)."},en:{q:"The management of a fashion store had planned to increase sales of women's jeans by 5%. At the end of the year it finds that the increase was only 2%. Which phase of the management cycle is it in, and what comes next?",o:["Organising – then controlling follows","Deciding – then organising follows","Planning – then deciding follows","Controlling – then new planning follows"],e:"Comparing the plan (5%) with the result (2%) is control. Because the management cycle is a loop, the findings feed into the next round of planning (e.g. new goals or different measures)."},hu:{q:"Egy divatáruház vezetése azt tervezte, hogy 5%-kal növeli a női farmerek árbevételét. Az év végén megállapítja, hogy csak 2% lett. A vezetési ciklus melyik szakaszában van, és mi következik?",o:["Szervezés – utána ellenőrzés következik","Döntéshozatal – utána szervezés következik","Tervezés – utána döntéshozatal következik","Ellenőrzés – utána új tervezés következik"],e:"A terv (5%) és az eredmény (2%) összevetése az ellenőrzés. Mivel a vezetési ciklus körforgás, a tanulságok a következő tervezésbe épülnek be (pl. új célok vagy más intézkedések)."}},{type:"number",level:2,value:18925,tol:.5,unit:{de:"€",en:"€",hu:"€"},de:{q:"Loopy verkauft im Dezember 1.250 Pralinenschachteln zu je 12,90 € und 800 Schokoladetafeln zu je 3,50 €. Wie hoch ist ihr Umsatz im Dezember?",e:"Umsatz = verkaufte Menge · Preis. Pralinen: 1.250 · 12,90 = 16.125 €. Tafeln: 800 · 3,50 = 2.800 €. Gesamtumsatz = 16.125 + 2.800 = 18.925 €. Achtung: Umsatz ist nicht Gewinn – die Kosten sind noch nicht abgezogen."},en:{q:"In December Loopy sells 1,250 boxes of chocolates at €12.90 each and 800 chocolate bars at €3.50 each. What is her sales revenue for December?",e:"Revenue = quantity sold · price. Chocolates: 1,250 · 12.90 = €16,125. Bars: 800 · 3.50 = €2,800. Total revenue = 16,125 + 2,800 = €18,925. Note: revenue is not profit – costs have not been deducted yet."},hu:{q:"Loopy decemberben 1250 doboz bonbont ad el darabonként 12,90 €-ért és 800 tábla csokoládét darabonként 3,50 €-ért. Mekkora a decemberi árbevétele?",e:"Árbevétel = eladott mennyiség · ár. Bonbon: 1250 · 12,90 = 16 125 €. Csokoládé: 800 · 3,50 = 2800 €. Teljes árbevétel = 16 125 + 2800 = 18 925 €. Figyelem: az árbevétel nem nyereség – a költségeket még nem vontuk le."}}],"phasen-kaufen-verkaufen":[{type:"tf",level:1,correct:!0,de:{q:"Wer Geld in einen Getränkeautomaten wirft, schließt einen Kaufvertrag durch schlüssiges Handeln ab",e:"Richtig. Ein Vertrag braucht keine Worte: Durch das Einwerfen des Geldes zeigt man eindeutig, dass man kaufen will – das ist schlüssiges Handeln. Grundsätzlich gilt Formfreiheit."},en:{q:"Anyone who puts money into a drinks vending machine concludes a purchase contract by implied conduct",e:"True. A contract does not need words: by inserting the money you clearly show that you want to buy – that is implied conduct. In principle, there is freedom of form."},hu:{q:"Aki pénzt dob be egy italautomatába, ráutaló magatartással adásvételi szerződést köt",e:"Igaz. A szerződéshez nem kellenek szavak: a pénz bedobásával egyértelműen kimutatjuk, hogy vásárolni akarunk – ez ráutaló magatartás. Alapvetően formaszabadság érvényes."}},{type:"tf",level:2,correct:!1,de:{q:"Bekommt eine Privatperson unbestellte Ware zugeschickt, muss sie diese entweder bezahlen oder auf eigene Kosten zurückschicken",e:"Falsch. Schweigen einer Privatperson gilt als Ablehnung – es kommt kein Vertrag zustande. Unbestellte Ware muss sie weder bezahlen noch zurückschicken."},en:{q:"If a private person receives goods they did not order, they must either pay for them or send them back at their own expense",e:"False. Silence from a private person counts as rejection – no contract is formed. They neither have to pay for unordered goods nor send them back."},hu:{q:"Ha egy magánszemély meg nem rendelt árut kap, azt vagy ki kell fizetnie, vagy saját költségén vissza kell küldenie",e:"Hamis. Egy magánszemély hallgatása elutasításnak számít – nem jön létre szerződés. A meg nem rendelt árut sem kifizetnie, sem visszaküldenie nem kell."}},{type:"tf",level:3,correct:!1,de:{q:"Schließt ein 12-Jähriger ohne Zustimmung seiner Eltern einen Kaufvertrag über eine Spielkonsole um 500 € ab, ist dieser Vertrag sofort und endgültig ungültig",e:"Falsch. Der Vertrag ist schwebend unwirksam: Er wird gültig, wenn die Eltern nachträglich zustimmen, und ungültig, wenn sie ablehnen. Ein 12-Jähriger darf selbst nur geringfügige Alltagsgeschäfte abschließen."},en:{q:"If a 12-year-old concludes a contract to buy a games console for €500 without his parents' consent, the contract is immediately and permanently invalid",e:"False. The contract is provisionally ineffective (pending): it becomes valid if the parents consent afterwards and invalid if they refuse. A 12-year-old may only conclude minor everyday transactions on his own."},hu:{q:"Ha egy 12 éves a szülei hozzájárulása nélkül adásvételi szerződést köt egy 500 €-s játékkonzolra, a szerződés azonnal és véglegesen érvénytelen",e:"Hamis. A szerződés függő hatályú: érvényessé válik, ha a szülők utólag jóváhagyják, és érvénytelenné, ha elutasítják. Egy 12 éves önállóan csak csekély jelentőségű, mindennapi ügyleteket köthet."}},{type:"multi",level:2,correct:[0,1,2],de:{q:"Welche Voraussetzungen müssen gemeinsam erfüllt sein, damit ein Angebot für den Verkäufer verbindlich ist? Wähle alle zutreffenden aus.",o:["Inhaltliche Bestimmtheit (Verkäufer, Käufer, Qualität, Menge, Preis)","Erkennbarer Bindungswille des Verkäufers","Persönlicher Zugang beim Käufer","Schriftliche Form des Angebots","Eine vorherige Anfrage des Käufers"],e:"Verbindlich ist ein Angebot bei inhaltlicher Bestimmtheit, Bindungswillen und persönlichem Zugang. Es kann auch mündlich gemacht werden und auch unverlangt sein – Schriftform und Anfrage sind also keine Voraussetzung."},en:{q:"Which requirements must all be met for an offer to be binding on the seller? Select all that apply.",o:["Definite content (seller, buyer, quality, quantity, price)","Recognisable intention of the seller to be bound","Offer personally received by the buyer","Written form of the offer","A prior enquiry by the buyer"],e:"An offer is binding if its content is definite, the seller intends to be bound and it has personally reached the buyer. It can also be made orally and unsolicited – so written form and an enquiry are not requirements."},hu:{q:"Mely feltételeknek kell együttesen teljesülniük ahhoz, hogy egy ajánlat kötelező legyen az eladóra? Jelöld meg az összes helyeset.",o:["Tartalmi meghatározottság (eladó, vevő, minőség, mennyiség, ár)","Az eladó felismerhető kötelezettségvállalási szándéka","Az ajánlat személyesen eljut a vevőhöz","Az ajánlat írásbeli formája","A vevő előzetes ajánlatkérése"],e:"Az ajánlat akkor kötelező, ha tartalmilag meghatározott, megvan a kötelezettségvállalási szándék, és személyesen eljutott a vevőhöz. Szóban és kérés nélkül is tehető – az írásbeliség és az ajánlatkérés tehát nem feltétel."}},{type:"multi",level:3,correct:[0,1,4],de:{q:"Welche der folgenden Verträge müssen zwingend schriftlich abgeschlossen werden? Wähle alle zutreffenden aus.",o:["Kauf einer Eigentumswohnung","Kauf eines Fernsehers auf Raten","Pizza-Bestellung am Telefon","Kauf eines Neuwagens um 60.000 €","Kauf eines Baugrundstücks"],e:"Zwingend schriftlich sind Verträge über Grundstücke, Häuser, Wohnungen sowie Ratengeschäfte. Ein Neuwagen wird zwar meist schriftlich gekauft, rechtlich gilt aber auch bei hohen Beträgen Formfreiheit – der Preis allein macht keine Schriftform nötig."},en:{q:"Which of the following contracts must be concluded in writing? Select all that apply.",o:["Buying a flat","Buying a TV in instalments","Ordering a pizza by phone","Buying a new car for €60,000","Buying a building plot"],e:"Contracts for land, houses, flats and instalment sales must be in writing. A new car is usually bought in writing, but legally freedom of form applies even for large amounts – the price alone does not require written form."},hu:{q:"Az alábbi szerződések közül melyeket kötelező írásban megkötni? Jelöld meg az összes helyeset.",o:["Egy öröklakás megvásárlása","Egy tévé részletre vásárlása","Pizza rendelése telefonon","Egy 60 000 €-s új autó megvásárlása","Egy építési telek megvásárlása"],e:"Kötelezően írásbeliek a telekre, házra, lakásra vonatkozó szerződések, valamint a részletügyletek. Új autót általában írásban vásárolnak, de jogilag nagy összegnél is formaszabadság érvényes – az ár önmagában nem teszi kötelezővé az írásbeliséget."}},{type:"order",level:1,de:{q:"Ordne die Stufen der Geschäftsfähigkeit nach dem Alter – vom jüngsten zum ältesten.",o:["Geschäftsunfähig (unter 7 Jahren)","Beschränkt geschäftsfähig (7–14 Jahre)","Erweitert beschränkt geschäftsfähig (14–18 Jahre)","Voll geschäftsfähig (ab 18 Jahren)"],e:"Mit dem Alter wächst der Spielraum: unter 7 nur Taschengeldgeschäfte, 7–14 geringfügige Alltagsgeschäfte, 14–18 Geschäfte im Rahmen von Taschengeld/eigenem Verdienst, ab 18 alle erlaubten Geschäfte."},en:{q:"Put the stages of legal capacity to contract in order of age – from youngest to oldest.",o:["No capacity to contract (under 7)","Limited capacity (7–14)","Extended limited capacity (14–18)","Full capacity (from 18)"],e:"The scope grows with age: under 7 only pocket-money purchases, 7–14 minor everyday transactions, 14–18 transactions within pocket money/own earnings, from 18 all lawful transactions."},hu:{q:"Rendezd az ügyleti képesség fokozatait életkor szerint – a legfiatalabbtól a legidősebbig.",o:["Ügyletképtelen (7 év alatt)","Korlátozottan ügyletképes (7–14 év)","Bővített korlátozott ügyletképesség (14–18 év)","Teljesen ügyletképes (18 évtől)"],e:"Az életkorral nő a mozgástér: 7 év alatt csak zsebpénzből vásárlás, 7–14 év között csekély mindennapi ügyletek, 14–18 év között a zsebpénz/saját kereset keretein belüli ügyletek, 18 évtől minden megengedett ügylet."}},{type:"match",level:1,de:{q:"Diese Verträge sind ungültig. Ordne jedem Fall die Voraussetzung zu, die fehlt.",p:[["Verkauf eines Grundstücks am Jupiter","Möglichkeit"],["Unterschrift nur nach Drohung mit Gewalt","Freiwilligkeit"],["Kaufvertrag über Drogen","Erlaubtheit"],["Ein 6-Jähriger kauft ein Fahrrad um 400 €","Geschäftsfähigkeit"]],e:"Ein gültiger Vertrag braucht u. a. Möglichkeit (nichts Unmögliches), Freiwilligkeit (kein Zwang), Erlaubtheit (kein Gesetzesverstoß) und Geschäftsfähigkeit (ein 6-Jähriger darf nur Taschengeldgeschäfte abschließen)."},en:{q:"These contracts are invalid. Match each case to the requirement that is missing.",p:[["Selling a plot of land on Jupiter","Possibility"],["Signing only after a threat of violence","Voluntariness"],["Purchase contract for drugs","Legality"],["A 6-year-old buys a bike for €400","Legal capacity"]],e:"A valid contract requires, among other things, possibility (nothing impossible), voluntariness (no coercion), legality (no breach of law) and legal capacity (a 6-year-old may only make pocket-money purchases)."},hu:{q:"Ezek a szerződések érvénytelenek. Párosítsd mindegyik esetet a hiányzó feltétellel.",p:[["Egy telek eladása a Jupiteren","Lehetőség"],["Aláírás csak erőszakkal való fenyegetés után","Önkéntesség"],["Adásvételi szerződés kábítószerre","Jogszerűség"],["Egy 6 éves gyerek 400 €-ért vesz kerékpárt","Ügyleti képesség"]],e:"Az érvényes szerződéshez többek között szükséges a lehetőség (semmi lehetetlen), az önkéntesség (nincs kényszer), a jogszerűség (nincs törvénysértés) és az ügyleti képesség (egy 6 éves csak zsebpénzből vásárolhat)."}},{type:"mc",level:2,correctIndex:1,de:{q:"Ein Großhändler schickt Loopy per Brief ein Angebot über 50 kg Kakao, ohne eine Frist anzugeben. Wie lange ist er an sein Angebot gebunden?",o:["Nur bis Loopy den Brief geöffnet hat","Überlegungsfrist plus doppelter Postweg","Genau 14 Tage ab dem Absenden des Briefes","Unbefristet, bis er das Angebot widerruft"],e:"Bei einem Brief ohne Frist gilt: Überlegungsfrist + Hin- und Rückweg der Post (ca. 4–6 Tage). Feste 14 Tage gelten nur, wenn sie im Angebot stehen; „nur während des Gesprächs“ gilt für mündliche Angebote."},en:{q:"A wholesaler sends Loopy an offer for 50 kg of cocoa by letter without stating a deadline. How long is he bound by his offer?",o:["Only until Loopy has opened the letter","Time to consider plus double postal route","Exactly 14 days from sending the letter","Indefinitely, until he withdraws the offer"],e:"For a letter without a deadline: time to consider + the postal route there and back (about 4–6 days). A fixed 14 days only applies if stated in the offer; “only during the conversation” applies to oral offers."},hu:{q:"Egy nagykereskedő levélben ajánlatot küld Loopynak 50 kg kakaóra, határidő megadása nélkül. Meddig köti az ajánlata?",o:["Csak amíg Loopy ki nem nyitja a levelet","Gondolkodási idő plusz kétszeres postai út","Pontosan 14 napig a levél elküldésétől","Határidő nélkül, amíg vissza nem vonja"],e:"Határidő nélküli levélnél: gondolkodási idő + a posta oda- és visszaútja (kb. 4–6 nap). Fix 14 nap csak akkor érvényes, ha az ajánlatban szerepel; a „csak a beszélgetés alatt” a szóbeli ajánlatokra vonatkozik."}},{type:"mc",level:3,correctIndex:2,de:{q:"Ein Lieferant bietet Loopy verbindlich 100 kg Haselnüsse zu 8 €/kg an. Loopy bestellt rechtzeitig 100 kg – aber zu 7,50 €/kg. Was gilt?",o:["Vertrag zu 8 €/kg, weil das Angebot verbindlich war","Vertrag zu 7,50 €/kg, weil die Bestellung zuletzt kam","Kein Vertrag – die Bestellung gilt als neues Angebot","Vertrag zum Mittelwert von 7,75 €/kg"],e:"Ein Vertrag entsteht nur bei übereinstimmenden Willenserklärungen. Weicht die Bestellung vom Angebot ab, ist sie keine Annahme, sondern ein neues Angebot. Erst wenn der Lieferant die 7,50 € akzeptiert, ist der Vertrag geschlossen."},en:{q:"A supplier makes Loopy a binding offer of 100 kg of hazelnuts at €8/kg. Loopy orders 100 kg in time – but at €7.50/kg. What applies?",o:["Contract at €8/kg because the offer was binding","Contract at €7.50/kg because the order came last","No contract – the order counts as a new offer","Contract at the average of €7.75/kg"],e:"A contract only arises from matching declarations of intent. If the order deviates from the offer, it is not an acceptance but a new offer. Only when the supplier accepts the €7.50 is the contract concluded."},hu:{q:"Egy szállító kötelező ajánlatot tesz Loopynak 100 kg mogyoróra 8 €/kg áron. Loopy időben megrendel 100 kg-ot – de 7,50 €/kg áron. Mi érvényes?",o:["Szerződés 8 €/kg áron, mert az ajánlat kötelező volt","Szerződés 7,50 €/kg áron, mert a rendelés jött utoljára","Nincs szerződés – a rendelés új ajánlatnak számít","Szerződés a 7,75 €/kg-os átlagáron"],e:"Szerződés csak egybehangzó akaratnyilatkozatokkal jön létre. Ha a rendelés eltér az ajánlattól, az nem elfogadás, hanem új ajánlat. A szerződés csak akkor jön létre, ha a szállító elfogadja a 7,50 €-t."}},{type:"text",level:2,de:{q:"Wie heißt ein Zusatz wie „ohne Obligo“ oder „solange der Vorrat reicht“, mit dem ein Verkäufer sein Angebot unverbindlich macht?",a:["Freizeichnungsklausel","Freizeichnungsklauseln","Freizeichnung"],e:"Mit einer Freizeichnungsklausel macht der Verkäufer sein Angebot freibleibend – ihm fehlt dann der Bindungswille, und er muss nicht liefern."},en:{q:"What is a clause such as “without obligation” or “while stocks last” called, with which a seller makes his offer non-binding?",a:["exemption clause","non-binding clause","disclaimer clause","disclaimer","without obligation clause"],e:"With an exemption clause the seller makes the offer non-binding – the intention to be bound is missing, so he does not have to deliver."},hu:{q:"Hogyan nevezzük az olyan kikötést, mint a „kötelezettség nélkül” vagy a „a készlet erejéig”, amellyel az eladó az ajánlatát nem kötelezővé teszi?",a:["kötelezettségkizáró záradék","kötelezettség-kizáró záradék","mentesítő záradék","kizáró záradék"],e:"A kötelezettségkizáró záradékkal az eladó az ajánlatát kötöttség nélkülivé teszi – hiányzik a kötelezettségvállalási szándék, így nem köteles szállítani."}}],"gesetzliche-grundlagen-kauf":[{type:"tf",level:1,correct:!0,de:{q:"Das ABGB gilt auch für Verträge zwischen zwei Unternehmen",e:"Richtig. Das ABGB gilt für ALLE Verträge – bei B2B kommt zusätzlich das UGB dazu, das ABGB fällt aber nicht weg."},en:{q:"The ABGB (Austrian Civil Code) also applies to contracts between two businesses",e:"True. The ABGB applies to ALL contracts – for B2B the UGB (Commercial Code) applies in addition, but the ABGB does not drop out."},hu:{q:"Az ABGB (osztrák polgári törvénykönyv) két vállalkozás közötti szerződésekre is vonatkozik",e:"Igaz. Az ABGB MINDEN szerződésre vonatkozik – B2B esetén ehhez jön még az UGB (vállalati törvénykönyv), de az ABGB nem esik ki."}},{type:"tf",level:2,correct:!0,de:{q:"Verkauft eine Privatperson ihr altes Handy über eine Online-Plattform an eine andere Privatperson, ist das UGB nicht anzuwenden",e:"Richtig. Das ist ein C2C-Geschäft: Es gilt das ABGB, und weil es online passiert, ggf. das ECG. Das UGB gilt nur zwischen Unternehmen, das KSchG nur bei B2C."},en:{q:"If a private person sells their old phone to another private person via an online platform, the UGB does not apply",e:"True. This is a C2C transaction: the ABGB applies and, since it happens online, possibly the ECG (E-Commerce Act). The UGB only applies between businesses, the KSchG only to B2C."},hu:{q:"Ha egy magánszemély egy online platformon eladja régi mobiltelefonját egy másik magánszemélynek, az UGB nem alkalmazandó",e:"Igaz. Ez C2C-ügylet: az ABGB érvényes, és mivel online történik, adott esetben az ECG (e-kereskedelmi törvény). Az UGB csak vállalkozások között, a KSchG csak B2C esetén érvényes."}},{type:"tf",level:3,correct:!1,de:{q:"Verkauft eine Tischlerei einen fertigen Standardkasten aus ihrem Lager, liegt ein Werkvertrag vor",e:"Falsch. Wird ein bereits fertiges Produkt gegen einen Kaufpreis verkauft, ist das ein Kaufvertrag. Ein Werkvertrag liegt vor, wenn erst ein Werk hergestellt oder repariert wird (z. B. ein Kasten nach Maß) – die Gegenleistung heißt dann Werklohn."},en:{q:"If a joinery sells a finished standard wardrobe from its stock, this is a contract for work",e:"False. Selling an already finished product for a purchase price is a purchase contract. A contract for work exists when a piece of work is first made or repaired (e.g. a made-to-measure wardrobe) – the consideration is then called the fee for work."},hu:{q:"Ha egy asztalosüzem a raktárából elad egy kész, szabványos szekrényt, vállalkozási szerződésről van szó",e:"Hamis. Egy már kész termék vételár ellenében történő eladása adásvételi szerződés. Vállalkozási szerződés akkor áll fenn, ha egy művet előbb el kell készíteni vagy meg kell javítani (pl. méretre készült szekrény) – az ellenérték ekkor a vállalkozói díj."}},{type:"multi",level:2,correct:[0,1,3],de:{q:"Welche Aussagen zu den Geschäftsarten treffen zu? Wähle alle zutreffenden aus.",o:["„Business“ steht für Unternehmen, „Consumer“ für Privatperson.","Bei einem B2B-Geschäft gilt zusätzlich zum ABGB das UGB.","Bei einem C2C-Geschäft schützt das KSchG die Käuferin bzw. den Käufer.","Bei einem B2C-Geschäft schützt das KSchG die Konsument:innen.","Bei einem B2B-Geschäft gilt das KSchG für das kleinere Unternehmen."],e:"Das KSchG gilt nur, wenn auf einer Seite ein Konsument und auf der anderen ein Unternehmen steht (B2C). Bei C2C sind beide privat, bei B2B beide Unternehmer – dort gilt das UGB, egal wie groß die Betriebe sind."},en:{q:"Which statements about the types of transactions are correct? Select all that apply.",o:["“Business” stands for a company, “consumer” for a private person.","In a B2B transaction the UGB applies in addition to the ABGB.","In a C2C transaction the KSchG protects the buyer.","In a B2C transaction the KSchG protects consumers.","In a B2B transaction the KSchG applies to the smaller business."],e:"The KSchG (Consumer Protection Act) only applies when there is a consumer on one side and a business on the other (B2C). In C2C both are private, in B2B both are businesses – there the UGB applies, regardless of their size."},hu:{q:"Mely állítások igazak az ügylettípusokra? Jelöld meg az összes helyeset.",o:["A „business” vállalkozást, a „consumer” magánszemélyt jelent.","B2B-ügyletnél az ABGB mellett az UGB is érvényes.","C2C-ügyletnél a KSchG védi a vevőt.","B2C-ügyletnél a KSchG védi a fogyasztókat.","B2B-ügyletnél a KSchG a kisebb vállalkozásra vonatkozik."],e:"A KSchG (fogyasztóvédelmi törvény) csak akkor érvényes, ha az egyik oldalon fogyasztó, a másikon vállalkozás áll (B2C). C2C-nél mindkét fél magánszemély, B2B-nél mindkettő vállalkozás – ott az UGB érvényes, méretüktől függetlenül."}},{type:"multi",level:3,correct:[0,1,3,4,5],de:{q:"Eine Privatkundin bestellt in Loopys Onlineshop Pralinen und gibt dabei Name, Adresse und E-Mail an. Welche Gesetze sind für dieses Geschäft relevant? Wähle alle zutreffenden aus.",o:["ABGB","KSchG","UGB","ECG","FAGG","DSGVO"],e:"B2C online: ABGB (immer), KSchG (Konsumentin beteiligt), FAGG (Fernabsatz außerhalb des Geschäftslokals), ECG (Onlineauftritt) und DSGVO (personenbezogene Daten). Das UGB gilt nur, wenn beide Seiten Unternehmen sind."},en:{q:"A private customer orders chocolates in Loopy's online shop, giving her name, address and e-mail. Which laws are relevant to this transaction? Select all that apply.",o:["ABGB","KSchG","UGB","ECG","FAGG","DSGVO (GDPR)"],e:"B2C online: ABGB (always), KSchG (a consumer is involved), FAGG (distance selling outside the business premises), ECG (online presence) and GDPR (personal data). The UGB only applies if both sides are businesses."},hu:{q:"Egy magánvásárló bonbont rendel Loopy webáruházában, és megadja a nevét, címét és e-mail-címét. Mely törvények relevánsak erre az ügyletre? Jelöld meg az összes helyeset.",o:["ABGB","KSchG","UGB","ECG","FAGG","DSGVO (GDPR)"],e:"B2C online: ABGB (mindig), KSchG (fogyasztó vesz részt), FAGG (üzlethelyiségen kívüli, távollévők közötti értékesítés), ECG (online jelenlét) és GDPR (személyes adatok). Az UGB csak akkor érvényes, ha mindkét fél vállalkozás."}},{type:"match",level:1,de:{q:"Ordne jeden Fall aus Loopys Alltag dem passenden Vertragstyp zu.",p:[["Loopy mietet ein Geschäftslokal in der Innenstadt","Mietvertrag"],["Die Bank leiht Loopy 20.000 € für eine Maschine","Kreditvertrag"],["Loopy stellt eine Verkäuferin an","Arbeitsvertrag"],["Loopy sichert ihren Laden gegen Einbruch ab","Versicherungsvertrag"],["Eine Schneiderin näht Loopy eine Schürze nach Maß","Werkvertrag"]],e:"Miete: Gegenstand gegen Mietzins. Kredit: Geld gegen Zinsen + Rückzahlung. Arbeitsvertrag: Arbeitsleistung gegen Lohn. Versicherung: Schutz im Schadensfall gegen Prämie. Werkvertrag: ein erst herzustellendes Werk gegen Werklohn."},en:{q:"Match each case from Loopy's everyday business to the right type of contract.",p:[["Loopy rents shop premises in the town centre","Lease contract"],["The bank lends Loopy €20,000 for a machine","Loan contract"],["Loopy hires a shop assistant","Employment contract"],["Loopy insures her shop against burglary","Insurance contract"],["A tailor makes Loopy a made-to-measure apron","Contract for work"]],e:"Lease: object for rent. Loan: money for interest + repayment. Employment: work for wages. Insurance: cover in case of damage for a premium. Contract for work: a piece of work still to be made for a fee."},hu:{q:"Párosítsd Loopy hétköznapjainak egyes eseteit a megfelelő szerződéstípussal.",p:[["Loopy üzlethelyiséget bérel a belvárosban","Bérleti szerződés"],["A bank 20 000 €-t kölcsönöz Loopynak egy gépre","Hitelszerződés"],["Loopy felvesz egy eladónőt","Munkaszerződés"],["Loopy betörés ellen biztosítja a boltját","Biztosítási szerződés"],["Egy szabónő méretre varr Loopynak egy kötényt","Vállalkozási szerződés"]],e:"Bérlet: dolog bérleti díj ellenében. Hitel: pénz kamat + visszafizetés ellenében. Munkaszerződés: munkavégzés bér ellenében. Biztosítás: védelem kár esetén biztosítási díj ellenében. Vállalkozási szerződés: elkészítendő mű vállalkozói díj ellenében."}},{type:"mc",level:1,correctIndex:0,de:{q:"Lisa (17) verkauft ihr gebrauchtes Fahrrad an ihren Nachbarn, einen Pensionisten. Welche Geschäftsart liegt vor und welches Gesetz gilt?",o:["C2C – es gilt das ABGB","B2C – es gilt das KSchG","B2B – es gilt das UGB","C2C – es gilt das KSchG"],e:"Beide handeln privat, also C2C – dafür gilt das ABGB. Das KSchG greift nur, wenn ein Unternehmen an eine Privatperson verkauft (B2C), das UGB nur zwischen Unternehmen."},en:{q:"Lisa (17) sells her used bike to her neighbour, a pensioner. What type of transaction is this and which law applies?",o:["C2C – the ABGB applies","B2C – the KSchG applies","B2B – the UGB applies","C2C – the KSchG applies"],e:"Both act privately, so it is C2C – the ABGB applies. The KSchG only applies when a business sells to a private person (B2C), the UGB only between businesses."},hu:{q:"Lisa (17) eladja használt kerékpárját a szomszédjának, egy nyugdíjasnak. Milyen ügylettípusról van szó, és melyik törvény érvényes?",o:["C2C – az ABGB érvényes","B2C – a KSchG érvényes","B2B – az UGB érvényes","C2C – a KSchG érvényes"],e:"Mindketten magánszemélyként járnak el, tehát C2C – erre az ABGB vonatkozik. A KSchG csak akkor érvényes, ha vállalkozás ad el magánszemélynek (B2C), az UGB csak vállalkozások között."}},{type:"mc",level:2,correctIndex:3,de:{q:"Tischlermeister Huber kauft in einem Elektrofachgeschäft einen Fernseher für sein privates Wohnzimmer. Welche Geschäftsart liegt vor?",o:["B2B – Huber ist Unternehmer, also gilt das UGB","C2C – Huber kauft privat, daher gilt nur das ABGB","B2B – es gelten UGB und KSchG gemeinsam","B2C – Huber kauft als Konsument, das KSchG schützt ihn"],e:"Entscheidend ist, in welcher Rolle jemand kauft: Für sein Wohnzimmer handelt Huber als Privatperson (Consumer), der Händler ist ein Unternehmen – also B2C mit KSchG-Schutz. Kauft er eine Bohrmaschine für die Werkstatt, wäre es B2B."},en:{q:"Master joiner Huber buys a TV for his private living room at an electronics store. What type of transaction is this?",o:["B2B – Huber is a business owner, so the UGB applies","C2C – Huber buys privately, so only the ABGB applies","B2B – the UGB and KSchG apply together","B2C – Huber buys as a consumer, the KSchG protects him"],e:"What matters is the role in which someone buys: for his living room Huber acts as a private person (consumer), the retailer is a business – so it is B2C with KSchG protection. If he bought a drill for his workshop, it would be B2B."},hu:{q:"Huber asztalosmester egy elektronikai szaküzletben televíziót vesz a saját nappalijába. Milyen ügylettípusról van szó?",o:["B2B – Huber vállalkozó, ezért az UGB érvényes","C2C – Huber magáncélra vásárol, ezért csak az ABGB érvényes","B2B – az UGB és a KSchG együtt érvényes","B2C – Huber fogyasztóként vásárol, a KSchG védi"],e:"Az a döntő, milyen szerepben vásárol valaki: a nappalijába Huber magánszemélyként (fogyasztóként) vásárol, a kereskedő vállalkozás – tehát B2C, KSchG-védelemmel. Ha fúrógépet venne a műhelyébe, B2B lenne."}},{type:"mc",level:3,correctIndex:1,de:{q:"Loopy lässt eine Privatkundin einen Bestellschein unterschreiben, auf dem steht: „Das Konsumentenschutzgesetz gilt für diesen Vertrag nicht.“ Wie ist das zu beurteilen?",o:["Wirksam – es gilt Inhaltsfreiheit, die Kundin hat unterschrieben","Unwirksam – der Schutz des KSchG gilt trotzdem","Wirksam – dann gelten stattdessen die Regeln des UGB","Unwirksam – dadurch ist der ganze Kaufvertrag ungültig"],e:"Zwar gilt grundsätzlich Inhaltsfreiheit, aber Gesetze wie das KSchG gelten trotzdem – ihr Schutz für Konsument:innen kann nicht einfach weggeschrieben werden. Der Kaufvertrag selbst bleibt gültig, nur diese Klausel wirkt nicht."},en:{q:"Loopy has a private customer sign an order form stating: “The Consumer Protection Act does not apply to this contract.” How should this be assessed?",o:["Effective – freedom of content applies and the customer signed","Ineffective – the protection of the KSchG still applies","Effective – the rules of the UGB then apply instead","Ineffective – this makes the whole purchase contract invalid"],e:"Freedom of content applies in principle, but laws such as the KSchG still apply – their protection for consumers cannot simply be signed away. The purchase contract itself remains valid; only this clause has no effect."},hu:{q:"Loopy aláírat egy magánvásárlóval egy megrendelőlapot, amelyen ez áll: „A fogyasztóvédelmi törvény erre a szerződésre nem vonatkozik.” Hogyan értékelhető ez?",o:["Hatályos – tartalmi szabadság van, a vásárló aláírta","Hatálytalan – a KSchG védelme ettől függetlenül érvényes","Hatályos – helyette az UGB szabályai érvényesek","Hatálytalan – emiatt az egész adásvételi szerződés érvénytelen"],e:"Alapvetően ugyan tartalmi szabadság érvényes, de az olyan törvények, mint a KSchG, ettől függetlenül alkalmazandók – a fogyasztóknak nyújtott védelmet nem lehet egyszerűen kizárni. Maga az adásvételi szerződés érvényes marad, csak ez a kikötés hatástalan."}},{type:"text",level:2,de:{q:"Wie heißt die Gegenleistung, die man bei einem Werkvertrag (z. B. für eine Reparatur) bezahlt?",a:["Werklohn","Werklöhne","Werkentgelt"],e:"Beim Werkvertrag wird ein Werk (z. B. eine Reparatur) gegen Werklohn erbracht. Beim Kaufvertrag zahlt man den Kaufpreis, beim Mietvertrag den Mietzins."},en:{q:"What is the consideration called that you pay under a contract for work (e.g. for a repair)?",a:["fee for work","remuneration for work","work fee","contract price","fee"],e:"Under a contract for work, a piece of work (e.g. a repair) is performed in return for a fee for work. Under a purchase contract you pay the purchase price, under a lease the rent."},hu:{q:"Hogyan nevezzük az ellenértéket, amelyet vállalkozási szerződés esetén (pl. egy javításért) fizetünk?",a:["vállalkozói díj","vállalkozási díj","munkadíj"],e:"Vállalkozási szerződésnél egy művet (pl. javítást) vállalkozói díj ellenében végeznek el. Adásvételi szerződésnél vételárat, bérleti szerződésnél bérleti díjat fizetünk."}}]},s={"fernabsatz-ecommerce":[{type:"tf",level:1,correct:!0,de:{q:"E-Commerce ist eine besondere Form des Fernabsatzes.",e:"Beim E-Commerce läuft der ganze Handel über das Internet – also über ein Fernkommunikationsmittel. Damit ist jeder E-Commerce-Kauf auch Fernabsatz, aber nicht jeder Fernabsatz (z. B. Katalog, Telefon) ist E-Commerce."},en:{q:"E-commerce is a special form of distance selling.",e:"In e-commerce the whole trade takes place over the internet, i.e. a means of distance communication. So every e-commerce purchase is distance selling, but not all distance selling (e.g. catalogue, phone) is e-commerce."},hu:{q:"Az e-kereskedelem a távértékesítés egyik különleges formája.",e:"Az e-kereskedelemben az egész ügylet az interneten, vagyis távközlési eszközön keresztül zajlik. Ezért minden e-kereskedelmi vásárlás távértékesítés is, de nem minden távértékesítés (pl. katalógus, telefon) e-kereskedelem."}},{type:"tf",level:3,correct:!1,de:{q:"Verhandelt eine Kundin im Geschäft über den Preis und schließt den Kauf am nächsten Tag telefonisch ab, liegt ein Fernabsatzgeschäft vor.",e:"Falsch: Fernabsatz liegt nur vor, wenn ALLE Phasen ausschließlich über Fernkommunikationsmittel laufen. Wurde vorher persönlich im Geschäft verhandelt, ist es kein Fernabsatz – auch wenn der Abschluss per Telefon erfolgt."},en:{q:"If a customer negotiates the price in the shop and concludes the purchase by phone the next day, it is a distance contract.",e:"False: distance selling requires ALL phases to take place exclusively via means of distance communication. If the parties negotiated in person in the shop first, it is not distance selling – even if the contract is concluded by phone."},hu:{q:"Ha egy vevő az üzletben alkudozik az árról, majd másnap telefonon köti meg a vásárlást, akkor távértékesítésről van szó.",e:"Hamis: távértékesítésről csak akkor beszélünk, ha MINDEN szakasz kizárólag távközlési eszközökön keresztül zajlik. Ha előtte személyesen tárgyaltak az üzletben, az nem távértékesítés – még akkor sem, ha a szerződést telefonon kötik meg."}},{type:"tf",level:1,correct:!0,de:{q:"Die AGB eines Onlineshops müssen schon vor der Bestellung leicht auffindbar sein.",e:"Richtig: Das gehört zur Informationspflicht. AGB, die man erst auf Nachfrage oder nach dem Kauf zu sehen bekommt, können gar nicht Vertragsinhalt werden."},en:{q:"An online shop's terms and conditions must be easy to find before the order is placed.",e:"True: this is part of the duty to inform. Terms that customers only see on request or after the purchase cannot become part of the contract at all."},hu:{q:"Egy webáruház ÁSZF-ének már a megrendelés előtt könnyen megtalálhatónak kell lennie.",e:"Igaz: ez a tájékoztatási kötelezettség része. Az az ÁSZF, amelyet a vevő csak kérésre vagy a vásárlás után lát, egyáltalán nem válhat a szerződés részévé."}},{type:"multi",level:2,correct:[0,1,2,4],de:{q:"Worüber muss ein Onlineshop seine Kund:innen VOR Vertragsabschluss informieren? Wähle alle zutreffenden Angaben.",o:["Wesentliche Eigenschaften des Produkts","Preis inklusive Steuern","Rücktrittsrecht","Einkaufspreis beim eigenen Lieferanten","Gewährleistung","Anzahl der Mitarbeiter:innen im Lager"],e:"Vor Vertragsabschluss muss der Verkäufer über Produkteigenschaften, Preis inkl. Steuern, Lieferung/Zahlung, Rücktrittsrecht und Gewährleistung informieren. Einkaufspreise oder interne Daten wie die Personalanzahl sind Geschäftsgeheimnisse und keine Pflichtangaben."},en:{q:"What must an online shop inform its customers about BEFORE the contract is concluded? Select all that apply.",o:["Main characteristics of the product","Price including taxes","Right of withdrawal","Purchase price paid to its own supplier","Statutory warranty","Number of warehouse staff"],e:"Before the contract the seller must inform about product characteristics, price incl. taxes, delivery/payment, the right of withdrawal and the statutory warranty. Purchase prices or internal data such as staff numbers are business secrets, not mandatory information."},hu:{q:"Miről kell egy webáruháznak a vevőit a szerződéskötés ELŐTT tájékoztatnia? Válaszd ki az összes helyes választ.",o:["A termék lényeges tulajdonságairól","Az adókat is tartalmazó árról","Az elállási jogról","A saját beszállítójától kapott beszerzési árról","A szavatosságról","A raktárban dolgozók számáról"],e:"A szerződéskötés előtt az eladónak tájékoztatnia kell a termék tulajdonságairól, az adókat is tartalmazó árról, a szállításról/fizetésről, az elállási jogról és a szavatosságról. A beszerzési ár vagy a létszám belső üzleti adat, nem kötelező tájékoztatás."}},{type:"multi",level:1,correct:[0,2,3],de:{q:"Welche Verhaltensweisen gehören zu den Tipps für sicheres Onlineshopping? Wähle alle zutreffenden.",o:["Bestellbestätigung und AGB speichern","Möglichst im Voraus zahlen, damit schneller geliefert wird","Auf „https://“ und das Schloss-Symbol achten","Bei Gratisangeboten misstrauisch sein","Shops außerhalb der EU bevorzugen, weil sie billiger sind"],e:"Belege speichern, auf eine verschlüsselte Verbindung achten und Gratis-Lockangebote hinterfragen schützt vor Problemen. Vorauszahlung erhöht dagegen das Betrugsrisiko, und empfohlen werden geprüfte Shops aus der EU."},en:{q:"Which behaviours are among the tips for safe online shopping? Select all that apply.",o:["Save the order confirmation and terms and conditions","Pay in advance whenever possible so delivery is faster","Look for “https://” and the padlock symbol","Be suspicious of free offers","Prefer shops outside the EU because they are cheaper"],e:"Saving documents, checking for an encrypted connection and questioning free bait offers protect you. Paying in advance, by contrast, increases the risk of fraud, and certified shops within the EU are recommended."},hu:{q:"Mely viselkedésformák tartoznak a biztonságos online vásárlás tippjei közé? Válaszd ki az összes helyes választ.",o:["A megrendelés-visszaigazolás és az ÁSZF elmentése","Lehetőleg előre fizetni, hogy gyorsabb legyen a szállítás","Figyelni a „https://” előtagra és a lakat szimbólumra","Gyanakvónak lenni az ingyenes ajánlatokkal szemben","EU-n kívüli webáruházakat választani, mert olcsóbbak"],e:"A bizonylatok mentése, a titkosított kapcsolat ellenőrzése és az ingyenes csalogató ajánlatok megkérdőjelezése véd a problémáktól. Az előre fizetés viszont növeli a csalás kockázatát, és ellenőrzött EU-s webáruházak ajánlottak."}},{type:"match",level:2,de:{q:"Ordne jede Pflicht des Onlinehändlers dem passenden Beispiel zu.",p:[["Informationspflicht","Impressum mit UID- und Firmenbuchnummer"],["Bestätigungspflicht","Button „Jetzt kostenpflichtig bestellen“"],["Lieferfrist","Spätestens 30 Tage nach Vertragsabschluss"],["Rücktrittsrecht","Belehrung, wie man vom Kauf zurücktritt"]],e:"Das Impressum gehört zur Informationspflicht, der eindeutige Bestellbutton samt Bestellbestätigung zur Bestätigungspflicht. Ohne andere Vereinbarung muss binnen 30 Tagen geliefert werden, und über das Rücktrittsrecht muss belehrt werden."},en:{q:"Match each duty of the online seller with the right example.",p:[["Duty to inform","Legal notice with VAT ID and company register no."],["Duty to confirm","Button “Order now with obligation to pay”"],["Delivery period","At the latest 30 days after the contract"],["Right of withdrawal","Instructions on how to withdraw from the purchase"]],e:"The legal notice (Impressum) is part of the duty to inform; the clear order button plus order confirmation is the duty to confirm. Unless agreed otherwise, delivery must happen within 30 days, and customers must be told about their right of withdrawal."},hu:{q:"Párosítsd az online kereskedő kötelezettségeit a megfelelő példával.",p:[["Tájékoztatási kötelezettség","Impresszum közösségi adószámmal és cégjegyzékszámmal"],["Visszaigazolási kötelezettség","„Fizetési kötelezettséggel járó megrendelés” gomb"],["Szállítási határidő","Legkésőbb 30 nappal a szerződéskötés után"],["Elállási jog","Tájékoztatás arról, hogyan lehet elállni a vételtől"]],e:"Az impresszum a tájékoztatási kötelezettség része, az egyértelmű megrendelés gomb és a visszaigazolás a visszaigazolási kötelezettségé. Eltérő megállapodás hiányában 30 napon belül szállítani kell, és az elállási jogról tájékoztatni kell a vevőt."}},{type:"mc",level:2,correctIndex:1,de:{q:"Eine Kundin bestellt und bezahlt am 1. März eine große Pralinenbox in Loopys Onlineshop. Am 20. März merkt Loopy, dass sie wegen eines Lieferengpasses erst im Mai liefern kann. Was muss Loopy tun?",o:["Einfach im Mai liefern – die 30-Tage-Frist gilt nur im B2B-Geschäft","Die Kundin sofort informieren und das bezahlte Geld zurückzahlen","Der Kundin eine Stornogebühr verrechnen, falls sie nicht warten will","Ein anderes Produkt schicken, das die Kundin behalten muss"],e:"Die Lieferfrist beträgt spätestens 30 Tage nach Vertragsabschluss. Kann der Händler sie nicht einhalten, muss er die Kundin sofort informieren und bereits Bezahltes zurückzahlen. Die Frist schützt gerade Konsument:innen; eine Stornogebühr oder ein aufgezwungenes Ersatzprodukt ist unzulässig."},en:{q:"On 1 March a customer orders and pays for a large praline box in Loopy's online shop. On 20 March Loopy realises that, due to a supply shortage, she cannot deliver until May. What must Loopy do?",o:["Simply deliver in May – the 30-day rule only applies to B2B","Inform the customer immediately and refund the money paid","Charge the customer a cancellation fee if she won't wait","Send a different product that the customer has to keep"],e:"Delivery must take place at the latest 30 days after the contract. If the seller cannot manage this, they must inform the customer immediately and refund any payment. The rule protects consumers in particular; a cancellation fee or a forced substitute product is not allowed."},hu:{q:"Egy vevő március 1-jén megrendel és kifizet egy nagy bonbonos dobozt Loopy webáruházában. Március 20-án Loopy rájön, hogy ellátási nehézségek miatt csak májusban tud szállítani. Mit kell Loopynak tennie?",o:["Egyszerűen májusban szállít – a 30 napos határidő csak B2B-ben érvényes","Azonnal tájékoztatja a vevőt, és visszafizeti a kifizetett összeget","Lemondási díjat számít fel, ha a vevő nem akar várni","Másik terméket küld, amelyet a vevőnek meg kell tartania"],e:"A szállítási határidő legkésőbb 30 nap a szerződéskötéstől. Ha az eladó ezt nem tudja tartani, azonnal tájékoztatnia kell a vevőt, és vissza kell fizetnie a már kifizetett összeget. A szabály éppen a fogyasztókat védi; lemondási díj vagy ráerőltetett helyettesítő termék nem megengedett."}},{type:"mc",level:3,correctIndex:1,de:{q:"Im Onlineshop eines Grazer Modehändlers steht am Ende des Bestellvorgangs nur ein Button mit der Aufschrift „Weiter“. Ein Kunde klickt darauf und erhält eine Rechnung. Wie ist die Rechtslage?",o:["Der Vertrag gilt, denn jeder Klick im Shop ist eine Bestellung","Nicht bindend, weil der Button die Zahlungspflicht nicht klar zeigt","Der Vertrag gilt, der Kunde hat aber 30 statt 14 Tage Rücktrittsrecht","Der Vertrag gilt erst, wenn der Kunde die Rechnung bezahlt hat"],e:"Laut Bestätigungspflicht muss eindeutig erkennbar sein, dass der Klick eine Zahlungspflicht auslöst (z. B. „zahlungspflichtig bestellen“). Fehlt das, ist der Konsument an die Bestellung nicht gebunden (FAGG). Eine längere Rücktrittsfrist ist dafür nicht die Rechtsfolge."},en:{q:"In the online shop of a fashion retailer in Graz, the last step of the checkout only shows a button labelled “Continue”. A customer clicks it and receives an invoice. What is the legal position?",o:["The contract is valid because every click in the shop is an order","Not binding, because the button doesn't show the duty to pay","The contract is valid, but he has 30 instead of 14 days to withdraw","The contract only becomes valid once the customer pays the invoice"],e:"Under the duty to confirm it must be obvious that the click triggers an obligation to pay (e.g. “order with obligation to pay”). If not, the consumer is not bound by the order (FAGG). A longer withdrawal period is not the legal consequence."},hu:{q:"Egy grazi divatkereskedő webáruházában a rendelési folyamat végén csak egy „Tovább” feliratú gomb van. Egy vevő rákattint, és számlát kap. Mi a jogi helyzet?",o:["A szerződés érvényes, mert minden kattintás a boltban megrendelés","Nem köti a vevőt, mert a gomb nem jelzi a fizetési kötelezettséget","A szerződés érvényes, de a vevőnek 14 helyett 30 napja van elállni","A szerződés csak akkor érvényes, ha a vevő kifizette a számlát"],e:"A visszaigazolási kötelezettség szerint egyértelműnek kell lennie, hogy a kattintás fizetési kötelezettséget von maga után (pl. „fizetési kötelezettséggel járó megrendelés”). Ha ez hiányzik, a fogyasztót nem köti a megrendelés (FAGG). Hosszabb elállási határidő nem jogkövetkezmény."}},{type:"mc",level:3,correctIndex:2,de:{q:"Die Tischlerei Huber GmbH bestellt für ihre Werkstatt im Onlineshop eines Werkzeughändlers eine Kreissäge. Zehn Tage nach der Lieferung will sie die Säge ohne Angabe von Gründen zurückschicken. Was gilt?",o:["Sie darf zurücktreten – 14 Tage gelten bei jedem Onlinekauf","Sie darf zurücktreten, muss aber eine Stornogebühr zahlen","Kein Rücktrittsrecht, außer es wurde vereinbart","Sie darf zurücktreten, weil die Lieferfrist 30 Tage beträgt"],e:"Die besonderen Rücktrittsrechte im Fernabsatz (FAGG) schützen Konsument:innen. Kauft ein Unternehmen für seinen Betrieb ein (B2B), gibt es kein gesetzliches Rücktrittsrecht ohne Gründe – eine Rückgabe ist nur möglich, wenn sie vertraglich (z. B. in den AGB) vereinbart ist."},en:{q:"Tischlerei Huber GmbH (a joinery) orders a circular saw for its workshop from a tool dealer's online shop. Ten days after delivery it wants to send the saw back without giving reasons. What applies?",o:["It may withdraw – 14 days apply to every online purchase","It may withdraw but must pay a cancellation fee","No right of withdrawal unless it was agreed","It may withdraw because the delivery period is 30 days"],e:"The special withdrawal rights for distance selling (FAGG) protect consumers. If a company buys for its business (B2B), there is no statutory right to withdraw without reasons – a return is only possible if agreed in the contract (e.g. in the terms and conditions)."},hu:{q:"A Huber Asztalosüzem Kft. a műhelye számára egy szerszámkereskedő webáruházában körfűrészt rendel. Tíz nappal a kiszállítás után indoklás nélkül vissza akarja küldeni. Mi érvényes?",o:["Elállhat – minden online vásárlásnál 14 nap jár","Elállhat, de lemondási díjat kell fizetnie","Csak akkor állhat el, ha ezt kikötötték","Elállhat, mert a szállítási határidő 30 nap"],e:"A távértékesítésre vonatkozó különleges elállási jogok (FAGG) a fogyasztókat védik. Ha egy vállalkozás az üzeme számára vásárol (B2B), nincs indoklás nélküli törvényi elállási jog – visszaküldés csak akkor lehetséges, ha a szerződésben (pl. az ÁSZF-ben) megállapodtak róla."}},{type:"text",level:2,de:{q:"Wie nennt man einen betrügerischen Onlineshop, der nach der Zahlung verschwindet und nie liefert?",a:["Fake Shop","Fake-Shop","Fakeshop","Fake-Shops","Fake Shops","Fake-Onlineshop"],e:"Ein Fake Shop wirkt wie ein echter Onlineshop, kassiert aber nur Vorauszahlungen und liefert nie. Schutz: Impressum und Gütezeichen prüfen, nicht im Voraus zahlen."},en:{q:"What do you call a fraudulent online shop that disappears after payment and never delivers?",a:["fake shop","fake-shop","fakeshop","fake online shop","scam shop"],e:"A fake shop looks like a real online shop but only collects advance payments and never delivers. Protection: check the legal notice and trust marks, don't pay in advance."},hu:{q:"Hogyan nevezzük azt a csaló webáruházat, amely a fizetés után eltűnik, és soha nem szállít?",a:["kamu webshop","kamu webáruház","hamis webshop","hamis webáruház","álwebshop","fake shop"],e:"A kamu webshop valódi webáruháznak tűnik, de csak beszedi az előre fizetett összegeket, és soha nem szállít. Védekezés: ellenőrizd az impresszumot és a minőségi jelzéseket, ne fizess előre."}}],ruecktrittsrechte:[{type:"tf",level:1,correct:!0,de:{q:"Der Rücktritt nach dem FAGG ist an keine bestimmte Form gebunden und kann daher auch telefonisch erklärt werden.",e:"Richtig: Für den Rücktritt ist keine Form vorgeschrieben. Schriftlich (E-Mail, Brief, Formular) ist trotzdem besser, weil man den rechtzeitigen Rücktritt dann beweisen kann."},en:{q:"Withdrawal under the FAGG does not require any particular form and can therefore also be declared by phone.",e:"True: no form is prescribed for withdrawal. In writing (email, letter, form) is still better, because then you can prove you withdrew in time."},hu:{q:"A FAGG szerinti elállás nincs meghatározott formához kötve, ezért telefonon is bejelenthető.",e:"Igaz: az elálláshoz nem írnak elő formát. Írásban (e-mail, levél, nyomtatvány) mégis jobb, mert így bizonyítható, hogy időben elálltunk."}},{type:"tf",level:2,correct:!1,de:{q:"Ein Kauf an einem Messestand gilt als Geschäft außerhalb der Geschäftsräume, deshalb besteht ein 14-tägiges Rücktrittsrecht.",e:"Falsch: Ein Messestand gilt als Geschäftsraum. Wer dort kauft, wird nicht „überrumpelt“ wie bei einem Haustürgeschäft oder einer Werbefahrt – das besondere Rücktrittsrecht gilt daher nicht."},en:{q:"A purchase at a trade fair stand counts as a contract concluded off business premises, so there is a 14-day right of withdrawal.",e:"False: a trade fair stand counts as business premises. Buyers there are not taken by surprise as with a doorstep sale or a promotional trip – so the special right of withdrawal does not apply."},hu:{q:"A vásári standon történő vásárlás üzlethelyiségen kívül kötött ügyletnek számít, ezért 14 napos elállási jog jár.",e:"Hamis: a vásári stand üzlethelyiségnek számít. Az ott vásárlót nem „rohanják le” úgy, mint egy házaló kereskedőnél vagy egy reklámúton – ezért a különleges elállási jog nem érvényes."}},{type:"tf",level:2,correct:!1,de:{q:"Tritt eine Kundin von einem Onlinekauf zurück, muss in jedem Fall der Verkäufer die Kosten der Rücksendung tragen.",e:"Falsch: Wurde die Kundin vorher darüber informiert, trägt SIE die Kosten der Rücksendung. Der Verkäufer muss dann den Kaufpreis zurückzahlen."},en:{q:"If a customer withdraws from an online purchase, the seller always has to pay the cost of returning the goods.",e:"False: if the customer was informed about this beforehand, SHE bears the return costs. The seller must then refund the purchase price."},hu:{q:"Ha egy vevő eláll egy online vásárlástól, a visszaküldés költségét minden esetben az eladónak kell viselnie.",e:"Hamis: ha a vevőt előre tájékoztatták erről, a visszaküldés költségét Ő viseli. Az eladónak ezután vissza kell fizetnie a vételárat."}},{type:"multi",level:1,correct:[0,1,3],de:{q:"Was gilt für das besondere Rücktrittsrecht von Konsument:innen im Fernabsatz? Wähle alle zutreffenden Aussagen.",o:["Man muss keine Gründe angeben","Es darf keine Stornogebühr verlangt werden","Es gilt auch für jeden Kauf im Geschäftslokal","Die Frist beträgt grundsätzlich 14 Kalendertage","Der Rücktritt ist nur per eingeschriebenem Brief gültig"],e:"Im Fernabsatz und bei Geschäften außerhalb der Geschäftsräume kann man binnen 14 Kalendertagen ohne Gründe und ohne Stornogebühr zurücktreten. Für Käufe im Geschäftslokal gilt das nicht, und eine bestimmte Form ist nicht vorgeschrieben."},en:{q:"What applies to consumers' special right of withdrawal in distance selling? Select all that apply.",o:["No reasons have to be given","No cancellation fee may be charged","It also applies to every purchase in a shop","The period is generally 14 calendar days","Withdrawal is only valid by registered letter"],e:"For distance contracts and contracts concluded off business premises, consumers can withdraw within 14 calendar days without reasons and without a cancellation fee. This does not apply to purchases in a shop, and no particular form is required."},hu:{q:"Mi érvényes a fogyasztók különleges elállási jogára távértékesítésnél? Válaszd ki az összes helyes állítást.",o:["Nem kell indokot megadni","Nem kérhető lemondási díj","Minden üzletben történő vásárlásra is vonatkozik","A határidő alapvetően 14 naptári nap","Az elállás csak ajánlott levélben érvényes"],e:"Távértékesítésnél és üzlethelyiségen kívül kötött ügyleteknél 14 naptári napon belül indoklás és lemondási díj nélkül lehet elállni. Üzletben történő vásárlásra ez nem vonatkozik, és meghatározott forma sem kötelező."}},{type:"multi",level:3,correct:[0,1,3,5],de:{q:"Bei welchen Geschäften gibt es trotz Fernabsatz bzw. Auswärtsgeschäft KEIN Rücktrittsrecht? Wähle alle zutreffenden.",o:["Online bestellte Pizza, die nach Hause geliefert wird","Maßgeschneidertes Hochzeitskleid","Online bestellte Jacke in Standardgröße","Konzertkarte für einen bestimmten Termin","Staubsauger, gekauft auf einer Werbefahrt","Software-DVD, deren Siegel geöffnet wurde"],e:"Ausgenommen sind Lebensmittel-Hauszustellungen, Sonderanfertigungen, entsiegelte Software/CDs/DVDs, dringende Reparaturen und Freizeitdienstleistungen mit fixem Termin. Die Standard-Jacke und der Staubsauger von der Werbefahrt fallen dagegen voll unter das Rücktrittsrecht."},en:{q:"For which transactions is there NO right of withdrawal despite distance selling or an off-premises contract? Select all that apply.",o:["Pizza ordered online and delivered to your home","Tailor-made wedding dress","Jacket in a standard size ordered online","Concert ticket for a specific date","Vacuum cleaner bought on a promotional trip","Software DVD whose seal has been opened"],e:"Exceptions are home deliveries of food, custom-made goods, unsealed software/CDs/DVDs, urgent repairs and leisure services for a fixed date. The standard jacket and the vacuum cleaner from the promotional trip, by contrast, are fully covered by the right of withdrawal."},hu:{q:"Mely ügyleteknél NINCS elállási jog annak ellenére, hogy távértékesítésről vagy üzlethelyiségen kívül kötött szerződésről van szó? Válaszd ki az összes helyeset.",o:["Online rendelt, házhoz szállított pizza","Méretre szabott esküvői ruha","Online rendelt, normál méretű dzseki","Koncertjegy egy meghatározott időpontra","Reklámúton vásárolt porszívó","Szoftver-DVD, amelynek a zárócímkéjét feltörték"],e:"Kivételt jelent az élelmiszerek házhoz szállítása, az egyedi gyártás, a felbontott szoftver/CD/DVD, a sürgős javítás és az időponthoz kötött szabadidős szolgáltatás. A normál méretű dzsekire és a reklámúton vett porszívóra viszont teljes mértékben vonatkozik az elállási jog."}},{type:"match",level:2,de:{q:"Ordne jeden Fall dem passenden Weg der Vertragsauflösung zu.",p:[["Händlerin nimmt ein Kleid aus Kulanz zurück","Abänderung (einvernehmliche Auflösung)"],["Reise wegen Krankheit gegen Gebühr abgesagt","Stornierung"],["Verkäufer verschwieg bewusst einen Unfallschaden","Rücktritt wegen arglistiger Täuschung"],["Vertreter verkauft an der Haustür ein Abo","Besonderes Rücktrittsrecht (14 Tage)"]],e:"Sind beide einverstanden, ist es eine Abänderung; gegen Stornogebühr eine Stornierung. Arglistige Täuschung berechtigt allgemein zum Rücktritt, und beim Haustürgeschäft schützt das besondere Rücktrittsrecht für Konsument:innen."},en:{q:"Match each case with the right way of ending the contract.",p:[["Shop owner takes back a dress as a goodwill gesture","Modification (termination by mutual consent)"],["Trip cancelled due to illness, for a fee","Cancellation"],["Seller deliberately concealed accident damage","Withdrawal due to fraudulent misrepresentation"],["Sales rep sells a subscription at the door","Special right of withdrawal (14 days)"]],e:"If both agree, it is a modification; for a cancellation fee it is a cancellation. Fraudulent misrepresentation generally entitles the buyer to withdraw, and for doorstep sales consumers are protected by the special right of withdrawal."},hu:{q:"Párosítsd az eseteket a szerződés felbontásának megfelelő módjával.",p:[["Az eladó méltányosságból visszaveszi a ruhát","Módosítás (közös megegyezéses felbontás)"],["Betegség miatt díj ellenében lemondott utazás","Lemondás (sztornó)"],["Az eladó szándékosan elhallgatta a baleseti kárt","Elállás csalárd megtévesztés miatt"],["Ügynök az ajtóban előfizetést ad el","Különleges elállási jog (14 nap)"]],e:"Ha mindkét fél egyetért, módosításról van szó; lemondási díj ellenében lemondásról. A csalárd megtévesztés általánosan elállásra jogosít, házaló értékesítésnél pedig a fogyasztók különleges elállási joga véd."}},{type:"mc",level:2,correctIndex:0,de:{q:"Herr Berger kauft auf einer Werbefahrt eine Heizdecke um 290 €. Er wird ordnungsgemäß über sein Rücktrittsrecht informiert und nimmt die Decke gleich mit. Neun Tage später bereut er den Kauf. Was gilt?",o:["Rücktritt möglich – ohne Gründe und ohne Gebühr","Kein Rücktritt, weil er die Ware sofort mitgenommen hat","Rücktritt möglich, aber nur gegen eine Stornogebühr","Kein Rücktritt, denn das gilt nur für Onlinekäufe"],e:"Eine Werbefahrt ist ein Geschäft außerhalb der Geschäftsräume. Wurde die Ware sofort übergeben, läuft die 14-tägige Frist ab Vertragsabschluss – nach neun Tagen ist sie noch offen. Der Rücktritt ist ohne Gründe und ohne Stornogebühr möglich."},en:{q:"Mr Berger buys an electric blanket for €290 on a promotional trip. He is properly informed about his right of withdrawal and takes the blanket with him straight away. Nine days later he regrets the purchase. What applies?",o:["Withdrawal possible – without reasons and without a fee","No withdrawal, because he took the goods with him at once","Withdrawal possible, but only for a cancellation fee","No withdrawal, because that only applies to online purchases"],e:"A promotional trip is a contract concluded off business premises. If the goods were handed over immediately, the 14-day period runs from the conclusion of the contract – after nine days it is still open. He can withdraw without reasons and without a cancellation fee."},hu:{q:"Berger úr egy reklámúton 290 €-ért elektromos melegítőtakarót vesz. Szabályszerűen tájékoztatják az elállási jogáról, és a takarót azonnal magával viszi. Kilenc nappal később megbánja a vásárlást. Mi érvényes?",o:["Elállhat – indoklás és díj nélkül","Nem állhat el, mert az árut azonnal magával vitte","Elállhat, de csak lemondási díj ellenében","Nem állhat el, mert ez csak online vásárlásra vonatkozik"],e:"A reklámút üzlethelyiségen kívül kötött ügyletnek számít. Ha az árut azonnal átadták, a 14 napos határidő a szerződéskötéstől fut – kilenc nap után még nem járt le. Az elállás indoklás és lemondási díj nélkül lehetséges."}},{type:"mc",level:3,correctIndex:1,de:{q:"Eine Kundin bestellt online Sneaker, die am 2. März geliefert werden. Über ihr Rücktrittsrecht wurde sie nicht informiert. Am 10. Juni schickt der Shop die Belehrung per E-Mail nach. Bis wann kann sie zurücktreten?",o:["Gar nicht mehr – die Frist endete schon am 16. März","Bis 24. Juni – 14 Tage ab Erhalt der Belehrung","Bis 16. März des Folgejahres – 1 Jahr plus 14 Tage","Bis 10. Juli – 30 Tage ab Erhalt der E-Mail"],e:"Ohne Belehrung verlängert sich die Frist auf 1 Jahr + 14 Tage. Holt der Händler die Information innerhalb dieses Jahres nach, endet die Frist 14 Tage nach Erhalt der Belehrung (FAGG) – hier also am 24. Juni. Die verlängerte Frist gilt nur, solange nicht nachträglich informiert wird."},en:{q:"A customer orders sneakers online, which are delivered on 2 March. She was not informed about her right of withdrawal. On 10 June the shop sends the information by email. Until when can she withdraw?",o:["Not at all – the period already ended on 16 March","Until 24 June – 14 days after receiving the information","Until 16 March of the following year – 1 year plus 14 days","Until 10 July – 30 days after receiving the email"],e:"Without information, the period is extended to 1 year + 14 days. If the seller provides the information within that year, the period ends 14 days after it is received (FAGG) – here on 24 June. The extended period only applies as long as no information is provided later."},hu:{q:"Egy vevő online sportcipőt rendel, amelyet március 2-án szállítanak ki. Az elállási jogáról nem tájékoztatták. A webáruház június 10-én e-mailben pótolja a tájékoztatást. Meddig állhat el?",o:["Már egyáltalán nem – a határidő március 16-án lejárt","Június 24-ig – 14 nap a tájékoztatás kézhezvételétől","A következő év március 16-ig – vagyis 1 év plusz 14 nap","Július 10-ig – az e-mail kézhezvételétől számított 30 napig"],e:"Tájékoztatás hiányában a határidő 1 év + 14 napra hosszabbodik. Ha az eladó ezen az éven belül pótolja a tájékoztatást, a határidő a kézhezvételtől számított 14 nap múlva jár le (FAGG) – itt június 24-én. A meghosszabbított határidő csak addig él, amíg utólag nem tájékoztatnak."}},{type:"mc",level:3,correctIndex:2,de:{q:"Lena bestellt online ein Abendkleid, trägt es auf einer Hochzeit und tritt danach innerhalb der 14 Tage vom Vertrag zurück. Was gilt?",o:["Rücktritt ausgeschlossen, weil das Kleid schon getragen wurde","Rücktritt möglich, der volle Preis muss erstattet werden","Rücktritt möglich, aber mit Entschädigung für die Benützung","Rücktritt möglich, Lena bekommt aber nur einen Gutschein"],e:"Das Rücktrittsrecht bleibt bestehen, doch wurde die Ware benutzt oder verbraucht, darf der Verkäufer eine Entschädigung (für den Wertverlust) verlangen. Ein Gutschein statt Geld ist beim gesetzlichen Rücktritt nicht zulässig – der Verkäufer muss das Geld zurückzahlen."},en:{q:"Lena orders an evening dress online, wears it at a wedding and then withdraws from the contract within the 14 days. What applies?",o:["Withdrawal excluded because the dress has already been worn","Withdrawal possible, the full price must be refunded","Withdrawal possible, the seller may claim compensation","Withdrawal possible, but Lena only gets a voucher"],e:"The right of withdrawal remains, but if the goods were used or consumed, the seller may claim compensation (for the loss in value). A voucher instead of money is not allowed for a statutory withdrawal – the seller must refund the money."},hu:{q:"Léna online rendel egy estélyi ruhát, felveszi egy esküvőn, majd a 14 napon belül eláll a szerződéstől. Mi érvényes?",o:["Az elállás kizárt, mert a ruhát használták","Elállhat, és a teljes árat vissza kell téríteni","Elállhat, de az eladó kártérítést kérhet","Elállhat, de Léna csak utalványt kap"],e:"Az elállási jog megmarad, de ha az árut használták vagy elfogyasztották, az eladó kártérítést (az értékcsökkenésért) követelhet. Törvényes elállásnál utalvány a pénz helyett nem megengedett – az eladónak vissza kell fizetnie a pénzt."}},{type:"number",level:1,value:26,tol:0,de:{q:"Eine Kundin bestellt in einem Onlineshop eine Jacke und wurde korrekt über ihr Rücktrittsrecht informiert. Die Jacke wird am 12. Oktober geliefert. Bis zu welchem Tag im Oktober kann sie zurücktreten? (Gib nur die Tageszahl an.)",e:"Wird Ware geliefert, läuft die Frist 14 Kalendertage ab Lieferung: 12 + 14 = 26. Rücktritt ist also bis 26. Oktober möglich (wie im Beispiel: Lieferung 7. August → bis 21. August)."},en:{q:"A customer orders a jacket from an online shop and was correctly informed about her right of withdrawal. The jacket is delivered on 12 October. Until which day in October can she withdraw? (Enter only the day number.)",e:"If goods are delivered, the period is 14 calendar days from delivery: 12 + 14 = 26. So withdrawal is possible until 26 October (as in the example: delivered 7 August → until 21 August)."},hu:{q:"Egy vevő dzsekit rendel egy webáruházból, és szabályszerűen tájékoztatták az elállási jogáról. A dzsekit október 12-én szállítják ki. Október hányadikáig állhat el? (Csak a nap számát add meg.)",e:"Kiszállított árunál a határidő a kiszállítástól számított 14 naptári nap: 12 + 14 = 26. Az elállás tehát október 26-ig lehetséges (mint a példában: kiszállítás augusztus 7. → augusztus 21-ig)."}}],"bestandteile-kaufvertrag":[{type:"tf",level:1,correct:!1,de:{q:"Ein Gebrauchtwagen ist eine vertretbare (fungible) Ware.",e:"Falsch: Ein Gebrauchtwagen ist einzigartig (Kilometerstand, Zustand, Schäden) und muss genau besichtigt werden – er ist nicht vertretbar. Vertretbar sind gleichwertig ersetzbare Waren wie ein neues Handy oder ein A4-Schulheft."},en:{q:"A used car is a fungible (replaceable) good.",e:"False: a used car is unique (mileage, condition, damage) and must be inspected carefully – it is not fungible. Fungible goods can be replaced by equivalent ones, like a new mobile phone or an A4 exercise book."},hu:{q:"A használt autó helyettesíthető (fungibilis) áru.",e:"Hamis: a használt autó egyedi (futásteljesítmény, állapot, sérülések), ezért pontosan meg kell tekinteni – nem helyettesíthető. Helyettesíthető az egyenértékűen pótolható áru, például egy új mobiltelefon vagy egy A4-es füzet."}},{type:"tf",level:2,correct:!0,de:{q:"Ist im Kaufvertrag kein Liefertermin vereinbart, muss der Verkäufer sofort liefern.",e:"Richtig: Ohne Vereinbarung gilt das Promptgeschäft – Lieferung sofort. Ein Fixgeschäft (genauer Termin) oder Termingeschäft (ungefährer Termin) muss ausdrücklich vereinbart werden."},en:{q:"If no delivery date is agreed in the contract of sale, the seller must deliver immediately.",e:"True: without an agreement, a spot transaction (Promptgeschäft) applies – immediate delivery. A fixed-date or forward transaction must be agreed explicitly."},hu:{q:"Ha az adásvételi szerződésben nem állapodtak meg a szállítási időpontról, az eladónak azonnal szállítania kell.",e:"Igaz: megállapodás hiányában azonnali ügylet érvényes – azonnali szállítás. A fix határidős ügyletet (pontos időpont) vagy a határidős ügyletet (hozzávetőleges időpont) kifejezetten ki kell kötni."}},{type:"tf",level:3,correct:!1,de:{q:"AGB werden auch dann Vertragsinhalt, wenn die Käuferin sie erst nach Vertragsabschluss auf der Rückseite der Rechnung erhält.",e:"Falsch: AGB gelten nur, wenn die Käuferin sie VOR Vertragsabschluss kennen konnte. Auf der Rechnung kommen sie zu spät – der Vertrag ist da schon geschlossen."},en:{q:"Terms and conditions become part of the contract even if the buyer only receives them on the back of the invoice after the contract was concluded.",e:"False: terms and conditions only apply if the buyer could know them BEFORE the contract was concluded. On the invoice they come too late – the contract has already been made."},hu:{q:"Az ÁSZF akkor is a szerződés részévé válik, ha a vevő csak a szerződéskötés után, a számla hátoldalán kapja meg.",e:"Hamis: az ÁSZF csak akkor érvényes, ha a vevő a szerződéskötés ELŐTT megismerhette. A számlán már túl késő – a szerződés addigra létrejött."}},{type:"multi",level:2,correct:[0,1,3],de:{q:"Welche Vereinbarungen führen zu einem freibleibenden (nicht festen) Preis? Wähle alle zutreffenden.",o:["Wertsicherungsklausel (Bindung an den Verbraucherpreisindex)","Heizöl zum Tagespreis an der Börse","Fixpreis von 12 € pro Stück","Kostenschwankungsklausel beim Hausbau","Mengenrabatt von 5 % ab 100 Stück"],e:"Freibleibend ist ein Preis, der sich nach Vertragsabschluss noch ändern kann: Markt-/Börsenpreis, Wertsicherungsklausel, Basiskauf, Kostenschwankungsklausel. Ein Fixpreis ist fest, und ein Mengenrabatt ist ein Preisnachlass, keine Preisanpassung."},en:{q:"Which agreements lead to a variable (not fixed) price? Select all that apply.",o:["Value-protection clause (linked to the consumer price index)","Heating oil at the daily exchange price","Fixed price of €12 per piece","Cost-fluctuation clause when building a house","5% quantity discount from 100 pieces"],e:"A price is variable if it can still change after the contract: market/exchange price, value-protection clause, basis purchase, cost-fluctuation clause. A fixed price is fixed, and a quantity discount is a price reduction, not a price adjustment."},hu:{q:"Mely megállapodások eredményeznek változó (nem rögzített) árat? Válaszd ki az összes helyeset.",o:["Értékállandósági záradék (a fogyasztói árindexhez kötve)","Fűtőolaj a tőzsdei napi áron","Darabonként 12 € fix ár","Költségingadozási záradék házépítésnél","5% mennyiségi engedmény 100 darabtól"],e:"Változó az az ár, amely a szerződéskötés után még változhat: piaci/tőzsdei ár, értékállandósági záradék, bázisvétel, költségingadozási záradék. A fix ár rögzített, a mennyiségi engedmény pedig árengedmény, nem árkiigazítás."}},{type:"multi",level:1,correct:[0,2,4],de:{q:"Welche Rabattarten werden wegen großer Abnahmemengen gewährt? Wähle alle zutreffenden.",o:["Mengenrabatt","Treuerabatt","Umsatzbonus am Jahresende","Einführungsrabatt","Naturalrabatt"],e:"Mengenrabatt, Schlussrabatt, Naturalrabatt (Drauf-/Dreingabe) und Umsatzbonus belohnen große Mengen. Der Treuerabatt belohnt Stammkund:innen, der Einführungsrabatt ein besonderes Ereignis (neues Produkt)."},en:{q:"Which types of discount are granted because of large purchase quantities? Select all that apply.",o:["Quantity discount","Loyalty discount","Year-end turnover bonus","Introductory discount","Discount in kind"],e:"Quantity discount, final discount, discount in kind (extra goods) and turnover bonus reward large quantities. A loyalty discount rewards regular customers, an introductory discount a special event (new product)."},hu:{q:"Mely engedményfajtákat adják nagy vásárolt mennyiség miatt? Válaszd ki az összes helyeset.",o:["Mennyiségi engedmény","Hűségkedvezmény","Év végi forgalmi bónusz","Bevezető engedmény","Természetbeni engedmény"],e:"A mennyiségi engedmény, a záró engedmény, a természetbeni engedmény (ráadás) és a forgalmi bónusz a nagy mennyiséget jutalmazza. A hűségkedvezmény a törzsvásárlókat, a bevezető engedmény egy különleges eseményt (új termék) jutalmaz."}},{type:"order",level:2,de:{q:"Bringe die Zeilen der Bezugskalkulation in die richtige Reihenfolge.",o:["Listeneinkaufspreis","− Lieferantenrabatt","= Zieleinkaufspreis","− Lieferantenskonto","= Kassaeinkaufspreis","+ Bezugskosten","= Einstandspreis"],e:"Zuerst wird vom Listenpreis der Rabatt abgezogen (Zieleinkaufspreis), dann das Skonto vom bereits rabattierten Betrag (Kassaeinkaufspreis). Erst zum Schluss kommen die Bezugskosten dazu – das Ergebnis ist der Einstandspreis."},en:{q:"Put the lines of the purchase price calculation in the correct order.",o:["List purchase price","− Supplier discount","= Target purchase price","− Supplier cash discount","= Cash purchase price","+ Acquisition costs","= Landed cost price"],e:"First the discount is deducted from the list price (target purchase price), then the cash discount from the already discounted amount (cash purchase price). Only at the end are acquisition costs added – the result is the landed cost price."},hu:{q:"Állítsd helyes sorrendbe a beszerzési kalkuláció sorait.",o:["Listás beszerzési ár","− szállítói engedmény","= célbeszerzési ár","− szállítói skontó","= készpénzes beszerzési ár","+ beszerzési költségek","= bekerülési ár"],e:"Először a listaárból vonjuk le az engedményt (célbeszerzési ár), majd a skontót a már csökkentett összegből (készpénzes beszerzési ár). A beszerzési költségeket csak a végén adjuk hozzá – az eredmény a bekerülési ár."}},{type:"match",level:1,de:{q:"Ordne jede Kaufart der passenden Bedeutung zu.",p:[["Kauf nach Probe","Ware muss genau wie die Probe sein"],["Kauf auf Probe","Rückgabe innerhalb einer Frist möglich"],["Kauf zur Probe","Kleine Menge testen, keine Rückgabe"],["Spezifikationskauf","Käufer legt Größe/Farbe erst später fest"]],e:"Nach Probe = Probe bestimmt die Qualität (Fliesenmuster); auf Probe = Testen mit Rückgaberecht (Matratze); zur Probe = kleine Testmenge ohne Rückgabe (Wandfarbe). Beim Spezifikationskauf bestimmt der Käufer Details nachträglich."},en:{q:"Match each type of purchase with its meaning.",p:[["Sale by sample","Goods must be exactly like the sample"],["Sale on approval","Return possible within a period"],["Trial purchase","Test a small quantity, no return"],["Purchase by specification","Buyer sets size/colour later"]],e:"By sample = the sample sets the quality (tile sample); on approval = testing with a right to return (mattress); trial purchase = small test quantity without return (wall paint). In a purchase by specification the buyer decides details later."},hu:{q:"Párosítsd a vételfajtákat a jelentésükkel.",p:[["Minta szerinti vétel","Az árunak pontosan olyannak kell lennie, mint a minta"],["Próbára vétel","Határidőn belül visszaadható"],["Kipróbálásra vétel","Kis mennyiség kipróbálása, nincs visszaadás"],["Specifikációs vétel","A méretet/színt a vevő később határozza meg"]],e:"Minta szerinti = a minta határozza meg a minőséget (csempeminta); próbára = kipróbálás visszaadási joggal (matrac); kipróbálásra = kis tesztmennyiség visszaadás nélkül (falfesték). Specifikációs vételnél a vevő utólag határozza meg a részleteket."}},{type:"mc",level:2,correctIndex:1,de:{q:"Loopy bestellt 100 kg Zucker. Der Großhändler liefert 100 kg, stellt aber nur 95 kg in Rechnung. Wie nennt man diesen Naturalrabatt?",o:["Draufgabe","Dreingabe","Skonto","Kauf in Bausch und Bogen"],e:"Bei der Dreingabe wird weniger verrechnet als geliefert (100 kg geliefert, 95 kg bezahlt). Bei der Draufgabe wird mehr geliefert als bezahlt (z. B. 100 kg bezahlt, 105 kg geliefert). Skonto ist ein Abzug für schnelles Zahlen."},en:{q:"Loopy orders 100 kg of sugar. The wholesaler delivers 100 kg but only invoices 95 kg. What is this discount in kind called?",o:["Draufgabe (extra goods delivered)","Dreingabe (less invoiced)","Cash discount","Purchase in bulk (Bausch und Bogen)"],e:"With a Dreingabe less is invoiced than delivered (100 kg delivered, 95 kg paid). With a Draufgabe more is delivered than paid (e.g. 100 kg paid, 105 kg delivered). A cash discount is a deduction for fast payment."},hu:{q:"Loopy 100 kg cukrot rendel. A nagykereskedő 100 kg-ot szállít, de csak 95 kg-ot számláz ki. Hogyan nevezzük ezt a természetbeni engedményt?",o:["Ráadás (Draufgabe)","Kedvezményes mennyiség (Dreingabe)","Skontó (készpénzfizetési engedmény)","Egy tételben történő vétel"],e:"Kedvezményes mennyiség (Dreingabe) esetén kevesebbet számláznak, mint amennyit szállítanak (100 kg szállítva, 95 kg kifizetve). Ráadásnál (Draufgabe) többet szállítanak, mint amennyit kifizettek (pl. 100 kg kifizetve, 105 kg szállítva). A skontó a gyors fizetésért járó levonás."}},{type:"mc",level:3,correctIndex:1,de:{q:"Ein Linzer Lieferant verkauft Loopy (Graz) Maschinenteile „frachtfrei Bahnhof Graz“. Auf der Bahnfahrt zwischen Linz und Graz wird die Ware beschädigt. Wer trägt das Risiko?",o:["Der Lieferant, weil er die Frachtkosten bis Graz bezahlt","Loopy, weil das Risiko beim ersten Frachtführer übergeht","Beide je zur Hälfte, weil es eine Zweipunktklausel ist","Der Lieferant, weil Loopy die Ware noch nicht hat"],e:"„Frachtfrei Bahnhof …“ ist eine Zweipunktklausel: Die Kosten trägt der Verkäufer bis Bahnhof Graz, das Risiko geht aber schon mit Übergabe an den ersten Frachtführer (in Linz) auf die Käuferin über. Wer die Fracht zahlt, trägt hier also nicht automatisch das Risiko."},en:{q:"A supplier in Linz sells machine parts to Loopy (Graz) “carriage paid to Graz station”. During the rail journey between Linz and Graz the goods are damaged. Who bears the risk?",o:["The supplier, because he pays freight to Graz","Loopy, because the risk passes at the first carrier","Both half each, because it is a two-point clause","The supplier, because Loopy doesn't have the goods yet"],e:"“Carriage paid to … station” is a two-point clause: the seller bears the costs up to Graz station, but the risk passes to the buyer as soon as the goods are handed to the first carrier (in Linz). Paying the freight therefore does not automatically mean bearing the risk."},hu:{q:"Egy linzi beszállító gépalkatrészeket ad el Loopynak (Graz) „fuvarköltség fizetve grazi állomásig” feltétellel. A Linz és Graz közötti vasúti úton az áru megsérül. Ki viseli a kockázatot?",o:["A beszállító, mert ő fizeti a fuvart Grazig","Loopy, mert a kockázat az első fuvarozónál átszáll","Fele-fele arányban, mert kétpontos záradékról van szó","A beszállító, mert Loopynál még nincs ott az áru"],e:"A „fuvarköltség fizetve … állomásig” kétpontos záradék: a költséget az eladó viseli a grazi állomásig, a kockázat viszont már az első fuvarozónak (Linzben) történő átadáskor átszáll a vevőre. Aki a fuvart fizeti, itt tehát nem automatikusan viseli a kockázatot is."}},{type:"mc",level:3,correctIndex:3,de:{q:"Loopy verschickt eine Pralinenbox an eine Privatkundin in Salzburg. Über den Erfüllungsort wurde nichts vereinbart. Das Paket geht bei der Post verloren. Wer trägt das Risiko?",o:["Die Kundin, weil die Ware dem Frachtführer übergeben wurde","Die Post allein, Loopy und die Kundin sind nicht betroffen","Die Kundin, weil sie die Lieferung bestellt hat","Loopy, weil bei B2C erst die Übergabe an die Kundin zählt"],e:"Ohne Vereinbarung ist der Erfüllungsort bei B2C die Übergabe an die Käuferin – bis dahin trägt der Verkäufer das Risiko, Loopy muss also nochmals liefern. Die Übergabe an den Frachtführer zählt nur im B2B-Geschäft."},en:{q:"Loopy sends a praline box to a private customer in Salzburg. Nothing was agreed about the place of performance. The parcel is lost by the post. Who bears the risk?",o:["The customer, because the goods were handed to the carrier","The post alone; Loopy and the customer are not affected","The customer, because she ordered the delivery","Loopy, because in B2C only handover to the customer counts"],e:"Without an agreement, the place of performance in B2C is the handover to the buyer – until then the seller bears the risk, so Loopy has to deliver again. Handover to the carrier only counts in B2B."},hu:{q:"Loopy egy bonbonos dobozt küld egy salzburgi magánvásárlónak. A teljesítési helyről nem állapodtak meg. A csomag elvész a postán. Ki viseli a kockázatot?",o:["A vevő, mert az árut átadták a fuvarozónak","Egyedül a posta, Loopyt és a vevőt ez nem érinti","A vevő, mert ő rendelte meg a kiszállítást","Loopy, mert B2C-ben a vevőnek való átadás számít"],e:"Megállapodás hiányában B2C-ben a teljesítési hely a vevőnek történő átadás – addig az eladó viseli a kockázatot, Loopynak tehát újra kell szállítania. A fuvarozónak történő átadás csak B2B-ben számít."}},{type:"number",level:2,value:25.71,tol:.01,unit:{de:"%",en:"%",hu:"%"},de:{q:"Eine Rechnung lautet: „Zahlbar binnen 10 Tagen mit 2,5 % Skonto oder 45 Tage netto.“ Wie hoch ist die Jahresverzinsung des Skontos? (Auf 2 Dezimalstellen runden)",e:"Skonto % / (Zahlungsziel − Kassafrist) · 360 = 2,5 / (45 − 10) · 360 = 2,5 / 35 · 360 = 25,71 % p. a. Das ist viel mehr als die Zinsen eines Bankkredits – Skonto ausnützen lohnt sich."},en:{q:"An invoice states: “Payable within 10 days less 2.5% cash discount or 45 days net.” What is the annual interest rate of the cash discount? (Round to 2 decimal places)",e:"Discount % / (payment term − discount period) · 360 = 2.5 / (45 − 10) · 360 = 2.5 / 35 · 360 = 25.71% p.a. That is far more than the interest on a bank loan – taking the discount pays off."},hu:{q:"A számlán ez áll: „Fizetendő 10 napon belül 2,5% skontóval vagy 45 nap nettó.” Mekkora a skontó éves kamatlába? (2 tizedesjegyre kerekítve)",e:"Skontó % / (fizetési határidő − skontóhatáridő) · 360 = 2,5 / (45 − 10) · 360 = 2,5 / 35 · 360 = évi 25,71%. Ez jóval több egy bankhitel kamatánál – megéri kihasználni a skontót."}}],"schriftverkehr-kaufvertrag":[{type:"tf",level:1,correct:!0,de:{q:"Der Lieferschein listet die gelieferten Produkte ohne Preise auf.",e:"Richtig: Der Lieferschein zeigt nur Produkte und Mengen, damit die Übernahme geprüft werden kann. Die Preise stehen erst auf der Rechnung."},en:{q:"The delivery note lists the delivered products without prices.",e:"True: the delivery note only shows products and quantities so that the delivery can be checked. The prices only appear on the invoice."},hu:{q:"A szállítólevél árak nélkül sorolja fel a leszállított termékeket.",e:"Igaz: a szállítólevél csak a termékeket és a mennyiségeket mutatja, hogy az átvételt ellenőrizni lehessen. Az árak csak a számlán szerepelnek."}},{type:"tf",level:1,correct:!0,de:{q:"Mit ihrer Unterschrift auf dem Gegenschein bestätigt die Käuferin die Übernahme der Ware; der Gegenschein geht an den Verkäufer zurück.",e:"Richtig: Der Gegenschein ist eine Kopie des Lieferscheins. Die Unterschrift beweist dem Verkäufer, dass geliefert wurde – der Lieferschein selbst bleibt bei der Käuferin."},en:{q:"By signing the counterfoil (Gegenschein), the buyer confirms receipt of the goods; the counterfoil goes back to the seller.",e:"True: the counterfoil is a copy of the delivery note. The signature proves to the seller that delivery took place – the delivery note itself stays with the buyer."},hu:{q:"Az ellenlevél aláírásával a vevő igazolja az áru átvételét; az ellenlevél visszakerül az eladóhoz.",e:"Igaz: az ellenlevél a szállítólevél másolata. Az aláírás bizonyítja az eladónak, hogy a szállítás megtörtént – maga a szállítólevél a vevőnél marad."}},{type:"tf",level:2,correct:!1,de:{q:"Bestellt ein Kunde aufgrund eines Werbekatalogs, ist der Kaufvertrag schon mit dem Absenden der Bestellung abgeschlossen.",e:"Falsch: Ein Katalog ist eine unverbindliche Anpreisung. Die Bestellung ist dann erst das Angebot des Kunden – der Vertrag kommt erst mit der Auftragsbestätigung zustande (Auftragsbestätigung ALS Abschluss)."},en:{q:"If a customer orders on the basis of an advertising catalogue, the contract of sale is already concluded when the order is sent.",e:"False: a catalogue is a non-binding advertisement. The order is then only the customer's offer – the contract only comes about with the order confirmation (confirmation AS conclusion)."},hu:{q:"Ha egy vevő egy reklámkatalógus alapján rendel, az adásvételi szerződés már a megrendelés elküldésével létrejön.",e:"Hamis: a katalógus nem kötelező érvényű reklám. A megrendelés ilyenkor csak a vevő ajánlata – a szerződés csak a megrendelés-visszaigazolással jön létre (visszaigazolás MINT megkötés)."}},{type:"multi",level:2,correct:[0,1,3],de:{q:"Welche UNTERNEHMENSEXTERNEN Quellen kann ein Käufer nutzen, um neue Lieferanten zu finden? Wähle alle zutreffenden.",o:["Fachmessen","Lieferantensuchmaschinen wie wlw.at","Die eigene Bezugsquellendatei","Wirtschaftskammer (wko.at)","Der eigene Kontoauszug"],e:"Messen, Lieferantensuchmaschinen, die WKO, Kataloge/Werbemails und Geschäftsfreunde sind externe Quellen. Die Bezugsquellendatei ist eine interne Quelle (Infos über bisherige Lieferanten), und ein Kontoauszug hilft bei der Lieferantensuche nicht."},en:{q:"Which EXTERNAL sources can a buyer use to find new suppliers? Select all that apply.",o:["Trade fairs","Supplier search engines such as wlw.at","The company's own supplier file","Chamber of Commerce (wko.at)","The company's own bank statement"],e:"Trade fairs, supplier search engines, the Chamber of Commerce (WKO), catalogues/advertising emails and business contacts are external sources. The supplier file is an internal source (information on previous suppliers), and a bank statement does not help to find suppliers."},hu:{q:"Mely VÁLLALATON KÍVÜLI forrásokat használhat a vevő új beszállítók felkutatására? Válaszd ki az összes helyeset.",o:["Szakvásárok","Beszállítókereső oldalak, pl. wlw.at","A saját beszerzési forrás-nyilvántartás","Gazdasági Kamara (wko.at)","A saját bankszámlakivonat"],e:"A vásárok, a beszállítókereső oldalak, a Gazdasági Kamara (WKO), a katalógusok/reklám e-mailek és az üzleti partnerek külső források. A beszerzési forrás-nyilvántartás belső forrás (adatok a korábbi beszállítókról), a bankszámlakivonat pedig nem segít a beszállítókeresésben."}},{type:"multi",level:3,correct:[0,1,2,4],de:{q:"Welche Angaben muss eine Kleinbetragsrechnung (bis 400 € brutto) enthalten? Wähle alle zutreffenden.",o:["Name und Anschrift des Verkäufers","Ausstellungsdatum","Gesamtbetrag inklusive USt","UID-Nummer des Käufers","Steuersatz","Name und Anschrift des Käufers"],e:"Bei der Kleinbetragsrechnung reichen: Verkäufer, Datum, Menge/Bezeichnung, Gesamtbetrag inkl. USt, Steuersatz und Lieferdatum. Angaben zum Käufer (Name, Anschrift, UID) sind erst bei Rechnungen über 400 € brutto nötig."},en:{q:"Which details must a small-amount invoice (up to €400 gross) contain? Select all that apply.",o:["Name and address of the seller","Date of issue","Total amount including VAT","Buyer's VAT ID number","Tax rate","Name and address of the buyer"],e:"For a small-amount invoice the following are enough: seller, date, quantity/description, total amount incl. VAT, tax rate and date of delivery. Details about the buyer (name, address, VAT ID) are only needed on invoices above €400 gross."},hu:{q:"Milyen adatokat kell tartalmaznia egy egyszerűsített (kis összegű) számlának (bruttó 400 €-ig)? Válaszd ki az összes helyeset.",o:["Az eladó neve és címe","A kiállítás dátuma","Az áfát is tartalmazó végösszeg","A vevő közösségi adószáma","Az adókulcs","A vevő neve és címe"],e:"Az egyszerűsített számlán elég: eladó, dátum, mennyiség/megnevezés, áfát is tartalmazó végösszeg, adókulcs és a szállítás dátuma. A vevő adatai (név, cím, közösségi adószám) csak bruttó 400 € feletti számlán kötelezők."}},{type:"order",level:1,de:{q:"Bringe die Schritte bei der Annahme einer Lieferung in die richtige Reihenfolge.",o:["Produkt annehmen und prüfen","Ware einlagern","Rechnung prüfen","Zahlung freigeben"],e:"Zuerst wird die Ware übernommen und auf Menge und Mängel geprüft, dann eingelagert. Erst danach wird die Rechnung mit Bestellung und Lieferung verglichen – und nur eine korrekte Rechnung wird zur Zahlung freigegeben."},en:{q:"Put the steps for accepting a delivery in the correct order.",o:["Accept and check the product","Store the goods","Check the invoice","Release the payment"],e:"First the goods are accepted and checked for quantity and defects, then stored. Only then is the invoice compared with the order and delivery – and only a correct invoice is released for payment."},hu:{q:"Állítsd helyes sorrendbe a szállítmány átvételének lépéseit.",o:["A termék átvétele és ellenőrzése","Az áru betárolása","A számla ellenőrzése","A fizetés jóváhagyása"],e:"Először átveszik az árut, és ellenőrzik a mennyiséget és a hibákat, majd betárolják. Csak ezután vetik össze a számlát a megrendeléssel és a szállítással – és csak a helyes számlát hagyják jóvá fizetésre."}},{type:"match",level:2,de:{q:"Ordne jedes Schriftstück seiner Funktion zu.",p:[["Anfrage","Käufer bittet unverbindlich um Infos/Angebot"],["Angebot","Verkäufer will zu genannten Bedingungen verkaufen"],["Gegenangebot","Käufer schlägt eigene Bedingungen vor"],["Auftragsbestätigung","Verkäufer wiederholt alle Bestelldaten"],["Gegenschein","Käufer bestätigt die Übernahme mit Unterschrift"]],e:"Anfrage (Käufer) ist unverbindlich, das Angebot (Verkäufer) verbindlich. Mit dem Gegenangebot ändert der Käufer Bedingungen, die Auftragsbestätigung soll Irrtümer vermeiden, und der unterschriebene Gegenschein beweist die Lieferung."},en:{q:"Match each document with its function.",p:[["Enquiry","Buyer asks for info/offer without obligation"],["Offer","Seller wants to sell on the stated terms"],["Counter-offer","Buyer proposes his own terms"],["Order confirmation","Seller repeats all order details"],["Counterfoil","Buyer confirms receipt with a signature"]],e:"The enquiry (buyer) is non-binding, the offer (seller) binding. With a counter-offer the buyer changes terms, the order confirmation helps avoid mistakes, and the signed counterfoil proves delivery."},hu:{q:"Párosítsd az iratokat a funkciójukkal.",p:[["Ajánlatkérés","A vevő kötelezettség nélkül információt/ajánlatot kér"],["Ajánlat","Az eladó a megadott feltételekkel akar eladni"],["Ellenajánlat","A vevő saját feltételeket javasol"],["Megrendelés-visszaigazolás","Az eladó megismétli az összes rendelési adatot"],["Ellenlevél","A vevő aláírással igazolja az átvételt"]],e:"Az ajánlatkérés (vevő) nem kötelező, az ajánlat (eladó) kötelező érvényű. Ellenajánlattal a vevő módosítja a feltételeket, a visszaigazolás a tévedéseket előzi meg, az aláírt ellenlevél pedig a szállítást bizonyítja."}},{type:"mc",level:2,correctIndex:2,de:{q:"Loopy braucht dringend Ostereier-Verpackungen. Anbieter A: 0,42 €/Stück, Lieferzeit 6 Wochen, oft unpünktlich. Anbieter B: 0,44 €/Stück, Lieferzeit 1 Woche, termintreu, 2 % Skonto. Ostern ist in 3 Wochen. Wen sollte Loopy wählen?",o:["A, weil sein Stückpreis am niedrigsten von beiden ist","A, weil man bei langer Lieferzeit später zahlt","B, weil Lieferzeit und Termintreue wichtiger sind","Keinen, weil man immer drei Angebote braucht"],e:"Wer nur Preise vergleicht, findet den billigsten Anbieter – entscheidend ist aber der beste Anbieter. A könnte vor Ostern gar nicht liefern. B ist pünktlich, schnell und durch 2 % Skonto praktisch genauso günstig."},en:{q:"Loopy urgently needs Easter egg packaging. Supplier A: €0.42/piece, delivery time 6 weeks, often late. Supplier B: €0.44/piece, delivery time 1 week, reliable, 2% cash discount. Easter is in 3 weeks. Whom should Loopy choose?",o:["A, because its unit price is the lower of the two","A, because with a long delivery time you pay later","B, because delivery time and reliability matter more","Neither, because you always need three offers"],e:"Comparing only prices finds the cheapest supplier – but what counts is the best supplier. A could not even deliver before Easter. B is punctual, fast and, thanks to the 2% cash discount, practically just as cheap."},hu:{q:"Loopynak sürgősen húsvéti tojáscsomagolásra van szüksége. A ajánlattevő: 0,42 €/db, szállítási idő 6 hét, gyakran késik. B ajánlattevő: 0,44 €/db, szállítási idő 1 hét, pontos, 2% skontó. Húsvét 3 hét múlva van. Kit válasszon Loopy?",o:["A-t, mert az ő darabára a kettő közül alacsonyabb","A-t, mert hosszú szállítási időnél később kell fizetni","B-t, mert a szállítási idő és a pontosság fontosabb","Egyiket sem, mert mindig három ajánlat kell"],e:"Aki csak az árakat hasonlítja össze, a legolcsóbb ajánlattevőt találja meg – a döntő azonban a legjobb ajánlattevő. A húsvét előtt nem is tudna szállítani. B pontos, gyors, és a 2% skontó miatt gyakorlatilag ugyanolyan olcsó."}},{type:"mc",level:3,correctIndex:2,de:{q:"Ein Lkw-Fahrer liefert 20 Kartons Kakaopulver an Loopys Candy Store. Zwei Kartons sind sichtbar eingedrückt und nass. Der Fahrer drängt, schnell zu unterschreiben. Was sollte die Mitarbeiterin tun?",o:["Unterschreiben und den Schaden später per E-Mail melden","Die Unterschrift verweigern und alle 20 Kartons zurückschicken","Schaden auf Liefer- und Gegenschein vermerken, dann unterschreiben","Unterschreiben und dafür die Rechnung einfach um 10 % kürzen"],e:"Erkennbare Mängel müssen sofort auf Liefer- und Gegenschein vermerkt werden – sonst bestätigt die Unterschrift eine einwandfreie Übernahme. Die mangelfreien Kartons sind vertragsgemäß und müssen angenommen werden; die Rechnung darf nur der Aussteller korrigieren."},en:{q:"A lorry driver delivers 20 boxes of cocoa powder to Loopy's Candy Store. Two boxes are visibly dented and wet. The driver urges her to sign quickly. What should the employee do?",o:["Sign now and report the damage later by email","Refuse to sign and send all 20 boxes back at once","Note the damage on both delivery papers, then sign","Sign and simply cut the invoice amount by 10%"],e:"Visible defects must be noted on the delivery note and counterfoil immediately – otherwise the signature confirms a flawless handover. The undamaged boxes conform to the contract and must be accepted; only the issuer may correct the invoice."},hu:{q:"Egy kamionsofőr 20 karton kakaóport szállít Loopy's Candy Store-nak. Két karton láthatóan be van nyomódva és nedves. A sofőr sürgeti, hogy gyorsan írja alá az átvételt. Mit tegyen a munkatárs?",o:["Írja alá, és a kárt csak később jelentse e-mailben","Tagadja meg az aláírást, és küldje vissza mind a 20 kartont","Jegyezze fel a kárt mindkét szállítási okmányra, majd írja alá","Írja alá, és egyszerűen csökkentse a számlát 10%-kal"],e:"A látható hibákat azonnal fel kell jegyezni a szállítólevélre és az ellenlevélre – különben az aláírás hibátlan átvételt igazol. A sértetlen kartonok szerződésszerűek, ezeket át kell venni; a számlát pedig csak a kiállítója javíthatja."}},{type:"number",level:3,value:387.6,tol:.01,unit:{de:"€",en:"€",hu:"€"},de:{q:"Ein Großhändler liefert Loopy 85 Rollen Geschenkband zu je 4,00 € netto. Vereinbart sind 5 % Rabatt, dazu kommen 20 % USt. Wie hoch ist der Rechnungsbetrag brutto?",e:"85 · 4,00 = 340,00 €; − 5 % Rabatt (17,00 €) = 323,00 € netto; + 20 % USt (64,60 €) = 387,60 € brutto. Da der Betrag unter 400 € brutto liegt, darf eine Kleinbetragsrechnung ausgestellt werden."},en:{q:"A wholesaler delivers 85 rolls of gift ribbon to Loopy at €4.00 net each. A 5% discount is agreed, and 20% VAT is added. What is the gross invoice amount?",e:"85 · 4.00 = €340.00; − 5% discount (€17.00) = €323.00 net; + 20% VAT (€64.60) = €387.60 gross. As the amount is below €400 gross, a small-amount invoice may be issued."},hu:{q:"Egy nagykereskedő 85 tekercs díszszalagot szállít Loopynak darabonként nettó 4,00 €-ért. 5% engedményben állapodtak meg, és ehhez jön 20% áfa. Mekkora a bruttó számlaösszeg?",e:"85 · 4,00 = 340,00 €; − 5% engedmény (17,00 €) = nettó 323,00 €; + 20% áfa (64,60 €) = bruttó 387,60 €. Mivel az összeg bruttó 400 € alatt van, egyszerűsített számla is kiállítható."}}],"zahlungsformen-1jg":[{type:"tf",level:1,correct:!0,de:{q:"Bei einem Und-Konto dürfen die Kontoinhaber:innen nur gemeinsam über das Konto verfügen.",e:"Richtig: Beim Und-Konto müssen alle gemeinsam handeln. Beim Oder-Konto darf dagegen jede:r allein verfügen."},en:{q:"With an “and” account, the account holders may only operate the account jointly.",e:"True: with an “and” account all holders must act together. With an “or” account, by contrast, each holder may act alone."},hu:{q:"Az „és”-számla tulajdonosai csak együttesen rendelkezhetnek a számla felett.",e:"Igaz: az „és”-számlánál mindenkinek együtt kell eljárnia. A „vagy”-számlánál viszont mindegyik tulajdonos egyedül is rendelkezhet."}},{type:"tf",level:2,correct:!1,de:{q:"Eine zeichnungsberechtigte Person darf das Girokonto auch auflösen.",e:"Falsch: Zeichnungsberechtigte dürfen Geld abheben, einzahlen und Daueraufträge einrichten – das Konto löschen darf aber nur die verfügungsberechtigte Person (Inhaber:in)."},en:{q:"An authorised signatory may also close the current account.",e:"False: authorised signatories may withdraw and deposit money and set up standing orders – but only the person with full power of disposal (the account holder) may close the account."},hu:{q:"Az aláírási joggal rendelkező személy a folyószámlát meg is szüntetheti.",e:"Hamis: az aláírási jogosult pénzt vehet fel, befizethet és rendszeres átutalást állíthat be – a számlát azonban csak a rendelkezési jogosult (a tulajdonos) szüntetheti meg."}},{type:"tf",level:2,correct:!0,de:{q:"Für eine SEPA-Überweisung von Wien nach Oslo genügt die IBAN des Empfängers, ein BIC ist nicht nötig.",e:"Richtig: Norwegen gehört zum SEPA-Raum (EU plus u. a. Großbritannien, Norwegen, Island, Liechtenstein, Schweiz). Dort reicht die IBAN, und die Überweisung kostet gleich viel wie im Inland."},en:{q:"For a SEPA transfer from Vienna to Oslo the payee's IBAN is enough; no BIC is needed.",e:"True: Norway belongs to the SEPA area (EU plus the UK, Norway, Iceland, Liechtenstein, Switzerland and others). There the IBAN is enough, and the transfer costs the same as a domestic one."},hu:{q:"Egy Bécsből Oslóba indított SEPA-átutaláshoz elég a kedvezményezett IBAN-ja, BIC nem szükséges.",e:"Igaz: Norvégia a SEPA-térség része (EU, valamint többek között az Egyesült Királyság, Norvégia, Izland, Liechtenstein, Svájc). Ott elég az IBAN, és az átutalás ugyanannyiba kerül, mint belföldön."}},{type:"multi",level:1,correct:[0,2,4],de:{q:"Welche Zahlungen eignen sich typischerweise für einen SEPA-Dauerauftrag? Wähle alle zutreffenden.",o:["Monatliche Miete von 850 €","Stromrechnung mit wechselnden Beträgen","Gleichbleibende Kreditrate","Handyrechnung nach Verbrauch","Fixer Monatsbeitrag fürs Fitnessstudio"],e:"Ein Dauerauftrag passt für regelmäßige Zahlungen mit gleichem Betrag – der Zahler bestimmt. Wechselnde Beträge wie Strom oder verbrauchsabhängige Handyrechnungen zahlt man besser per SEPA-Lastschrift, bei der der Empfänger abbucht."},en:{q:"Which payments are typically suitable for a SEPA standing order? Select all that apply.",o:["Monthly rent of €850","Electricity bill with varying amounts","Fixed loan instalment","Mobile phone bill based on usage","Fixed monthly gym fee"],e:"A standing order suits regular payments of the same amount – the payer decides. Varying amounts such as electricity or usage-based phone bills are better paid by SEPA direct debit, where the payee collects the money."},hu:{q:"Mely kifizetésekre alkalmas jellemzően a SEPA rendszeres átutalási megbízás? Válaszd ki az összes helyeset.",o:["850 €-s havi lakbér","Változó összegű villanyszámla","Állandó összegű hiteltörlesztő részlet","Fogyasztásfüggő telefonszámla","Fix havi edzőtermi tagdíj"],e:"A rendszeres átutalás az azonos összegű, rendszeres kifizetésekhez illik – a fizető dönt. A változó összegeket, mint az áram vagy a fogyasztásfüggő telefonszámla, jobb SEPA beszedéssel fizetni, ahol a kedvezményezett szedi be a pénzt."}},{type:"multi",level:2,correct:[0,2,4],de:{q:"Welche Aussagen zur Kreditkarte treffen zu? Wähle alle zutreffenden.",o:["Die Umsätze werden gesammelt am Monatsende abgebucht","Man bekommt sie schon ab 16 Jahren ohne Einkommen","Online zahlt man mit Kartennummer, Ablaufdatum, Prüfziffer und 3D-Secure","Bargeld abheben ist damit besonders günstig","Man kann damit weltweit bezahlen"],e:"Die Kreditkarte funktioniert nach „pay later“, ist weltweit einsetzbar und wird online mit Kartendaten und 3D-Secure verwendet. Sie gibt es nur ab 18 mit regelmäßigem Einkommen, und Bargeldbehebungen damit sind teuer."},en:{q:"Which statements about the credit card are correct? Select all that apply.",o:["Transactions are debited together at the end of the month","You can get one from age 16 without income","Online you pay with card number, expiry date, security code and 3D Secure","Withdrawing cash with it is particularly cheap","You can pay with it worldwide"],e:"The credit card works on a “pay later” basis, can be used worldwide and is used online with card details and 3D Secure. It is only available from 18 with a regular income, and cash withdrawals with it are expensive."},hu:{q:"Mely állítások igazak a hitelkártyára? Válaszd ki az összes helyeset.",o:["A tranzakciókat összesítve a hónap végén terhelik","Már 16 éves kortól, jövedelem nélkül is megkapható","Online kártyaszámmal, lejárati dátummal, ellenőrző kóddal és 3D Secure-ral fizetünk","Különösen olcsó vele készpénzt felvenni","Világszerte lehet vele fizetni"],e:"A hitelkártya „pay later” elven működik, világszerte használható, online pedig a kártyaadatokkal és 3D Secure-ral fizetünk vele. Csak 18 éves kortól, rendszeres jövedelemmel kapható, és a készpénzfelvétel vele drága."}},{type:"order",level:1,de:{q:"Bringe die Schritte einer Zahlung per Nachnahme in die richtige Reihenfolge.",o:["Verkäufer schickt die Ware per Post oder Logistiker","Zusteller übergibt die Ware nur gegen Bezahlung","Zusteller überweist das Geld an den Verkäufer"],e:"Bei der Nachnahme bekommt der Käufer die Ware erst, wenn er beim Zusteller zahlt. Danach leitet der Zusteller das Geld an den Verkäufer weiter – so trägt der Verkäufer kein Zahlungsrisiko."},en:{q:"Put the steps of a cash-on-delivery payment in the correct order.",o:["Seller sends the goods by post or logistics company","Courier hands over the goods only against payment","Courier transfers the money to the seller"],e:"With cash on delivery the buyer only gets the goods once he pays the courier. Then the courier passes the money on to the seller – so the seller bears no payment risk."},hu:{q:"Állítsd helyes sorrendbe az utánvétes fizetés lépéseit.",o:["Az eladó postán vagy futárral elküldi az árut","A kézbesítő csak fizetés ellenében adja át az árut","A kézbesítő átutalja a pénzt az eladónak"],e:"Utánvétnél a vevő csak akkor kapja meg az árut, ha fizet a kézbesítőnek. Ezután a kézbesítő továbbítja a pénzt az eladónak – így az eladó nem visel fizetési kockázatot."}},{type:"match",level:2,de:{q:"Ordne jedes Zahlungsmittel seiner Funktionsweise zu.",p:[["Debitkarte","„pay now“ – sofort vom Konto abgebucht"],["Kreditkarte","„pay later“ – gesammelt am Monatsende"],["Prepaidkarte","„pay before“ – vorher aufgeladenes Guthaben"],["Paysafecard","16-stelliger PIN-Code, keine persönlichen Daten"],["eps","Überweisung mit E-Banking-Zugang direkt im Shop"]],e:"Debit-, Kredit- und Prepaidkarte unterscheiden sich darin, wann gezahlt wird: jetzt, später oder vorher. Paysafecard ist eine anonyme Wertkarte mit PIN-Code, eps eine Online-Überweisung aus dem eigenen E-Banking."},en:{q:"Match each means of payment with how it works.",p:[["Debit card","“pay now” – debited from the account at once"],["Credit card","“pay later” – collected at the end of the month"],["Prepaid card","“pay before” – balance loaded in advance"],["Paysafecard","16-digit PIN code, no personal data"],["eps","Transfer via online banking directly in the shop"]],e:"Debit, credit and prepaid cards differ in when you pay: now, later or beforehand. Paysafecard is an anonymous voucher card with a PIN code, eps an online transfer from your own online banking."},hu:{q:"Párosítsd a fizetőeszközöket a működésükkel.",p:[["Betéti kártya","„pay now” – azonnal terhelik a számlát"],["Hitelkártya","„pay later” – összesítve a hónap végén"],["Feltöltős kártya","„pay before” – előre feltöltött egyenleg"],["Paysafecard","16 jegyű PIN-kód, személyes adatok nélkül"],["eps","Átutalás netbankkal közvetlenül a webáruházból"]],e:"A betéti, a hitel- és a feltöltős kártya abban különbözik, mikor fizetünk: most, később vagy előre. A Paysafecard anonim értékkártya PIN-kóddal, az eps pedig online átutalás a saját netbankból."}},{type:"mc",level:2,correctIndex:1,de:{q:"Eine Kundin will in Loopys Candy Store einen Geschenkkorb um 62 € kontaktlos mit ihrer Debitkarte bezahlen. Was gilt?",o:["Sie zahlt ohne PIN, weil kontaktlos nie eine PIN nötig ist","Sie muss die PIN eingeben, weil der Betrag über 50 € liegt","Kontaktlos ist über 50 € verboten, sie muss bar zahlen","Sie muss statt der PIN den Beleg unterschreiben"],e:"Kontaktloses Zahlen (NFC) ohne PIN ist nur bis 50 € möglich. Bei 62 € ist die PIN-Eingabe nötig – zahlen kann sie mit der Debitkarte trotzdem."},en:{q:"A customer wants to pay €62 for a gift basket at Loopy's Candy Store contactlessly with her debit card. What applies?",o:["She pays without a PIN, as contactless never needs a PIN","She must enter her PIN because the amount is over €50","Contactless is prohibited above €50, she must pay cash","Instead of a PIN she must sign the receipt"],e:"Contactless payment (NFC) without a PIN is only possible up to €50. For €62 she has to enter her PIN – but she can still pay with the debit card."},hu:{q:"Egy vevő Loopy's Candy Store-ban egy 62 €-s ajándékkosarat szeretne érintéssel kifizetni a betéti kártyájával. Mi érvényes?",o:["PIN nélkül fizet, mert érintéses fizetéshez sosem kell PIN","Meg kell adnia a PIN-kódot, mert az összeg 50 € fölött van","50 € fölött tilos az érintéses fizetés, készpénzzel kell fizetnie","PIN helyett alá kell írnia a bizonylatot"],e:"Érintéses (NFC) fizetés PIN nélkül csak 50 €-ig lehetséges. 62 €-nál meg kell adni a PIN-kódot – a betéti kártyával ettől még fizethet."}},{type:"mc",level:3,correctIndex:1,de:{q:"Eine Kundin ohne eigenes Bankkonto bestellt bei Loopy per Nachnahme. Sie zahlt dem Zusteller bar, und das Geld wird auf Loopys Girokonto überwiesen. Welche Zahlungsart liegt vor?",o:["Barzahlung, weil die Kundin Bargeld übergibt","Halbbare Zahlung, weil nur einer ein Konto hat","Bargeldlose Zahlung, weil Loopy eine Gutschrift erhält","SEPA-Lastschrift, weil der Empfänger das Geld einzieht"],e:"Halbbar heißt: Nur einer der beiden Partner hat ein Konto – die Kundin zahlt bar, Loopy erhält das Geld aufs Konto. Reine Barzahlung wäre eine direkte Übergabe zwischen Schuldnerin und Gläubigerin, bargeldlos setzt voraus, dass beide ein Konto haben."},en:{q:"A customer without a bank account orders from Loopy cash on delivery. She pays the courier in cash, and the money is transferred to Loopy's current account. What type of payment is this?",o:["Cash payment, because the customer hands over cash","Semi-cash payment, as only one party has an account","Cashless payment, because Loopy receives a credit","SEPA direct debit, because the payee collects the money"],e:"Semi-cash means only one of the two parties has an account – the customer pays in cash, Loopy receives the money into her account. A pure cash payment would be a direct handover between debtor and creditor; cashless requires both to have an account."},hu:{q:"Egy bankszámlával nem rendelkező vevő utánvéttel rendel Loopytól. Készpénzzel fizet a kézbesítőnek, és a pénzt átutalják Loopy folyószámlájára. Milyen fizetési módról van szó?",o:["Készpénzes fizetésről, mert a vevő készpénzt ad át","Félkészpénzesről, mert csak az egyik félnek van számlája","Készpénz nélküli fizetésről, mert Loopy jóváírást kap","SEPA beszedésről, mert a kedvezményezett szedi be a pénzt"],e:"Félkészpénzes azt jelenti, hogy a két fél közül csak az egyiknek van számlája – a vevő készpénzzel fizet, Loopy a számlájára kapja a pénzt. A tisztán készpénzes fizetés az adós és a hitelező közötti közvetlen átadás, a készpénz nélküli pedig feltételezi, hogy mindkettőnek van számlája."}},{type:"mc",level:3,correctIndex:0,de:{q:"Loopy wechselt den Stromanbieter. Der alte Anbieter bucht die Stromkosten bisher per SEPA-Lastschrift ab. Wie beendet sie diese Zahlungen richtig?",o:["Sie widerruft die Einzugsermächtigung beim Stromanbieter","Sie löscht bei ihrer Bank den Dauerauftrag an den Anbieter","Gar nicht – eine SEPA-Lastschrift ist unwiderruflich","Sie lässt einfach ihr Konto ins Minus rutschen"],e:"Bei der Lastschrift erteilt der Zahler dem Empfänger eine Einzugsermächtigung (Mandat) – widerrufen wird sie daher beim Empfänger. Den Dauerauftrag richtet man dagegen bei der Bank ein und widerruft ihn auch dort; ein Konto im Minus kostet nur hohe Sollzinsen."},en:{q:"Loopy is switching electricity provider. The old provider has been collecting the electricity costs by SEPA direct debit. How does she end these payments correctly?",o:["She revokes the direct debit mandate with the provider","She deletes the standing order to the provider at her bank","Not at all – a SEPA direct debit is irrevocable","She simply lets her account go into overdraft"],e:"With a direct debit the payer gives the payee a mandate – so it is revoked with the payee. A standing order, by contrast, is set up with the bank and revoked there; an overdrawn account only costs high debit interest."},hu:{q:"Loopy áramszolgáltatót vált. A régi szolgáltató eddig SEPA beszedéssel szedte be az áramdíjat. Hogyan szünteti meg helyesen ezeket a fizetéseket?",o:["Visszavonja a beszedési felhatalmazást az áramszolgáltatónál","A bankjában törli a szolgáltató felé szóló rendszeres átutalást","Sehogy – a SEPA beszedés visszavonhatatlan","Egyszerűen hagyja, hogy a számlája mínuszba csússzon"],e:"Beszedésnél a fizető beszedési felhatalmazást (mandátumot) ad a kedvezményezettnek – ezért azt a kedvezményezettnél kell visszavonni. A rendszeres átutalást viszont a banknál állítják be és ott is vonják vissza; a mínuszos számla csak magas tartozási kamatba kerül."}},{type:"number",level:3,value:9,tol:.01,unit:{de:"€",en:"€",hu:"€"},de:{q:"Loopy hat ein ganzes Jahr lang 4.800 € auf ihrem Konto. Die Bank zahlt 0,25 % Habenzinsen p. a. Davon wird die KESt (25 %) abgezogen. Wie viel Zinsen bekommt Loopy tatsächlich gutgeschrieben?",e:"Habenzinsen: 4.800 · 0,25 % = 12,00 €. KESt: 25 % von 12,00 = 3,00 €. Gutschrift: 12,00 − 3,00 = 9,00 €. Die KESt wird von den Zinsen abgezogen, nicht vom Guthaben."},en:{q:"Loopy has €4,800 in her account for a whole year. The bank pays 0.25% credit interest p.a. Capital gains tax (KESt, 25%) is deducted from it. How much interest is actually credited to Loopy?",e:"Credit interest: 4,800 · 0.25% = €12.00. KESt: 25% of 12.00 = €3.00. Credited: 12.00 − 3.00 = €9.00. The tax is deducted from the interest, not from the balance."},hu:{q:"Loopy számláján egy teljes évig 4800 € van. A bank évi 0,25% betéti kamatot fizet, amelyből levonják a tőkehozadék-adót (KESt, 25%). Mennyi kamatot írnak jóvá ténylegesen Loopynak?",e:"Betéti kamat: 4800 · 0,25% = 12,00 €. Tőkehozadék-adó: 12,00 25%-a = 3,00 €. Jóváírás: 12,00 − 3,00 = 9,00 €. Az adót a kamatból vonják le, nem az egyenlegből."}}],"unzuverlaessige-verkaeufer":[{type:"tf",level:1,correct:!1,de:{q:"Bei einem geringfügigen Mangel kann die Käuferin sofort die Auflösung des Vertrags verlangen.",e:"Falsch: Zuerst gibt es Verbesserung oder Austausch. Und selbst wenn das scheitert, bleibt bei einem geringfügigen Mangel nur die Preisminderung – eine Vertragsauflösung ist ausgeschlossen."},en:{q:"In the case of a minor defect, the buyer can immediately demand termination of the contract.",e:"False: first comes repair or replacement. And even if that fails, a minor defect only entitles the buyer to a price reduction – termination of the contract is excluded."},hu:{q:"Csekély hiba esetén a vevő azonnal követelheti a szerződés felbontását.",e:"Hamis: először kijavítás vagy csere jár. És ha ez nem sikerül, csekély hibánál akkor is csak árleszállítás jár – a szerződés felbontása kizárt."}},{type:"tf",level:1,correct:!1,de:{q:"Ein Elektrohändler darf in seinen AGB die Gewährleistung gegenüber Privatkund:innen ausschließen.",e:"Falsch: Bei B2C-Geschäften darf die Gewährleistung NICHT ausgeschlossen werden. Eine solche AGB-Klausel ist unwirksam."},en:{q:"An electronics retailer may exclude the statutory warranty for private customers in its terms and conditions.",e:"False: in B2C transactions the statutory warranty may NOT be excluded. Such a clause in the terms and conditions is invalid."},hu:{q:"Egy műszaki kereskedő az ÁSZF-ében kizárhatja a szavatosságot a magánvásárlókkal szemben.",e:"Hamis: B2C-ügyleteknél a szavatosság NEM zárható ki. Az ilyen ÁSZF-kikötés érvénytelen."}},{type:"tf",level:3,correct:!0,de:{q:"Auch nach Ablauf der Gewährleistungsfrist bleiben noch 3 Monate Zeit, um die Ansprüche vor Gericht geltend zu machen.",e:"Richtig: Der Mangel muss innerhalb der Gewährleistungsfrist auftreten. Danach gibt es noch eine Verjährungsfrist von 3 Monaten, um die Rechte gerichtlich durchzusetzen."},en:{q:"Even after the statutory warranty period has expired, there are still 3 months left to assert the claims in court.",e:"True: the defect must appear within the warranty period. After that there is a limitation period of 3 more months to enforce the rights in court."},hu:{q:"A szavatossági idő lejárta után még 3 hónap marad arra, hogy az igényeket bíróság előtt érvényesítsék.",e:"Igaz: a hibának a szavatossági időn belül kell jelentkeznie. Ezt követően még 3 hónapos elévülési idő áll rendelkezésre a jogok bírósági érvényesítésére."}},{type:"multi",level:2,correct:[0,1,3],de:{q:"Welche Aussagen zur Produkthaftung treffen zu? Wähle alle zutreffenden.",o:["Es haften Hersteller bzw. Importeur","Sie gilt für Personen- und Sachschäden durch ein fehlerhaftes Produkt","Sie ist freiwillig, ähnlich wie eine Garantie","Bei Sachschäden gibt es einen Selbstbehalt von 500 €","Sie ist im Konsumentenschutzgesetz (KSchG) geregelt"],e:"Die Produkthaftung ist gesetzlich (PHG) und trifft Hersteller/Importeur für Personen- und Sachschäden, mit 500 € Selbstbehalt bei Sachschäden. Freiwillig ist nur die Garantie, und das KSchG regelt die Gewährleistung, nicht die Produkthaftung."},en:{q:"Which statements about product liability are correct? Select all that apply.",o:["The manufacturer or importer is liable","It applies to personal injury and property damage caused by a defective product","It is voluntary, similar to a guarantee","For property damage there is a €500 deductible","It is regulated in the Consumer Protection Act (KSchG)"],e:"Product liability is statutory (PHG) and makes the manufacturer/importer liable for personal injury and property damage, with a €500 deductible for property damage. Only a guarantee is voluntary, and the KSchG deals with the statutory warranty, not product liability."},hu:{q:"Mely állítások igazak a termékfelelősségre? Válaszd ki az összes helyeset.",o:["A gyártó, illetve az importőr felel","A hibás termék által okozott személyi és dologi károkra vonatkozik","Önkéntes, a garanciához hasonlóan","Dologi kárnál 500 € önrész van","A fogyasztóvédelmi törvény (KSchG) szabályozza"],e:"A termékfelelősség törvényi (PHG), és a gyártót/importőrt terheli a személyi és dologi károkért, dologi kárnál 500 € önrésszel. Csak a garancia önkéntes, a KSchG pedig a szavatosságot szabályozza, nem a termékfelelősséget."}},{type:"multi",level:3,correct:[0,1,2],de:{q:"Welche Aussagen zu den Gewährleistungsfristen sind richtig? Wähle alle zutreffenden.",o:["Neuer Laptop: 2 Jahre ab Übergabe","Eigentumswohnung: 3 Jahre","Gebrauchtes Auto: 2 Jahre, auf 1 Jahr verkürzbar","Arglistig verschwiegener Mangel: 5 Jahre","Gebrauchte Sachen: immer nur 6 Monate"],e:"Bewegliche Sachen haben 2 Jahre (bei gebrauchten auf 1 Jahr verkürzbar), unbewegliche 3 Jahre. Bei arglistig verschwiegenen Mängeln beträgt die Frist 30 Jahre, nicht 5. Die 6 Monate betreffen die Beweislastumkehr nach ABGB, nicht die Gewährleistungsfrist."},en:{q:"Which statements about statutory warranty periods are correct? Select all that apply.",o:["New laptop: 2 years from handover","Owner-occupied flat: 3 years","Used car: 2 years, can be shortened to 1 year","Fraudulently concealed defect: 5 years","Used goods: always only 6 months"],e:"Movable goods have 2 years (can be shortened to 1 year for used goods), immovable property 3 years. For fraudulently concealed defects the period is 30 years, not 5. The 6 months refer to the reversal of the burden of proof under the ABGB, not to the warranty period."},hu:{q:"Mely állítások helyesek a szavatossági határidőkről? Válaszd ki az összes helyeset.",o:["Új laptop: 2 év az átadástól","Öröklakás: 3 év","Használt autó: 2 év, 1 évre csökkenthető","Csalárdul elhallgatott hiba: 5 év","Használt dolgok: mindig csak 6 hónap"],e:"Az ingó dolgokra 2 év vonatkozik (használtaknál 1 évre csökkenthető), az ingatlanokra 3 év. Csalárdul elhallgatott hibánál a határidő 30 év, nem 5. A 6 hónap az ABGB szerinti megfordított bizonyítási teherre vonatkozik, nem a szavatossági időre."}},{type:"order",level:2,de:{q:"Loopy hat Verpackungen „innerhalb von 2 Wochen“ bestellt, der Lieferant liefert nicht. Bringe die Schritte bis zum Schadenersatz in die richtige Reihenfolge.",o:["Vereinbarter ungefährer Liefertermin verstreicht","Mahnung mit angemessener Nachfrist (meist 14 Tage)","Nachfrist läuft ohne Lieferung ab","Rücktritt und Deckungskauf bei einem anderen Lieferanten","Mehrkosten als Schadenersatz vom Lieferanten fordern"],e:"Beim gewöhnlichen Termingeschäft treten die Rechtsfolgen erst nach einer Mahnung mit Nachfrist ein. Erst wenn diese verstrichen ist, kann Loopy zurücktreten und woanders kaufen; die Preisdifferenz verlangt sie (bei Verschulden) als Schadenersatz."},en:{q:"Loopy ordered packaging “within 2 weeks”, but the supplier does not deliver. Put the steps up to the claim for damages in the correct order.",o:["The agreed approximate delivery date passes","Reminder with a reasonable grace period (usually 14 days)","The grace period expires without delivery","Withdrawal and cover purchase from another supplier","Claim the extra costs from the supplier as damages"],e:"In an ordinary forward transaction the legal consequences only apply after a reminder with a grace period. Only once it has expired can Loopy withdraw and buy elsewhere; she claims the price difference as damages (if the supplier is at fault)."},hu:{q:"Loopy „2 héten belül” rendelt csomagolóanyagot, de a beszállító nem szállít. Állítsd helyes sorrendbe a lépéseket a kártérítésig.",o:["Eltelik a megállapodott hozzávetőleges szállítási határidő","Felszólítás megfelelő póthatáridővel (általában 14 nap)","A póthatáridő szállítás nélkül lejár","Elállás és fedezeti vétel egy másik beszállítótól","A többletköltség követelése kártérítésként a beszállítótól"],e:"Szokásos határidős ügyletnél a jogkövetkezmények csak póthatáridős felszólítás után állnak be. Csak ennek lejárta után állhat el Loopy, és vásárolhat máshol; az árkülönbözetet (vétkesség esetén) kártérítésként követeli."}},{type:"match",level:1,de:{q:"Ordne jedes Beispiel der passenden Mangelart zu.",p:[["Glas ist bei der Lieferung zerbrochen","Offener Mangel"],["Elektronikfehler zeigt sich nach 3 Monaten","Versteckter Mangel"],["Verkäufer verschweigt bewusst einen Wasserschaden","Arglistig verschwiegener Mangel"],["Motor des Lieferwagens ist kaputt","Wesentlicher Mangel"],["Farbe weicht leicht von der Abbildung ab","Geringfügiger Mangel"]],e:"Nach der Erkennbarkeit unterscheidet man offen, versteckt und arglistig verschwiegen, nach der Bedeutung geringfügig und wesentlich. Die Einteilung entscheidet z. B. darüber, ob eine Vertragsauflösung möglich ist und wie lange die Frist läuft."},en:{q:"Match each example with the right type of defect.",p:[["Glass is broken on delivery","Obvious defect"],["Electronic fault appears after 3 months","Hidden defect"],["Seller deliberately conceals water damage","Fraudulently concealed defect"],["The delivery van's engine is broken","Material defect"],["Colour differs slightly from the picture","Minor defect"]],e:"By recognisability we distinguish obvious, hidden and fraudulently concealed defects; by significance minor and material ones. The classification decides, for example, whether the contract can be terminated and how long the period runs."},hu:{q:"Párosítsd a példákat a megfelelő hibafajtával.",p:[["Az üveg a kiszállításkor eltört","Nyílt hiba"],["Elektronikai hiba 3 hónap után jelentkezik","Rejtett hiba"],["Az eladó szándékosan elhallgat egy beázást","Csalárdul elhallgatott hiba"],["Tönkrement a kisteherautó motorja","Lényeges hiba"],["A szín kissé eltér a képtől","Csekély hiba"]],e:"Felismerhetőség szerint nyílt, rejtett és csalárdul elhallgatott hibát, jelentőség szerint csekély és lényeges hibát különböztetünk meg. A besorolás dönti el például, hogy felbontható-e a szerződés, és meddig tart a határidő."}},{type:"mc",level:3,correctIndex:1,de:{q:"Frau Wallner kauft am 1. März bei einem Elektrohändler eine neue Kaffeemaschine. Mitte September fällt die Heizung aus. Der Händler sagt: „Nach 6 Monaten müssen Sie beweisen, dass der Fehler schon beim Kauf da war.“ Stimmt das?",o:["Ja, nach 6 Monaten liegt die Beweislast immer bei der Käuferin","Nein, bei B2C gilt 12 Monate die Vermutung zu ihren Gunsten","Nein, denn der Händler muss während der ganzen 2 Jahre alles beweisen","Ja, und nach 6 Monaten ist die Gewährleistung ohnehin abgelaufen"],e:"Für Verbrauchergeschäfte gilt nach dem VGG eine Beweislastumkehr von 12 Monaten: Der Händler muss beweisen, dass die Maschine bei Übergabe in Ordnung war. Die 6 Monate gelten nur nach ABGB (z. B. zwischen Privaten); die Gewährleistungsfrist selbst beträgt 2 Jahre."},en:{q:"On 1 March Ms Wallner buys a new coffee machine from an electronics retailer. In mid-September the heating element fails. The retailer says: “After 6 months you have to prove the fault was there when you bought it.” Is that right?",o:["Yes, after 6 months the burden of proof is always on the buyer","No, in B2C the presumption runs for 12 months in her favour","No, because the retailer must prove everything for the full 2 years","Yes, and after 6 months the warranty has expired anyway"],e:"For consumer contracts the VGG provides a 12-month reversal of the burden of proof: the retailer must prove the machine was fine at handover. The 6 months only apply under the ABGB (e.g. between private persons); the warranty period itself is 2 years."},hu:{q:"Wallnerné március 1-jén új kávéfőzőt vásárol egy műszaki kereskedőnél. Szeptember közepén elromlik a fűtőegység. A kereskedő azt mondja: „6 hónap után Önnek kell bizonyítania, hogy a hiba már a vásárláskor megvolt.” Igaza van?",o:["Igen, 6 hónap után a bizonyítási teher mindig a vevőé","Nem, B2C-ben 12 hónapig a vevő javára szól a vélelem","Nem, mert a kereskedőnek a teljes 2 év alatt mindent bizonyítania kell","Igen, és 6 hónap után a szavatosság amúgy is lejárt"],e:"Fogyasztói ügyleteknél a VGG szerint 12 hónapos a megfordított bizonyítási teher: a kereskedőnek kell bizonyítania, hogy a gép átadáskor rendben volt. A 6 hónap csak az ABGB szerint érvényes (pl. magánszemélyek között); maga a szavatossági idő 2 év."}},{type:"mc",level:2,correctIndex:3,de:{q:"Loopy erhält von einem Lieferanten eine Rechnung über 2.400 €, auf der die UID-Nummer des Lieferanten fehlt. Was sollte sie tun?",o:["Die UID-Nummer selbst handschriftlich auf der Rechnung ergänzen","Nichts – die UID-Nummer ist nur ein freiwilliger Zusatz","Die Rechnung bezahlen und 20 % USt einfach nicht überweisen","Beim Lieferanten schriftlich eine neue Rechnung anfordern"],e:"Nur der Aussteller darf eine Rechnung korrigieren – also stellt der Lieferant eine neue Rechnung aus. Fehlt ein UStG-Bestandteil wie die UID-Nummer, bekommt Loopy keinen Vorsteuerabzug; eigenmächtige Ergänzungen oder Kürzungen sind unzulässig."},en:{q:"Loopy receives an invoice for €2,400 from a supplier on which the supplier's VAT ID number is missing. What should she do?",o:["Add the VAT ID number to the invoice herself by hand","Nothing – the VAT ID number is only an optional extra","Pay the invoice but simply not transfer the 20% VAT","Ask the supplier in writing for a new invoice"],e:"Only the issuer may correct an invoice – so the supplier issues a new one. If a required element under the VAT Act such as the VAT ID is missing, Loopy cannot deduct input VAT; making her own additions or deductions is not allowed."},hu:{q:"Loopy egy beszállítótól 2400 €-s számlát kap, amelyről hiányzik a beszállító közösségi adószáma. Mit tegyen?",o:["Írja rá ő maga kézzel a közösségi adószámot a számlára","Semmit – a közösségi adószám csak önkéntes kiegészítés","Fizesse ki a számlát, de a 20% áfát egyszerűen ne utalja át","Kérjen írásban új, javított számlát a beszállítótól"],e:"Számlát csak a kiállítója javíthat – a beszállító tehát új számlát állít ki. Ha hiányzik egy áfatörvényi kötelező elem, például a közösségi adószám, Loopy nem élhet előzetesadó-levonással; az önhatalmú kiegészítés vagy csökkentés nem megengedett."}},{type:"number",level:2,value:120,tol:.01,unit:{de:"€",en:"€",hu:"€"},de:{q:"Loopy hat 200 kg Kakaobohnen zu 6,50 €/kg bestellt. Der Lieferant gerät schuldhaft in Lieferverzug, auch die Nachfrist verstreicht. Loopy tritt zurück und kauft die Bohnen woanders zu 7,10 €/kg. Wie viel Schadenersatz kann sie verlangen?",e:"Ursprünglich: 200 · 6,50 = 1.300 €. Deckungskauf: 200 · 7,10 = 1.420 €. Schadenersatz = Differenz: 1.420 − 1.300 = 120 €. Voraussetzung ist ein Verschulden des Lieferanten."},en:{q:"Loopy ordered 200 kg of cocoa beans at €6.50/kg. The supplier is culpably late, and the grace period also passes. Loopy withdraws and buys the beans elsewhere at €7.10/kg. How much can she claim in damages?",e:"Originally: 200 · 6.50 = €1,300. Cover purchase: 200 · 7.10 = €1,420. Damages = difference: 1,420 − 1,300 = €120. This requires the supplier to be at fault."},hu:{q:"Loopy 200 kg kakaóbabot rendelt 6,50 €/kg áron. A beszállító vétkesen késedelembe esik, és a póthatáridő is eltelik. Loopy eláll, és máshol 7,10 €/kg áron veszi meg a babot. Mennyi kártérítést követelhet?",e:"Eredetileg: 200 · 6,50 = 1300 €. Fedezeti vétel: 200 · 7,10 = 1420 €. Kártérítés = különbözet: 1420 − 1300 = 120 €. Feltétele, hogy a beszállító vétkes legyen."}}]},i={"unzuverlaessige-kaeufer":[{type:"tf",level:1,correct:!0,de:{q:"Bei einem Geschäft zwischen Unternehmen (B2B) trägt der Käufer ab dem Annahmeverzug die Lager- und Erhaltungskosten sowie das Risiko für die Ware",e:"Richtig. Im B2B-Bereich gehen ab dem Annahmeverzug alle Kosten (Lager, Erhaltung) und das Risiko auf den Käufer über – er hat die vertragsgemäße Ware ja nicht angenommen."},en:{q:"In a business-to-business (B2B) sale, the buyer bears the storage and maintenance costs and the risk for the goods from the moment of default of acceptance",e:"True. In B2B, all costs (storage, maintenance) and the risk pass to the buyer once they are in default of acceptance – after all, they refused goods that matched the contract."},hu:{q:"Vállalkozások közötti (B2B) ügyletnél az átvételi késedelem kezdetétől a vevő viseli a tárolási és fenntartási költségeket, valamint az áruval kapcsolatos kockázatot",e:"Igaz. B2B-ügyletnél az átvételi késedelemtől kezdve minden költség (tárolás, fenntartás) és a kockázat is a vevőre száll át – hiszen ő nem vette át a szerződésszerű árut."}},{type:"tf",level:2,correct:!1,de:{q:"Verzugszinsen darf der Verkäufer erst ab dem Tag verrechnen, an dem er die erste Mahnung verschickt hat",e:"Falsch. Verzugszinsen können ab dem Tag der Fälligkeit verlangt werden – auch ohne Mahnung und ohne Verschulden des Käufers. Mahnen ist gesetzlich gar nicht vorgeschrieben."},en:{q:"The seller may only charge default interest from the day on which the first reminder was sent",e:"False. Default interest can be charged from the due date – even without a reminder and even if the buyer is not at fault. Sending reminders is not legally required at all."},hu:{q:"Késedelmi kamatot az eladó csak attól a naptól számíthat fel, amikor az első fizetési felszólítást elküldte",e:"Hamis. Késedelmi kamat már az esedékesség napjától követelhető – felszólítás nélkül és akkor is, ha a vevő nem hibás. Felszólítást küldeni a törvény nem is ír elő."}},{type:"tf",level:3,correct:!1,de:{q:"Nimmt eine Privatperson ein von einer anderen Privatperson gekauftes Fahrrad nicht an, darf die Verkäuferin es nach Androhung im Selbsthilfeverkauf versteigern lassen",e:"Falsch. Das ist ein C2C-Geschäft. Hier hat die Verkäuferin nur Hinterlegung bei Gericht und Rücktritt. Selbsthilfeverkauf und erweiterte Hinterlegung gibt es nur bei B2B."},en:{q:"If a private person does not accept a bike bought from another private person, the seller may have it auctioned in a self-help sale after giving notice",e:"False. This is a C2C sale. The seller only has deposit with the court and withdrawal. Self-help sale and extended deposit exist only in B2B."},hu:{q:"Ha egy magánszemély nem veszi át a másik magánszemélytől vásárolt kerékpárt, az eladó előzetes figyelmeztetés után önsegélyes eladással elárvereztetheti",e:"Hamis. Ez C2C-ügylet, ahol az eladónak csak a bírósági letétbe helyezés és az elállás áll rendelkezésére. Az önsegélyes eladás és a bővített letét csak B2B-ügyleteknél létezik."}},{type:"multi",level:1,correct:[0,1,2],de:{q:"Welche Aussagen zum Mahnplan treffen zu? Wähle alle richtigen aus.",o:["Die 1. Mahnung ist eine höfliche Zahlungserinnerung ohne Frist","In der 2. Mahnung wird eine Frist gesetzt und es werden Verzugszinsen und Mahnspesen angedroht","Die letzte Mahnung wird eingeschrieben verschickt","Der Mahnplan ist gesetzlich vorgeschrieben – ohne drei Mahnungen darf man nicht klagen","Ein Inkassobüro ist ein staatliches Gericht, das über die Forderung entscheidet"],e:"Mahnen ist keine gesetzliche Pflicht – man könnte sofort klagen; der Mahnplan ist nur Praxis. Ein Inkassobüro ist eine private Firma, die Schulden eintreibt, kein Gericht."},en:{q:"Which statements about the dunning plan are correct? Select all that apply.",o:["The 1st reminder is a polite payment reminder without a deadline","The 2nd reminder sets a deadline and announces default interest and reminder fees","The final reminder is sent by registered mail","The dunning plan is required by law – you may not sue without three reminders","A debt collection agency is a state court that decides on the claim"],e:"Sending reminders is not a legal duty – the seller could sue immediately; the dunning plan is just common practice. A debt collection agency is a private company that collects debts, not a court."},hu:{q:"Mely állítások igazak a felszólítási tervre? Jelöld meg az összes helyeset.",o:["Az 1. felszólítás udvarias fizetési emlékeztető, határidő nélkül","A 2. felszólítás határidőt szab, és késedelmi kamatot, valamint felszólítási költséget helyez kilátásba","Az utolsó felszólítást ajánlott levélben küldik","A felszólítási tervet törvény írja elő – három felszólítás nélkül nem lehet pert indítani","A követeléskezelő cég állami bíróság, amely dönt a követelésről"],e:"A felszólítás nem törvényi kötelezettség – az eladó azonnal perelhetne; a felszólítási terv csak bevett gyakorlat. A követeléskezelő (inkasszó) cég magáncég, amely behajtja a tartozást, nem bíróság."}},{type:"multi",level:2,correct:[0,1],de:{q:"Eine Konsumentin holt die bei Loopy bestellte, mangelfreie Geburtstagstorte am vereinbarten Tag nicht ab (B2C). Welche Rechte hat Loopy? Wähle alle zutreffenden aus.",o:["Die Ware bei Gericht hinterlegen und die Kundin zur Zahlung auffordern","Vom Vertrag zurücktreten, wenn die Kundin trotzdem nicht zahlt","Die Torte auf Kosten der Kundin in einem Lagerhaus einlagern (erweiterte Hinterlegung)","Die Torte nach Androhung versteigern lassen (Selbsthilfeverkauf)"],e:"Bei B2C (wie auch C2C) hat der Verkäufer nur Hinterlegung bei Gericht und Rücktritt. Erweiterte Hinterlegung und Selbsthilfeverkauf stehen nur im B2B-Bereich zur Verfügung."},en:{q:"A consumer does not collect the flawless birthday cake she ordered from Loopy on the agreed day (B2C). Which rights does Loopy have? Select all that apply.",o:["Deposit the goods with the court and ask the customer to pay","Withdraw from the contract if the customer still does not pay","Store the cake in a warehouse at the customer's expense (extended deposit)","Have the cake auctioned after giving notice (self-help sale)"],e:"In B2C (as in C2C) the seller only has deposit with the court and withdrawal. Extended deposit and self-help sale are only available in B2B."},hu:{q:"Egy fogyasztó a megbeszélt napon nem viszi el a Loopynál rendelt, hibátlan születésnapi tortát (B2C). Milyen jogai vannak Loopynak? Jelöld meg az összes helyeset.",o:["Bírósági letétbe helyezi az árut, és felszólítja a vevőt a fizetésre","Eláll a szerződéstől, ha a vevő ezután sem fizet","A vevő költségére raktárban helyezi el a tortát (bővített letét)","Előzetes figyelmeztetés után elárverezteti a tortát (önsegélyes eladás)"],e:"B2C (és C2C) ügyletnél az eladónak csak a bírósági letét és az elállás joga van. A bővített letét és az önsegélyes eladás csak B2B-ügyleteknél lehetséges."}},{type:"order",level:1,de:{q:"Bringe die Schritte eines typischen Mahnplans in die richtige Reihenfolge.",o:["Fälligkeit der Rechnung","1. Mahnung: Zahlungserinnerung","2. Mahnung mit Frist","Letzte Mahnung (eingeschrieben)","Rechtsanwalt oder Inkassobüro","Gerichtliches Mahnverfahren"],e:"Nach der Fälligkeit wird zuerst höflich erinnert, dann mit Frist gemahnt und zuletzt eingeschrieben. Erst danach werden Anwalt/Inkasso und schließlich das Gericht eingeschaltet."},en:{q:"Put the steps of a typical dunning plan in the correct order.",o:["Invoice falls due","1st reminder: payment reminder","2nd reminder with a deadline","Final reminder (registered mail)","Lawyer or debt collection agency","Court dunning procedure"],e:"After the due date, the seller first reminds politely, then sets a deadline, and finally sends a registered final reminder. Only then are a lawyer/collection agency and finally the court brought in."},hu:{q:"Állítsd helyes sorrendbe egy tipikus felszólítási terv lépéseit.",o:["A számla esedékessé válik","1. felszólítás: fizetési emlékeztető","2. felszólítás határidővel","Utolsó felszólítás (ajánlott levélben)","Ügyvéd vagy követeléskezelő cég","Bírósági fizetési meghagyásos eljárás"],e:"Az esedékesség után először udvariasan emlékeztetnek, majd határidővel felszólítanak, végül ajánlott levélben küldik az utolsó felszólítást. Csak ezután jön az ügyvéd/követeléskezelő, végül a bíróság."}},{type:"match",level:2,de:{q:"Ordne jeder Situation die passende gesetzliche Regel bzw. das passende Recht zu.",p:[["B2B: Rechnung wird zu spät bezahlt","Basiszinssatz + 9,2 % p. a."],["C2C oder B2C: Zahlung kommt zu spät","4 % p. a. Verzugszinsen"],["B2B: Kosten für das Mahnen","40 € Pauschale"],["B2B: Ware wird auf Kosten des Käufers im Lagerhaus eingelagert","Erweiterte Hinterlegung"],["B2B: Ware wird nach Androhung versteigert","Selbsthilfeverkauf"]],e:"UGB (B2B): Basiszinssatz + 9,2 % und 40 € Mahnpauschale; ABGB (B2C, C2C): 4 % p. a. Erweiterte Hinterlegung und Selbsthilfeverkauf sind Rechte bei Annahmeverzug, die nur im B2B-Bereich gelten."},en:{q:"Match each situation with the correct legal rule or right.",p:[["B2B: invoice is paid late","Base rate + 9.2% p.a."],["C2C or B2C: payment arrives late","4% p.a. default interest"],["B2B: costs of sending reminders","€40 flat fee"],["B2B: goods stored in a warehouse at the buyer's cost","Extended deposit"],["B2B: goods auctioned after notice","Self-help sale"]],e:"UGB (B2B): base rate + 9.2% and a €40 flat reminder fee; ABGB (B2C, C2C): 4% p.a. Extended deposit and self-help sale are rights in case of default of acceptance that only apply in B2B."},hu:{q:"Párosítsd az egyes helyzeteket a megfelelő törvényi szabállyal vagy joggal.",p:[["B2B: a számlát késve fizetik ki","Alapkamat + évi 9,2 %"],["C2C vagy B2C: késik a fizetés","Évi 4 % késedelmi kamat"],["B2B: a felszólítás költségei","40 € átalány"],["B2B: az árut a vevő költségére raktárba viszik","Bővített letét"],["B2B: az árut figyelmeztetés után elárverezik","Önsegélyes eladás"]],e:"UGB (B2B): alapkamat + 9,2 % és 40 € behajtási átalány; ABGB (B2C, C2C): évi 4 %. A bővített letét és az önsegélyes eladás az átvételi késedelem esetén csak B2B-ügyleteknél érvényes jogok."}},{type:"mc",level:2,correctIndex:1,de:{q:"Loopy liefert dem Hotel Seeblick pünktlich und mangelfrei 200 kg Fruchtgummi. Das Hotel verweigert die Annahme. Loopy will die Ware nicht selbst lagern, sondern bei einer Spedition einlagern – auf Kosten des Hotels. Welches Recht nutzt Loopy?",o:["Hinterlegung bei Gericht","Erweiterte Hinterlegung","Selbsthilfeverkauf","Rücktritt vom Vertrag"],e:"Einlagern bei einem Lagerhaus o. Ä. auf Kosten des Käufers ist die erweiterte Hinterlegung – möglich, weil es ein B2B-Geschäft ist. Bei der normalen Hinterlegung kommt die Ware zum Gericht, beim Selbsthilfeverkauf wird sie versteigert."},en:{q:"Loopy delivers 200 kg of fruit gums to Hotel Seeblick on time and free of defects. The hotel refuses to accept them. Loopy does not want to store the goods herself but at a freight company – at the hotel's expense. Which right is Loopy using?",o:["Deposit with the court","Extended deposit","Self-help sale","Withdrawal from the contract"],e:"Storing goods in a warehouse or similar at the buyer's expense is the extended deposit – possible because this is a B2B sale. With an ordinary deposit the goods go to the court; in a self-help sale they are auctioned."},hu:{q:"Loopy határidőre és hibátlanul leszállít 200 kg gumicukrot a Seeblick szállodának. A szálloda megtagadja az átvételt. Loopy nem maga akarja tárolni az árut, hanem egy szállítmányozónál – a szálloda költségére. Melyik jogával él Loopy?",o:["Bírósági letétbe helyezés","Bővített letét","Önsegélyes eladás","Elállás a szerződéstől"],e:"Az áru raktárban vagy hasonló helyen, a vevő költségére történő elhelyezése a bővített letét – ez azért lehetséges, mert B2B-ügyletről van szó. Sima letétnél az áru a bírósághoz kerül, önsegélyes eladásnál elárverezik."}},{type:"mc",level:3,correctIndex:0,de:{q:"Das Café Sonnenschein schuldet Loopy 3.200 €. Der bedingte Zahlungsbefehl wurde dem Café am 3. März zugestellt. Bis 15. April hat das Café weder bezahlt noch Einspruch erhoben. Wie ist die Lage?",o:["Der Zahlungsbefehl ist rechtskräftig, Loopy kann die Pfändung einleiten","Das Gericht setzt nun automatisch eine Verhandlung im Zivilprozess an","Das Café kann noch bis Ende April Einspruch gegen den Befehl erheben","Loopy muss jetzt zuerst noch eine letzte Mahnung eingeschrieben senden"],e:"Die Einspruchsfrist von 4 Wochen ist Ende März abgelaufen. Ohne Einspruch und Zahlung wird der Zahlungsbefehl rechtskräftig – bei weiterer Nichtzahlung folgt die Pfändung. Ein Zivilprozess gäbe es nur nach einem Einspruch."},en:{q:"Café Sonnenschein owes Loopy €3,200. The conditional payment order was served on the café on 3 March. By 15 April the café has neither paid nor objected. What is the situation?",o:["The payment order is final; Loopy can start garnishment","The court now automatically schedules a hearing in a civil trial","The café can still object to the order until the end of April","Loopy first has to send a final reminder by registered mail now"],e:"The 4-week objection period ended at the end of March. Without objection or payment, the payment order becomes final – if the café still does not pay, garnishment follows. A civil trial would only happen after an objection."},hu:{q:"A Sonnenschein kávézó 3 200 €-val tartozik Loopynak. A feltételes fizetési meghagyást március 3-án kézbesítették a kávézónak. Április 15-ig a kávézó sem nem fizetett, sem ellentmondást nem nyújtott be. Mi a helyzet?",o:["A fizetési meghagyás jogerős, Loopy kezdeményezheti a foglalást","A bíróság most automatikusan polgári peres tárgyalást tűz ki","A kávézó április végéig még ellentmondhat a meghagyásnak","Loopynak most előbb még egy utolsó, ajánlott felszólítást kell küldenie"],e:"A 4 hetes ellentmondási határidő március végén lejárt. Ellentmondás és fizetés nélkül a fizetési meghagyás jogerőre emelkedik – ha továbbra sincs fizetés, jöhet a foglalás. Polgári per csak ellentmondás után indulna."}},{type:"number",level:3,value:137.5,tol:.01,unit:{de:"€",en:"€",hu:"€"},de:{q:"Die Tischlerei Holzmann GmbH bezahlt eine Rechnung von Loopys Candy Store über 5.000 € um 60 Tage zu spät. Im Vertrag ist nichts geregelt. Der Basiszinssatz beträgt (angenommen) 2,5 %. Wie viel kann Loopy insgesamt an Verzugszinsen und Mahnspesen verlangen? (Zinsen = Kapital · Zinssatz · Tage / 36 000)",e:"B2B → UGB: 2,5 % + 9,2 % = 11,7 % p. a. Zinsen = 5.000 · 11,7 · 60 / 36 000 = 97,50 €. Dazu kommt die Mahnpauschale von 40 €: 97,50 + 40 = 137,50 €."},en:{q:"Holzmann GmbH, a joinery, pays an invoice from Loopy's Candy Store for €5,000 sixty days late. The contract says nothing about this. The base rate is (assumed) 2.5%. How much can Loopy claim in total for default interest and reminder fees? (Interest = capital · rate · days / 36,000)",e:"B2B → UGB: 2.5% + 9.2% = 11.7% p.a. Interest = 5,000 · 11.7 · 60 / 36,000 = €97.50. Add the €40 flat reminder fee: 97.50 + 40 = €137.50."},hu:{q:"A Holzmann GmbH asztalosüzem 60 nap késéssel fizeti ki Loopy édességboltjának 5 000 €-s számláját. A szerződés erről nem rendelkezik. Az alapkamat (feltételezve) 2,5 %. Összesen mennyi késedelmi kamatot és felszólítási költséget követelhet Loopy? (Kamat = tőke · kamatláb · napok / 36 000)",e:"B2B → UGB: 2,5 % + 9,2 % = évi 11,7 %. Kamat = 5 000 · 11,7 · 60 / 36 000 = 97,50 €. Ehhez jön a 40 €-s behajtási átalány: 97,50 + 40 = 137,50 €."}}],rechtsdurchsetzung:[{type:"tf",level:1,correct:!0,de:{q:"Wer einen Gerichtsprozess verliert, muss grundsätzlich alle Kosten tragen – auch die Anwaltskosten der Gegenseite",e:"Richtig. Der Verlierer zahlt ALLE Kosten, auch die des Gewinners. Genau das macht einen Rechtsstreit so teuer und riskant."},en:{q:"Whoever loses a court case generally has to pay all costs – including the other side's lawyer's fees",e:"True. The loser pays ALL costs, including those of the winner. That is exactly what makes a lawsuit so expensive and risky."},hu:{q:"Aki elveszít egy pert, főszabály szerint minden költséget visel – az ellenfél ügyvédi költségeit is",e:"Igaz. A vesztes fél fizeti az ÖSSZES költséget, a nyertesét is. Éppen ez teszi a pereskedést drágává és kockázatossá."}},{type:"tf",level:2,correct:!1,de:{q:"Ein Schiedsgericht ist ein staatliches Gericht, das automatisch für alle Streitigkeiten zwischen Unternehmen zuständig ist",e:"Falsch. Ein Schiedsgericht ist ein privates Gericht, das die Vertragspartner vorher vertraglich vereinbaren müssen. Sein Urteil ist dann aber rechtlich bindend."},en:{q:"An arbitral tribunal is a state court that is automatically responsible for all disputes between businesses",e:"False. An arbitral tribunal is a private court that the contracting parties must agree on in advance in their contract. Its decision is, however, legally binding."},hu:{q:"A választottbíróság állami bíróság, amely automatikusan illetékes a vállalkozások közötti összes vitában",e:"Hamis. A választottbíróság magánbíróság, amelyben a feleknek előre, szerződésben kell megállapodniuk. A döntése viszont jogilag kötelező."}},{type:"tf",level:3,correct:!0,de:{q:"Behauptet ein Käufer, mit dem Lieferanten sei ein Fixgeschäft vereinbart worden, muss er das beweisen – gelingt ihm das nicht, ist er im Streit im Nachteil",e:"Richtig. Wer etwas behauptet, trägt die Beweislast. Kann der Käufer den fixen Termin nicht beweisen (z. B. nur mündlich vereinbart), geht das zu seinen Lasten."},en:{q:"If a buyer claims that a fixed-date transaction was agreed with the supplier, he has to prove it – if he cannot, he is at a disadvantage in the dispute",e:"True. Whoever claims something bears the burden of proof. If the buyer cannot prove the fixed date (e.g. it was only agreed orally), this works against him."},hu:{q:"Ha a vevő azt állítja, hogy a szállítóval fix határidős ügyletet kötött, ezt neki kell bizonyítania – ha nem sikerül, hátrányba kerül a vitában",e:"Igaz. Aki valamit állít, azt terheli a bizonyítási teher. Ha a vevő nem tudja bizonyítani a fix határidőt (pl. csak szóban állapodtak meg), az az ő kárára megy."}},{type:"multi",level:1,correct:[0,1,2],de:{q:"Loopy fordert von einem Lieferanten den Austausch mangelhafter Ware. Was sollte das Schreiben an den Vertragspartner enthalten bzw. wie sollte es verschickt werden? Wähle alle passenden aus.",o:["Eine konkrete Forderung („Was will ich?“)","Eine genaue Frist („bis wann?“)","Versand am besten eingeschrieben","Bewusst keine Frist, um flexibel zu bleiben","Sofort die Klage beilegen, damit es ernst wirkt"],e:"Beim Benachrichtigen des Vertragspartners gehört dazu, was man will und bis wann – am besten eingeschrieben, damit man es beweisen kann. Ohne Frist ist die Forderung unverbindlich; geklagt wird erst nach Abwägen und Beratung."},en:{q:"Loopy demands that a supplier replace defective goods. What should the letter to the business partner contain, or how should it be sent? Select all that apply.",o:["A concrete demand (‘What do I want?’)","An exact deadline (‘by when?’)","Ideally sent by registered mail","Deliberately no deadline to stay flexible","Attach the lawsuit straight away so it looks serious"],e:"When notifying the business partner, state what you want and by when – ideally by registered mail so you can prove it. Without a deadline the demand is vague; going to court only comes after weighing up and getting advice."},hu:{q:"Loopy azt követeli egy szállítótól, hogy cserélje ki a hibás árut. Mit tartalmazzon a szerződő félnek írt levél, illetve hogyan küldje el? Jelöld meg az összes helyeset.",o:["Konkrét követelést („Mit akarok?”)","Pontos határidőt („Meddig?”)","Lehetőleg ajánlott levélben küldve","Szándékosan határidő nélkül, hogy rugalmas maradjon","Azonnal mellékelve a keresetet, hogy komolynak tűnjön"],e:"A szerződő fél értesítésekor meg kell adni, mit akarunk és meddig – lehetőleg ajánlott levélben, hogy bizonyítható legyen. Határidő nélkül a követelés nem elég határozott; perre csak mérlegelés és tanácsadás után kerül sor."}},{type:"multi",level:2,correct:[0,1],de:{q:"Bei welchen Wegen der Streitbeilegung entsteht KEINE rechtlich bindende Entscheidung durch einen Dritten? Wähle alle zutreffenden aus.",o:["Mediation","Schlichtungsstelle","Schiedsgericht","Urteil eines staatlichen Gerichts"],e:"Der Mediator vermittelt nur, die Schlichtungsstelle gibt nur Empfehlungen – beides ist nicht bindend. Das Schiedsgericht (privat, vertraglich vereinbart) und das staatliche Gericht entscheiden dagegen verbindlich."},en:{q:"Which ways of settling a dispute do NOT lead to a legally binding decision by a third party? Select all that apply.",o:["Mediation","Conciliation board","Arbitral tribunal","Judgment of a state court"],e:"The mediator only facilitates, and the conciliation board only makes recommendations – neither is binding. The arbitral tribunal (private, agreed by contract) and the state court, by contrast, make binding decisions."},hu:{q:"A vitarendezés mely módjainál NEM születik harmadik fél által hozott, jogilag kötelező döntés? Jelöld meg az összes helyeset.",o:["Mediáció","Békéltető testület","Választottbíróság","Állami bíróság ítélete"],e:"A mediátor csak közvetít, a békéltető testület csak ajánlást tesz – egyik sem kötelező. A választottbíróság (magánbíróság, szerződésben kikötve) és az állami bíróság ezzel szemben kötelező erejű döntést hoz."}},{type:"order",level:1,de:{q:"Bringe die Schritte, mit denen man seine Rechte durchsetzt, in die richtige Reihenfolge.",o:["Eigenes Interesse klären: Was will ich?","Vertragspartner benachrichtigen: Was will ich bis wann?","Abwägen: Lohnt sich ein Rechtsstreit?","Beratung: Was sagen Expert:innen?","Entscheidung: außergerichtliche Einigung oder Prozess"],e:"Zuerst klärt man, was man fordern kann, und teilt es dem Partner mit Frist mit. Erst dann wägt man ab, holt Rat ein (Anwalt, Beratungsstelle) und entscheidet über Einigung oder Gericht."},en:{q:"Put the steps for enforcing your rights in the correct order.",o:["Clarify your own interest: What do I want?","Notify the business partner: What do I want by when?","Weigh up: Is a lawsuit worth it?","Get advice: What do experts say?","Decide: out-of-court settlement or lawsuit"],e:"First you clarify what you can demand and tell the partner, with a deadline. Only then do you weigh things up, get advice (lawyer, advice centre) and decide between a settlement and court."},hu:{q:"Állítsd helyes sorrendbe a jogérvényesítés lépéseit.",o:["Saját érdek tisztázása: Mit akarok?","A szerződő fél értesítése: Mit akarok, és meddig?","Mérlegelés: Megéri-e a per?","Tanácsadás: Mit mondanak a szakértők?","Döntés: peren kívüli megegyezés vagy per"],e:"Először tisztázzuk, mit követelhetünk, és ezt határidővel közöljük a partnerrel. Csak ezután mérlegelünk, kérünk tanácsot (ügyvéd, tanácsadó szolgálat), és döntünk a megegyezésről vagy a perről."}},{type:"match",level:2,de:{q:"Ordne jedem Weg der Konfliktlösung das passende Merkmal zu.",p:[["Kulanzweg","Beide gehen freiwillig aufeinander zu"],["Mediation","Neutraler Vermittler hilft, selbst eine Lösung zu finden"],["Schlichtungsstelle","Gibt eine nicht bindende Empfehlung"],["Schiedsgericht","Privates Gericht mit bindendem Urteil"],["Staatliches Gericht","Klärt Rechtskonflikte; Verlierer zahlt alle Kosten"]],e:"Kulanz und Mediation setzen auf eine gemeinsame Lösung, die Schlichtungsstelle empfiehlt nur. Bindend entscheiden nur das vertraglich vereinbarte Schiedsgericht und das staatliche Gericht."},en:{q:"Match each way of resolving a conflict with its feature.",p:[["Goodwill approach","Both sides voluntarily meet each other halfway"],["Mediation","A neutral facilitator helps find their own solution"],["Conciliation board","Makes a non-binding recommendation"],["Arbitral tribunal","Private court with a binding decision"],["State court","Settles legal disputes; the loser pays all costs"]],e:"Goodwill and mediation aim for a joint solution; the conciliation board only recommends. Only the contractually agreed arbitral tribunal and the state court make binding decisions."},hu:{q:"Párosítsd a konfliktuskezelés egyes módjait a rájuk jellemző tulajdonsággal.",p:[["Méltányossági (kulancia) út","Mindkét fél önként enged a másiknak"],["Mediáció","Semleges közvetítő segít saját megoldást találni"],["Békéltető testület","Nem kötelező ajánlást ad"],["Választottbíróság","Magánbíróság kötelező döntéssel"],["Állami bíróság","Jogvitákat dönt el; a vesztes fizet mindent"]],e:"A méltányossági út és a mediáció közös megoldásra törekszik, a békéltető testület csak ajánlást tesz. Kötelező döntést csak a szerződésben kikötött választottbíróság és az állami bíróság hoz."}},{type:"mc",level:3,correctIndex:2,de:{q:"Die Fensterbau Gruber GmbH und eine Baufirma haben im Vertrag vereinbart, dass Streitigkeiten ein Schiedsgericht entscheidet. Das Schiedsgericht gibt Gruber recht. Die Baufirma will das Ergebnis ignorieren. Was gilt?",o:["Sie darf es ignorieren, weil nur staatliche Gerichte Urteile sprechen","Es ist nur eine Empfehlung, wie bei einer Schlichtungsstelle","Das Urteil ist bindend, die Baufirma muss sich daran halten","Sie kann eine Mediation verlangen, die das Urteil aufhebt"],e:"Ein vertraglich vereinbartes Schiedsgericht entscheidet rechtlich bindend – anders als die Schlichtungsstelle (nur Empfehlung) oder die Mediation (nur Vermittlung, keine Entscheidung)."},en:{q:"Fensterbau Gruber GmbH and a construction company agreed in their contract that disputes will be decided by an arbitral tribunal. The tribunal rules in Gruber's favour. The construction company wants to ignore the result. What applies?",o:["It may ignore it because only state courts can issue judgments","It is only a recommendation, as with a conciliation board","The decision is binding; the company has to comply with it","It can demand a mediation that overturns the decision"],e:"A contractually agreed arbitral tribunal makes legally binding decisions – unlike a conciliation board (only a recommendation) or mediation (only facilitation, no decision)."},hu:{q:"A Fensterbau Gruber GmbH és egy építőipari cég a szerződésükben kikötötték, hogy vitáikat választottbíróság dönti el. A választottbíróság Grubernek ad igazat. Az építőipari cég figyelmen kívül akarja hagyni az eredményt. Mi a helyzet?",o:["Figyelmen kívül hagyhatja, mert ítéletet csak állami bíróság hozhat","Ez csak ajánlás, mint a békéltető testületnél","A döntés kötelező, a cégnek be kell tartania","Mediációt kérhet, amely hatályon kívül helyezi a döntést"],e:"A szerződésben kikötött választottbíróság jogilag kötelező döntést hoz – ellentétben a békéltető testülettel (csak ajánlás) vagy a mediációval (csak közvetítés, nincs döntés)."}},{type:"mc",level:3,correctIndex:1,de:{q:"Loopy meint, ein Lieferant habe ihr mündlich 5 % Treuerabatt zugesagt – insgesamt 300 €. Schriftlich gibt es nichts, der Lieferant bestreitet es. Welche Überlegung spricht beim Abwägen am stärksten gegen eine Klage?",o:["Gerichte verhandeln Beträge unter 1.000 € grundsätzlich nicht","Sie trägt die Beweislast und riskiert, alle Kosten zu zahlen","Die Kosten trägt immer die beklagte Partei, egal wie es ausgeht","Eine Klage ist erst nach einer gescheiterten Mediation zulässig"],e:"Loopy behauptet die Zusage, also muss sie sie beweisen – ohne schriftliche Unterlagen ist das unsicher. Verliert sie, zahlt sie alle Kosten, die bei 300 € Streitwert schnell höher sein können als der Betrag selbst."},en:{q:"Loopy believes a supplier orally promised her a 5% loyalty discount – €300 in total. There is nothing in writing and the supplier denies it. Which consideration speaks most strongly against a lawsuit?",o:["Courts generally do not hear cases about amounts under €1,000","She bears the burden of proof and risks paying all the costs","The defendant always pays the costs, whatever the outcome","A lawsuit is only allowed after a failed mediation"],e:"Loopy claims the promise, so she has to prove it – without documents that is uncertain. If she loses, she pays all costs, which in a €300 dispute can easily exceed the amount itself."},hu:{q:"Loopy úgy véli, egy szállító szóban 5 % hűségkedvezményt ígért neki – összesen 300 €-t. Írásban semmi nincs, a szállító tagadja. Melyik szempont szól a mérlegelésnél a legerősebben a per ellen?",o:["A bíróságok 1 000 € alatti összegekkel főszabály szerint nem foglalkoznak","Őt terheli a bizonyítási teher, és kockáztatja, hogy minden költséget fizet","A költségeket mindig az alperes viseli, bármi is az eredmény","Pert csak sikertelen mediáció után lehet indítani"],e:"Loopy állítja az ígéretet, tehát neki kell bizonyítania – írásos dokumentum nélkül ez bizonytalan. Ha veszít, minden költséget ő fizet, ami 300 €-s pertárgyértéknél könnyen meghaladhatja magát az összeget."}},{type:"text",level:1,de:{q:"Wie nennt man die neutrale Person, die bei einer Mediation zwischen den Streitparteien vermittelt?",a:["Mediator","Mediatorin","Mediator:in","Mediatorinnen","Mediatoren"],e:"Der Mediator bzw. die Mediatorin entscheidet nicht, sondern hilft den Parteien, selbst eine Lösung zu finden."},en:{q:"What do you call the neutral person who facilitates between the parties in a mediation?",a:["mediator","a mediator","the mediator"],e:"The mediator does not decide but helps the parties find a solution themselves."},hu:{q:"Hogyan nevezzük azt a semleges személyt, aki a mediáció során közvetít a vitázó felek között?",a:["mediátor","a mediátor","közvetítő"],e:"A mediátor nem dönt, hanem segít a feleknek, hogy maguk találjanak megoldást."}}],"unternehmensgruendung-schritte":[{type:"tf",level:1,correct:!1,de:{q:"Eine Ärztin, die eine eigene Praxis eröffnet, braucht dafür eine Gewerbeberechtigung",e:"Falsch. Ärzt:innen üben einen freien Beruf aus. Freie Berufe und Neue Selbstständige brauchen keine Gewerbeberechtigung – sie sind trotzdem selbstständig erwerbstätig."},en:{q:"A doctor who opens her own practice needs a trade licence for it",e:"False. Doctors practise a liberal profession. Liberal professions and the ‘new self-employed’ do not need a trade licence – they are nevertheless self-employed."},hu:{q:"Egy orvosnőnek, aki saját rendelőt nyit, ehhez iparengedélyre van szüksége",e:"Hamis. Az orvosok szabadfoglalkozást űznek. A szabadfoglalkozásúaknak és az „új önállóknak” nincs szükségük iparengedélyre – ettől még önálló vállalkozóként dolgoznak."}},{type:"tf",level:2,correct:!0,de:{q:"Auch eine dauerhafte Organisation, die nicht auf Gewinn ausgerichtet ist, kann nach dem UGB ein Unternehmen sein",e:"Richtig. Laut UGB ist ein Unternehmen jede auf Dauer angelegte Organisation selbstständiger wirtschaftlicher Tätigkeit – auch wenn sie nicht auf Gewinn aus ist."},en:{q:"Under the UGB, even a permanent organisation that is not aimed at making a profit can be an enterprise",e:"True. According to the UGB, an enterprise is any organisation of independent economic activity set up for the long term – even if it does not aim to make a profit."},hu:{q:"Az UGB szerint egy tartós szervezet akkor is lehet vállalkozás, ha nem nyereségszerzésre irányul",e:"Igaz. Az UGB szerint vállalkozás minden tartósan működő, önálló gazdasági tevékenységet folytató szervezet – akkor is, ha nem nyereségre törekszik."}},{type:"tf",level:3,correct:!1,de:{q:"Ein Einzelunternehmer, der nicht im Firmenbuch eingetragen ist, führt eine Firma aus Firmenkern und dem Zusatz „e. U.“",e:"Falsch. Ohne Eintragung ins Firmenbuch gibt es keine Firma, sondern nur eine Unternehmensbezeichnung (Vor- und Nachname). Den Zusatz „e. U.“ darf nur ein eingetragener Unternehmer führen."},en:{q:"A sole trader who is not entered in the commercial register uses a company name consisting of a core name and the suffix ‘e. U.’",e:"False. Without an entry in the commercial register there is no company name (Firma), only a business designation (first and last name). Only a registered trader may use the suffix ‘e. U.’."},hu:{q:"A cégjegyzékbe be nem jegyzett egyéni vállalkozó vezérszóból és „e. U.” toldatból álló cégnevet visel",e:"Hamis. Cégjegyzékbe való bejegyzés nélkül nincs cégnév, csak vállalkozásmegjelölés (vezeték- és utónév). Az „e. U.” toldatot csak bejegyzett vállalkozó használhatja."}},{type:"multi",level:2,correct:[0,1,2,3],de:{q:"Welche Merkmale muss eine Tätigkeit erfüllen, damit sie als gewerbliche Tätigkeit gilt? Wähle alle zutreffenden aus.",o:["Erlaubt","Selbstständig","Regelmäßig","Entgeltlich (mit Ertragsabsicht)","Weisungsgebunden in einem Dienstverhältnis","Einmalig und unentgeltlich"],e:"Gewerblich = erlaubt + selbstständig + regelmäßig + entgeltlich. Wer weisungsgebunden in einem Dienstverhältnis arbeitet, ist unselbstständig; eine einmalige, unentgeltliche Tätigkeit ist kein Gewerbe."},en:{q:"Which features must an activity have to count as a trade activity? Select all that apply.",o:["Lawful","Independent (self-employed)","Regular","For payment (intending to earn income)","Bound by instructions in an employment relationship","One-off and unpaid"],e:"Trade activity = lawful + independent + regular + for payment. Someone bound by instructions in an employment relationship is an employee; a one-off, unpaid activity is not a trade."},hu:{q:"Milyen ismérveknek kell megfelelnie egy tevékenységnek ahhoz, hogy iparszerű tevékenységnek minősüljön? Jelöld meg az összes helyeset.",o:["Megengedett","Önálló","Rendszeres","Ellenérték fejében végzett (jövedelemszerzési szándékkal)","Munkaviszonyban, utasításhoz kötve végzett","Egyszeri és ingyenes"],e:"Iparszerű = megengedett + önálló + rendszeres + ellenérték fejében végzett. Aki munkaviszonyban, utasításhoz kötve dolgozik, az nem önálló; egy egyszeri, ingyenes tevékenység pedig nem iparűzés."}},{type:"multi",level:1,correct:[0,1,3],de:{q:"Welche Aussagen beschreiben eine gute Geschäftsidee? Wähle alle zutreffenden aus.",o:["Sie bringt den Kund:innen einen Vorteil (z. B. schneller, einfacher)","Sie ist finanzierbar und gewinnbringend","Sie muss völlig neu sein – verbesserte bestehende Ideen zählen nicht","Sie hebt sich durch einen USP von der Konkurrenz ab","Sie braucht keine Marktchance, solange sie kreativ ist"],e:"Eine gute Idee überzeugt Kund:innen, ist besser als die Konkurrenz (USP), hat eine Marktchance, ist finanzierbar und gewinnbringend. Auch bewährte Ideen weiterzuentwickeln ist ein legitimer Weg zur Neugründung."},en:{q:"Which statements describe a good business idea? Select all that apply.",o:["It gives customers an advantage (e.g. faster, easier)","It can be financed and makes a profit","It must be completely new – improved existing ideas do not count","It stands out from the competition through a USP","It does not need a market opportunity as long as it is creative"],e:"A good idea convinces customers, is better than the competition (USP), has a chance on the market, can be financed and is profitable. Developing proven ideas further is also a legitimate way to start a new business."},hu:{q:"Mely állítások jellemzik a jó üzleti ötletet? Jelöld meg az összes helyeset.",o:["Előnyt nyújt a vevőknek (pl. gyorsabb, egyszerűbb)","Finanszírozható és nyereséges","Teljesen újnak kell lennie – a továbbfejlesztett meglévő ötletek nem számítanak","Egyedi értékajánlattal (USP) kiemelkedik a versenytársak közül","Nem kell piaci esély, ha elég kreatív"],e:"A jó ötlet meggyőzi a vevőket, jobb a konkurenciánál (USP), van piaci esélye, finanszírozható és nyereséges. A bevált ötletek továbbfejlesztése is teljesen elfogadott út az új vállalkozás alapításához."}},{type:"order",level:1,de:{q:"Bringe die Schritte der Unternehmensgründung in die richtige Reihenfolge.",o:["Gründungswille und Geschäftsidee","Unternehmensgründer:in prüfen (persönliche und gewerberechtliche Voraussetzungen)","Rechtsform festlegen","Businessplan erstellen"],e:"Am Anfang stehen der Wunsch und die Idee. Dann prüft man, ob man selbst die Voraussetzungen erfüllt, wählt die Rechtsform und hält schließlich alles im Businessplan fest."},en:{q:"Put the steps of starting a business in the correct order.",o:["Desire to start a business and business idea","Check the founder (personal and trade-law requirements)","Choose the legal form","Write the business plan"],e:"It starts with the wish and the idea. Then you check whether you meet the requirements, choose the legal form and finally put everything down in the business plan."},hu:{q:"Állítsd helyes sorrendbe a vállalkozásalapítás lépéseit.",o:["Alapítási szándék és üzleti ötlet","Az alapító ellenőrzése (személyes és iparjogi feltételek)","A jogi forma kiválasztása","Az üzleti terv elkészítése"],e:"Az elején a szándék és az ötlet áll. Ezután megvizsgáljuk, teljesítjük-e a feltételeket, kiválasztjuk a jogi formát, végül mindent rögzítünk az üzleti tervben."}},{type:"match",level:3,de:{q:"Ordne jeder Tätigkeit die richtige Einordnung zu.",p:[["Werbeagentur","Freies Gewerbe"],["Friseursalon","Reglementiertes Gewerbe"],["Baumeister","Reglementiert mit Zuverlässigkeitsprüfung"],["Rechtsanwaltskanzlei","Freier Beruf – keine Gewerbeberechtigung"],["Freischaffende Künstlerin","Neue Selbstständige – keine Gewerbeberechtigung"]],e:"Freie Gewerbe brauchen nur die allgemeinen Voraussetzungen, reglementierte zusätzlich einen Befähigungsnachweis, manche (Baumeister, Reisebüro) auch eine Zuverlässigkeitsprüfung. Freie Berufe und Neue Selbstständige brauchen gar keine Gewerbeberechtigung."},en:{q:"Match each activity with the correct category.",p:[["Advertising agency","Free trade"],["Hair salon","Regulated trade"],["Master builder","Regulated with reliability check"],["Law firm","Liberal profession – no trade licence"],["Freelance artist","New self-employed – no trade licence"]],e:"Free trades only need the general requirements; regulated trades also need proof of qualification, and some (master builder, travel agency) a reliability check as well. Liberal professions and the new self-employed need no trade licence at all."},hu:{q:"Párosítsd az egyes tevékenységeket a helyes besorolással.",p:[["Reklámügynökség","Szabad ipar"],["Fodrászszalon","Szabályozott ipar"],["Építőmester","Szabályozott, megbízhatósági vizsgálattal"],["Ügyvédi iroda","Szabadfoglalkozás – nem kell iparengedély"],["Szabadúszó művész","Új önálló – nem kell iparengedély"]],e:"A szabad iparhoz csak az általános feltételek kellenek, a szabályozott iparhoz képesítési igazolás is, egyesekhez (építőmester, utazási iroda) megbízhatósági vizsgálat is. A szabadfoglalkozásúaknak és az új önállóknak egyáltalán nem kell iparengedély."}},{type:"mc",level:2,correctIndex:3,de:{q:"Lena hat die Meisterprüfung als Friseurin und will in Graz einen eigenen Salon eröffnen. Wo erhält sie die Gewerbeberechtigung?",o:["Bei der Wirtschaftskammer Steiermark","Beim Landesgericht Graz (Firmenbuch)","Beim Finanzamt Österreich in Graz","Beim Magistrat Graz (Gewerbebehörde)"],e:"Die Gewerbeberechtigung stellt die Gewerbebehörde aus – die Bezirkshauptmannschaft oder in Statutarstädten wie Graz der Magistrat. Die WKO ist die Interessenvertretung, das Firmenbuch verzeichnet Firmen."},en:{q:"Lena has passed her master hairdresser exam and wants to open her own salon in Graz. Where does she obtain the trade licence?",o:["At the Styrian Economic Chamber (WKO)","At the Graz regional court (commercial register)","At the tax office in Graz","At the Graz Magistrat (trade authority)"],e:"The trade licence is issued by the trade authority – the district authority or, in statutory cities like Graz, the municipal authority (Magistrat). The WKO represents businesses' interests; the commercial register lists companies."},hu:{q:"Lena fodrászmestervizsgát tett, és saját szalont szeretne nyitni Grazban. Hol kapja meg az iparengedélyt?",o:["A stájer gazdasági kamaránál (WKO)","A grazi tartományi bíróságon (cégjegyzék)","A grazi adóhivatalnál","A grazi Magistratnál (iparhatóság)"],e:"Az iparengedélyt az iparhatóság adja ki – a járási hivatal (Bezirkshauptmannschaft), illetve a törvényhatósági jogú városokban, mint Graz, a városi hivatal (Magistrat). A WKO érdekképviselet, a cégjegyzék pedig a cégeket tartja nyilván."}},{type:"mc",level:3,correctIndex:0,de:{q:"Max (24) möchte eine eigene Pizzeria. Er überlegt, eine bestehende Pizzeria samt Personal und Stammkundschaft zu kaufen. Welcher Nachteil ist für diesen Weg typisch?",o:["Mängel und eingefahrene Strukturen werden mit übernommen","Er muss laufende Franchisegebühren an die Zentrale zahlen","Er hat anfangs weder Kund:innen noch Lieferanten","Er darf das Konzept nicht an eigene Ideen anpassen"],e:"Bei einer Unternehmensübernahme übernimmt man auch Mängel, und Strukturen sind schwer zu ändern. Gebühren und wenig Spielraum sind Nachteile des Franchisings; fehlende Kund:innen wären typisch für eine Neugründung."},en:{q:"Max (24) wants his own pizzeria. He is thinking about buying an existing pizzeria with its staff and regular customers. Which disadvantage is typical of this route?",o:["Defects and entrenched structures are taken over as well","He has to pay ongoing franchise fees to head office","At first he has neither customers nor suppliers","He may not adapt the concept to his own ideas"],e:"When taking over a business, you also take over its defects, and structures are hard to change. Fees and little room for your own ideas are disadvantages of franchising; having no customers would be typical of a brand-new start-up."},hu:{q:"Max (24) saját pizzériát szeretne. Azon gondolkodik, hogy megvesz egy meglévő pizzériát a személyzettel és a törzsvendégekkel együtt. Melyik hátrány jellemző erre az útra?",o:["A hiányosságokat és a megszokott struktúrákat is átveszi","Folyamatos franchise-díjat kell fizetnie a központnak","Kezdetben nincsenek sem vevői, sem szállítói","Nem igazíthatja a koncepciót saját ötleteihez"],e:"Vállalkozás átvételekor a hiányosságokat is átvesszük, és a struktúrákat nehéz megváltoztatni. A díjak és a kevés mozgástér a franchise hátrányai; a vevők hiánya az új alapításra lenne jellemző."}},{type:"text",level:2,de:{q:"Eine Firma besteht aus zwei Teilen. Wie heißt der frei wählbare Teil (z. B. „Lisa Berger“ in „Lisa Berger e. U.“)?",a:["Firmenkern","der Firmenkern"],e:"Firma = Firmenkern (frei wählbar) + Firmenzusatz (zeigt die Rechtsform, z. B. e. U., GmbH)."},en:{q:"A company name (Firma) consists of two parts. What is the freely chosen part called (e.g. ‘Lisa Berger’ in ‘Lisa Berger e. U.’)?",a:["core name","firm core","company core","core of the company name","core"],e:"Company name = core name (freely chosen) + legal form suffix (shows the legal form, e.g. e. U., GmbH)."},hu:{q:"A cégnév két részből áll. Hogyan nevezzük a szabadon választható részt (pl. „Lisa Berger” a „Lisa Berger e. U.” cégnévben)?",a:["vezérszó","a vezérszó","cégnév vezérszava","cégmag"],e:"Cégnév = vezérszó (szabadon választható) + cégforma-toldat (a jogi formát mutatja, pl. e. U., GmbH)."}}],"wahl-der-rechtsform-1jg":[{type:"tf",level:1,correct:!1,de:{q:"Für die Gründung eines Einzelunternehmens ist ein gesetzliches Mindestkapital vorgeschrieben",e:"Falsch. Beim Einzelunternehmen gibt es KEIN Mindestkapital – das ist einer seiner Vorteile. Der Unternehmer bringt das Kapital (Eigen- und Fremdkapital) selbst auf."},en:{q:"A statutory minimum capital is required to set up a sole proprietorship",e:"False. A sole proprietorship has NO minimum capital – that is one of its advantages. The owner raises the capital (equity and borrowed funds) himself."},hu:{q:"Egyéni vállalkozás alapításához törvényben előírt minimális tőke szükséges",e:"Hamis. Az egyéni vállalkozásnál NINCS minimális tőke – ez az egyik előnye. A vállalkozó maga teremti elő a tőkét (saját és idegen tőkét)."}},{type:"tf",level:2,correct:!0,de:{q:"Ein Einzelunternehmer kann sich auch freiwillig ins Firmenbuch eintragen lassen und als e. U. auftreten, bevor er die Umsatzgrenzen erreicht",e:"Richtig. Ab den Umsatzgrenzen ist die Eintragung Pflicht, freiwillig ist sie aber schon früher möglich. Dann führt er eine Firma mit dem Zusatz „eingetragener Unternehmer (e. U.)“."},en:{q:"A sole trader may also voluntarily register in the commercial register and trade as an e. U. before reaching the turnover thresholds",e:"True. Registration becomes mandatory once the turnover thresholds are reached, but it is possible voluntarily earlier. The trader then uses a company name with the suffix ‘registered trader (e. U.)’."},hu:{q:"Az egyéni vállalkozó önként is bejegyeztetheti magát a cégjegyzékbe, és e. U.-ként léphet fel, mielőtt elérné a forgalmi értékhatárokat",e:"Igaz. Az értékhatárok elérésétől a bejegyzés kötelező, de önként már korábban is lehetséges. Ekkor „bejegyzett vállalkozó (e. U.)” toldatú cégnevet használ."}},{type:"tf",level:3,correct:!1,de:{q:"Ein Einzelunternehmer, der in einem einzigen Jahr 800.000 € Umsatz erzielt, muss deshalb bereits doppelte Buchhaltung führen",e:"Falsch. Doppelte Buchhaltung ist nötig ab 1 Mio. € Umsatz in einem Jahr oder wenn zwei Jahre hintereinander je 700.000 € überschritten werden. Ein einzelnes Jahr mit 800.000 € reicht noch nicht."},en:{q:"A sole trader who achieves €800,000 in turnover in a single year therefore already has to keep double-entry books",e:"False. Double-entry bookkeeping is required from €1 million turnover in one year, or if €700,000 is exceeded in two consecutive years. A single year with €800,000 is not yet enough."},hu:{q:"Az az egyéni vállalkozó, aki egyetlen évben 800 000 € árbevételt ér el, emiatt már kettős könyvvitelt köteles vezetni",e:"Hamis. Kettős könyvvitel egy évben 1 millió € árbevétel felett kell, vagy ha két egymást követő évben is meghaladja a 700 000 €-t. Egyetlen 800 000 €-s év ehhez még nem elég."}},{type:"multi",level:1,correct:[0,1,2],de:{q:"Welche Aussagen zum Einzelunternehmen treffen zu? Wähle alle richtigen aus.",o:["Es entsteht mit der Gewerbeanmeldung","Es ist die häufigste Rechtsform in Österreich","Der Gewinn muss nicht geteilt werden","Die Haftung ist auf das Geschäftsvermögen beschränkt","Für die Gründung braucht man mindestens zwei Personen"],e:"Das Einzelunternehmen entsteht einfach mit der Gewerbeanmeldung, ist die häufigste Rechtsform und der Gewinn gehört dem Inhaber allein. Er haftet aber unbeschränkt – auch privat – und gründet allein."},en:{q:"Which statements about the sole proprietorship are correct? Select all that apply.",o:["It comes into existence when the trade is registered","It is the most common legal form in Austria","The profit does not have to be shared","Liability is limited to the business assets","At least two people are needed to set it up"],e:"A sole proprietorship comes into existence simply by registering the trade, is the most common legal form, and the profit belongs to the owner alone. However, the owner has unlimited liability – including private assets – and founds it alone."},hu:{q:"Mely állítások igazak az egyéni vállalkozásra? Jelöld meg az összes helyeset.",o:["Az iparbejelentéssel jön létre","Ez a leggyakoribb jogi forma Ausztriában","A nyereséget nem kell megosztani","A felelősség az üzleti vagyonra korlátozódik","Az alapításhoz legalább két személy kell"],e:"Az egyéni vállalkozás egyszerűen az iparbejelentéssel jön létre, ez a leggyakoribb jogi forma, és a nyereség egyedül a tulajdonosé. Ő viszont korlátlanul felel – magánvagyonával is –, és egyedül alapít."}},{type:"multi",level:3,correct:[0,1,2],de:{q:"Die Einzelunternehmerin Sophie (Blumenhandel) schuldet einem Lieferanten 30.000 €, das Geschäftskonto ist leer. Worauf kann der Gläubiger grundsätzlich zugreifen? Wähle alle zutreffenden aus.",o:["Auf Sophies privates Sparbuch","Auf Sophies Eigentumswohnung","Auf die Ladeneinrichtung des Blumengeschäfts","Auf das Vermögen von Sophies Ehemann","Auf die Wohnung von Sophies Eltern"],e:"Als Vollhafterin haftet Sophie persönlich und unbeschränkt – mit Geschäfts- UND Privatvermögen. Das Vermögen anderer Personen (Ehemann, Eltern) haftet aber nicht, solange diese nicht selbst z. B. als Bürgen unterschrieben haben."},en:{q:"Sophie, a sole trader (flower shop), owes a supplier €30,000 and the business account is empty. What can the creditor in principle claim against? Select all that apply.",o:["Sophie's private savings account","Sophie's owner-occupied flat","The shop fittings of the flower shop","The assets of Sophie's husband","The flat of Sophie's parents"],e:"As a fully liable owner, Sophie is personally and unlimitedly liable – with business AND private assets. Other people's assets (husband, parents) are not liable unless they themselves signed, e.g. as guarantors."},hu:{q:"Sophie egyéni vállalkozó (virágbolt) 30 000 €-val tartozik egy szállítónak, az üzleti számla üres. Mire vezethet a hitelező főszabály szerint végrehajtást? Jelöld meg az összes helyeset.",o:["Sophie magán-takarékbetétjére","Sophie saját tulajdonú lakására","A virágbolt berendezésére","Sophie férjének vagyonára","Sophie szüleinek lakására"],e:"Korlátlanul felelős tulajdonosként Sophie személyesen és korlátlanul felel – üzleti ÉS magánvagyonával is. Más személyek (férj, szülők) vagyona viszont nem felel, hacsak ők maguk nem írtak alá pl. kezesként."}},{type:"match",level:1,de:{q:"Ordne jede Rechtsform der richtigen Gruppe zu.",p:[["Einzelunternehmen","1 Person ist Alleineigentümer"],["OG","Personengesellschaft"],["GmbH","Kapitalgesellschaft"],["Genossenschaft","Sonderform"]],e:"Einzelunternehmen: eine Person. Personengesellschaften: OG, KG. Kapitalgesellschaften: GmbH, AG. Sonderform: Genossenschaft."},en:{q:"Match each legal form with the correct group.",p:[["Sole proprietorship","1 person is the sole owner"],["OG (general partnership)","Partnership"],["GmbH (limited company)","Corporation"],["Cooperative","Special form"]],e:"Sole proprietorship: one person. Partnerships: OG, KG. Corporations: GmbH, AG. Special form: cooperative."},hu:{q:"Párosítsd az egyes jogi formákat a megfelelő csoporttal.",p:[["Egyéni vállalkozás","1 személy az egyedüli tulajdonos"],["OG (közkereseti társaság)","Személyegyesítő társaság"],["GmbH (korlátolt felelősségű társaság)","Tőkeegyesítő társaság"],["Szövetkezet","Különleges forma"]],e:"Egyéni vállalkozás: egy személy. Személyegyesítő társaságok: OG, KG. Tőkeegyesítő társaságok: GmbH, AG. Különleges forma: szövetkezet."}},{type:"match",level:2,de:{q:"Ordne jedem Kriterium der Rechtsformwahl die passende Frage zu.",p:[["Anzahl der Eigentümer","Allein oder mit Partnern gründen?"],["Kapitalaufbringung","Muss ein Mindestkapital vorhanden sein?"],["Haftung","Wer haftet wie stark für Schulden?"],["Erfolgsverteilung","Wer bekommt Gewinn, wer trägt Verlust?"],["Art der Buchführung","E/A-Rechnung oder doppelte Buchhaltung?"]],e:"Diese Kriterien (dazu Leitungsbefugnis/Kontrolle) entscheiden, welche Rechtsform passt – z. B. ob man ein Mindestkapital braucht oder privat haftet."},en:{q:"Match each criterion for choosing a legal form with the right question.",p:[["Number of owners","Found alone or with partners?"],["Raising capital","Is a minimum capital required?"],["Liability","Who is liable for debts, and how far?"],["Profit distribution","Who gets the profit, who bears the loss?"],["Type of bookkeeping","Cash-basis accounts or double-entry?"]],e:"These criteria (plus management authority/control) decide which legal form fits – e.g. whether minimum capital is needed or whether you are liable with private assets."},hu:{q:"Párosítsd a jogi forma választásának egyes szempontjait a hozzájuk illő kérdéssel.",p:[["Tulajdonosok száma","Egyedül vagy partnerekkel alapítunk?"],["Tőke előteremtése","Kell-e minimális tőke?"],["Felelősség","Ki és milyen mértékben felel a tartozásokért?"],["Eredmény felosztása","Ki kapja a nyereséget, ki viseli a veszteséget?"],["Könyvvezetés módja","Bevétel-kiadás nyilvántartás vagy kettős könyvvitel?"]],e:"Ezek a szempontok (és a vezetési jogkör/ellenőrzés) döntik el, melyik jogi forma a megfelelő – pl. kell-e minimális tőke, vagy felel-e valaki a magánvagyonával."}},{type:"mc",level:2,correctIndex:2,de:{q:"Anna führt ihren Blumenladen als Einzelunternehmen ohne Mitarbeiter:innen. Sie muss sechs Wochen ins Krankenhaus. Welcher typische Nachteil des Einzelunternehmens zeigt sich hier?",o:["Sie muss ihren Gewinn mit Partner:innen teilen","Sie haftet dann nur mit ihrem Geschäftsvermögen","Es gibt keine Vertretung, der Betrieb steht still","Sie muss sich sofort ins Firmenbuch eintragen lassen"],e:"Beim Einzelunternehmen liegt alles beim Inhaber – fällt er aus, gibt es keine Vertretung. Den Gewinn muss Anna gerade nicht teilen, und sie haftet sogar unbeschränkt, auch privat."},en:{q:"Anna runs her flower shop as a sole proprietorship without employees. She has to go to hospital for six weeks. Which typical disadvantage of the sole proprietorship shows here?",o:["She has to share her profit with partners","She is only liable with her business assets","There is no one to stand in; the business stops","She must register in the commercial register at once"],e:"In a sole proprietorship everything depends on the owner – if she is absent, there is no one to stand in. Anna does not have to share the profit, and her liability is in fact unlimited, including private assets."},hu:{q:"Anna egyéni vállalkozásként, alkalmazottak nélkül vezeti virágboltját. Hat hétre kórházba kell mennie. Az egyéni vállalkozás melyik tipikus hátránya mutatkozik meg itt?",o:["Meg kell osztania a nyereségét a partnereivel","Csak az üzleti vagyonával felel","Nincs, aki helyettesítse, az üzlet leáll","Azonnal be kell jegyeztetnie magát a cégjegyzékbe"],e:"Az egyéni vállalkozásban minden a tulajdonoson múlik – ha kiesik, nincs helyettesítés. A nyereséget Annának éppen nem kell megosztania, és ráadásul korlátlanul, magánvagyonával is felel."}},{type:"mc",level:3,correctIndex:0,de:{q:"Die Einzelunternehmerin Mira (Online-Shop für Schmuck) hat zwei Jahre hintereinander je 750.000 € Umsatz. Was folgt daraus?",o:["Doppelte Buchhaltung und Eintragung als e. U. werden Pflicht","Sie muss das Unternehmen in eine GmbH umwandeln","Nichts – E/A-Rechnung bleibt, 1 Mio. € wurde nie erreicht","Sie muss nachträglich ein Mindestkapital von 10.000 € einzahlen"],e:"Werden zwei Jahre hintereinander je 700.000 € überschritten, muss sie doppelt buchen und sich ins Firmenbuch eintragen (e. U.). Die 1-Mio.-Grenze gilt für ein einzelnes Jahr; eine Umwandlung oder ein Mindestkapital verlangt das Gesetz nicht."},en:{q:"Mira, a sole trader (online jewellery shop), has €750,000 turnover in each of two consecutive years. What follows from this?",o:["Double-entry books and registration as e. U. become mandatory","She has to convert the business into a GmbH","Nothing – cash-basis accounts stay, €1m was never reached","She has to pay in a minimum capital of €10,000 retroactively"],e:"If €700,000 is exceeded in two consecutive years, she must keep double-entry books and register in the commercial register (e. U.). The €1m threshold applies to a single year; the law requires neither conversion nor minimum capital."},hu:{q:"Mira egyéni vállalkozó (online ékszerbolt) két egymást követő évben is 750 000 € árbevételt ér el. Mi következik ebből?",o:["Kettős könyvvitel és e. U.-bejegyzés kötelező","Át kell alakítania a vállalkozást GmbH-vá","Semmi – marad a bevétel-kiadás nyilvántartás, 1 millió € nem volt","Utólag minimális tőkét kell befizetnie"],e:"Ha két egymást követő évben is meghaladja a 700 000 €-t, kettős könyvvitelt kell vezetnie, és be kell jegyeztetnie magát a cégjegyzékbe (e. U.). Az 1 milliós határ egyetlen évre vonatkozik; átalakítást vagy minimális tőkét a törvény nem ír elő."}},{type:"number",level:2,value:1e6,tol:0,unit:{de:"€",en:"€",hu:"€"},de:{q:"Ab welchem Jahresumsatz in einem einzigen Jahr muss ein Einzelunternehmer jedenfalls auf doppelte Buchhaltung umsteigen (und sich als e. U. ins Firmenbuch eintragen)? Gib den Betrag in € an.",e:"Ab 1.000.000 € Umsatz in einem Jahr (oder wenn zwei Jahre hintereinander je 700.000 € überschritten werden) ist doppelte Buchhaltung Pflicht; darunter reicht die E/A-Rechnung."},en:{q:"From what annual turnover in a single year must a sole trader in any case switch to double-entry bookkeeping (and register as e. U.)? Give the amount in €.",e:"From €1,000,000 turnover in one year (or if €700,000 is exceeded in two consecutive years), double-entry bookkeeping is mandatory; below that, cash-basis accounts are enough."},hu:{q:"Egyetlen évben mekkora árbevételtől köteles az egyéni vállalkozó mindenképpen kettős könyvvitelre áttérni (és e. U.-ként bejegyeztetni magát)? Add meg az összeget €-ban.",e:"Egy évben 1 000 000 € árbevételtől (vagy ha két egymást követő évben is meghaladja a 700 000 €-t) kötelező a kettős könyvvitel; ez alatt elég a bevétel-kiadás nyilvántartás."}}],"businessplan-1jg":[{type:"tf",level:1,correct:!0,de:{q:"Wer für die Gründung einen Bankkredit oder eine Förderung beantragt, muss einen Businessplan vorlegen",e:"Richtig. Banken und Förderstellen verlangen einen Businessplan, um zu beurteilen, ob die Idee realisierbar und wirtschaftlich ist – und ob das Geld zurückfließen kann."},en:{q:"Anyone applying for a bank loan or a subsidy to start a business has to present a business plan",e:"True. Banks and funding bodies require a business plan to judge whether the idea is feasible and economically viable – and whether the money will be repaid."},hu:{q:"Aki az alapításhoz banki hitelt vagy támogatást igényel, annak üzleti tervet kell bemutatnia",e:"Igaz. A bankok és a támogató szervezetek üzleti tervet kérnek, hogy megítéljék, megvalósítható és gazdaságos-e az ötlet – és visszatérül-e a pénz."}},{type:"tf",level:2,correct:!1,de:{q:"Die Executive Summary steht am Ende des Businessplans und fasst nur die Finanzplanung zusammen",e:"Falsch. Die Executive Summary steht ganz am Anfang und gibt einen Überblick über die wichtigsten Aussagen und Kennzahlen des gesamten Plans – nicht nur über die Finanzen."},en:{q:"The executive summary comes at the end of the business plan and only summarises the financial planning",e:"False. The executive summary comes at the very beginning and gives an overview of the key statements and figures of the whole plan – not just the finances."},hu:{q:"A vezetői összefoglaló az üzleti terv végén áll, és csak a pénzügyi tervet foglalja össze",e:"Hamis. A vezetői összefoglaló a terv legelején áll, és a teljes terv legfontosabb állításairól és mutatóiról ad áttekintést – nem csak a pénzügyekről."}},{type:"tf",level:3,correct:!1,de:{q:"Ein Kontokorrentkredit eignet sich besonders gut, um langfristige Investitionen wie eine teure Produktionsmaschine zu finanzieren",e:"Falsch. Der Kontokorrentkredit ist ein Überziehungsrahmen am Girokonto für kurzfristige Geldengpässe. Langfristige Investitionen finanziert man mit Eigenkapital oder langfristigen Krediten."},en:{q:"An overdraft facility is particularly suitable for financing long-term investments such as an expensive production machine",e:"False. An overdraft facility is a credit line on the current account for short-term cash shortages. Long-term investments are financed with equity or long-term loans."},hu:{q:"A folyószámlahitel különösen alkalmas hosszú távú beruházások, például egy drága gyártógép finanszírozására",e:"Hamis. A folyószámlahitel a bankszámlához kapcsolódó hitelkeret rövid távú pénzszűke áthidalására. Hosszú távú beruházásokat saját tőkéből vagy hosszú lejáratú hitelből finanszíroznak."}},{type:"multi",level:1,correct:[0,1,2,3],de:{q:"Welche Funktionen erfüllt ein Businessplan? Wähle alle zutreffenden aus.",o:["Beurteilen, ob die Idee realisierbar und wirtschaftlich ist","Kapitalgeber, Lieferanten und Förderstellen überzeugen","Die Umsetzung zielgerichtet planen","Die Gründungsphase steuern und Ziele kontrollieren","Steuern sparen, weil er beim Finanzamt abgegeben wird","Die Gewerbeanmeldung ersetzen"],e:"Die vier Funktionen sind beurteilen, überzeugen, planen und steuern. „Steuern“ meint hier lenken, nicht Abgaben – der Businessplan spart keine Steuern und ersetzt auch keine Gewerbeanmeldung."},en:{q:"Which functions does a business plan fulfil? Select all that apply.",o:["Assess whether the idea is feasible and economically viable","Convince investors, suppliers and funding bodies","Plan the implementation in a targeted way","Steer the start-up phase and monitor goals","Save taxes because it is submitted to the tax office","Replace the trade registration"],e:"The four functions are assessing, convincing, planning and steering. A business plan does not save taxes and does not replace the trade registration."},hu:{q:"Milyen funkciókat tölt be az üzleti terv? Jelöld meg az összes helyeset.",o:["Megítélni, hogy az ötlet megvalósítható és gazdaságos-e","Meggyőzni a tőkebefektetőket, szállítókat és támogató szervezeteket","Célirányosan megtervezni a megvalósítást","Irányítani az alapítási szakaszt és ellenőrizni a célokat","Adót spórolni, mert le kell adni az adóhivatalnál","Kiváltani az iparbejelentést"],e:"A négy funkció: megítélés, meggyőzés, tervezés és irányítás. Az üzleti terv nem spórol adót, és nem helyettesíti az iparbejelentést."}},{type:"multi",level:2,correct:[0,1,3],de:{q:"Loopy schreibt den Abschnitt „Marketing“ ihres Businessplans. Welche Inhalte gehören hierher? Wähle alle zutreffenden aus.",o:["Preise der Pralinenboxen","Werbung auf Instagram und Flyer","Meilensteine mit Datum bis zur Eröffnung","Vertriebswege (Laden, Online-Shop)","Kapitalbedarf für die Ladeneinrichtung"],e:"Zum Marketing gehören Preise, Werbung und Vertriebswege. Meilensteine mit Datum stehen im Umsetzungsfahrplan, der Kapitalbedarf in der Finanzplanung."},en:{q:"Loopy is writing the ‘Marketing’ section of her business plan. Which contents belong here? Select all that apply.",o:["Prices of the chocolate boxes","Advertising on Instagram and flyers","Milestones with dates up to the opening","Sales channels (shop, online shop)","Capital required for the shop fittings"],e:"Marketing covers prices, advertising and sales channels. Milestones with dates belong in the implementation roadmap, the capital requirement in the financial planning."},hu:{q:"Loopy az üzleti terve „Marketing” fejezetét írja. Mely tartalmak tartoznak ide? Jelöld meg az összes helyeset.",o:["A bonbonos dobozok árai","Reklám az Instagramon és szórólapok","Mérföldkövek dátummal a megnyitásig","Értékesítési csatornák (bolt, webshop)","A bolti berendezés tőkeszükséglete"],e:"A marketinghez az árak, a reklám és az értékesítési csatornák tartoznak. A dátumozott mérföldkövek a megvalósítási ütemtervbe, a tőkeszükséglet a pénzügyi tervbe kerül."}},{type:"order",level:3,de:{q:"Bringe diese Bestandteile in die Reihenfolge, in der sie laut Checkliste im Businessplan stehen.",o:["Executive Summary","Unternehmen","Produkt und Dienstleistung","Branche, Markt und Wettbewerb","Marketing","Finanzplanung","Umsetzungsfahrplan"],e:"Zuerst der Überblick (Executive Summary), dann wer gründet und was angeboten wird, danach Markt und Marketing. Nach Chancen und Risiken folgen die Finanzplanung und zum Schluss der Fahrplan mit Meilensteinen."},en:{q:"Put these components in the order in which they appear in the business plan according to the checklist.",o:["Executive summary","Company","Product and service","Industry, market and competition","Marketing","Financial planning","Implementation roadmap"],e:"First the overview (executive summary), then who is founding and what is offered, then market and marketing. After opportunities and risks come the financial planning and finally the roadmap with milestones."},hu:{q:"Állítsd abba a sorrendbe ezeket a részeket, ahogyan az ellenőrzőlista szerint az üzleti tervben szerepelnek.",o:["Vezetői összefoglaló","A vállalkozás","Termék és szolgáltatás","Iparág, piac és verseny","Marketing","Pénzügyi terv","Megvalósítási ütemterv"],e:"Először az áttekintés (vezetői összefoglaló), majd hogy ki alapít és mit kínál, utána a piac és a marketing. Az esélyek és kockázatok után jön a pénzügyi terv, végül a mérföldköveket tartalmazó ütemterv."}},{type:"match",level:1,de:{q:"Ordne jedem Bestandteil des Businessplans den passenden Inhalt zu.",p:[["Executive Summary","Überblick über wichtigste Aussagen und Kennzahlen"],["Unternehmen","Profil, Tätigkeit, Personen, Rechtsform"],["Branche, Markt und Wettbewerb","Verkaufsmenge, Trends, Konkurrenz"],["Finanzplanung","Kapitalbedarf, Finanzierung, Umsatz"],["Umsetzungsfahrplan","Meilensteine mit Datum"]],e:"Jeder Teil beantwortet eine eigene Frage: Überblick, wer gründet, wie der Markt aussieht, wie viel Geld nötig ist und wann was passiert."},en:{q:"Match each component of the business plan with its content.",p:[["Executive summary","Overview of key statements and figures"],["Company","Profile, activity, people, legal form"],["Industry, market and competition","Sales volume, trends, competitors"],["Financial planning","Capital requirement, financing, turnover"],["Implementation roadmap","Milestones with dates"]],e:"Each part answers its own question: overview, who is founding, what the market looks like, how much money is needed and when what happens."},hu:{q:"Párosítsd az üzleti terv egyes részeit a hozzájuk tartozó tartalommal.",p:[["Vezetői összefoglaló","A legfontosabb állítások és mutatók áttekintése"],["A vállalkozás","Profil, tevékenység, személyek, jogi forma"],["Iparág, piac és verseny","Értékesítési mennyiség, trendek, versenytársak"],["Pénzügyi terv","Tőkeszükséglet, finanszírozás, árbevétel"],["Megvalósítási ütemterv","Mérföldkövek dátummal"]],e:"Minden rész egy saját kérdésre felel: áttekintés, ki alapít, milyen a piac, mennyi pénz kell, és mikor mi történik."}},{type:"mc",level:2,correctIndex:1,de:{q:"Loopy notiert: „15. Februar: Online-Shop geht live · 1. März: Eröffnung des Ladens · Mai: erstes Verkostungs-Event“. In welchen Teil des Businessplans gehört das?",o:["Branche, Markt und Wettbewerb","Umsetzungsfahrplan","Executive Summary","Finanzplanung"],e:"Konkrete Meilensteine mit Datum bilden den Umsetzungsfahrplan. Branche/Markt beschreibt Trends und Konkurrenz, die Finanzplanung das Geld – aber keiner davon den Zeitplan der Gründung."},en:{q:"Loopy notes: ‘15 February: online shop goes live · 1 March: shop opening · May: first tasting event’. Which part of the business plan does this belong in?",o:["Industry, market and competition","Implementation roadmap","Executive summary","Financial planning"],e:"Concrete milestones with dates form the implementation roadmap. Industry/market describes trends and competitors, financial planning the money – but neither covers the start-up timetable."},hu:{q:"Loopy feljegyzi: „Február 15.: elindul a webshop · Március 1.: a bolt megnyitása · Május: első kóstoló esemény”. Az üzleti terv melyik részébe tartozik ez?",o:["Iparág, piac és verseny","Megvalósítási ütemterv","Vezetői összefoglaló","Pénzügyi terv"],e:"A konkrét, dátumozott mérföldkövek alkotják a megvalósítási ütemtervet. Az iparág/piac rész a trendeket és a versenytársakat, a pénzügyi terv a pénzt írja le – az alapítás ütemezését egyik sem."}},{type:"mc",level:3,correctIndex:0,de:{q:"Loopy braucht 40.000 € für Kühlvitrine und Ladeneinrichtung. Außerdem fehlen im ruhigen Sommer erfahrungsgemäß kurzfristig bis zu 3.000 €. Welche Finanzierung ist im Finanzplan am sinnvollsten?",o:["Langfristiger Kredit für die Einrichtung, Kontokorrentkredit für Engpässe","Kontokorrentkredit für beides, weil er am flexibelsten ist","Kontokorrentkredit für die Einrichtung, langfristiger Kredit für Engpässe","Keine Finanzierung, weil die Marge alle Ausgaben sofort deckt"],e:"Langfristige Investitionen finanziert man langfristig, kurzfristige Geldengpässe mit dem Kontokorrentkredit (Überziehungsrahmen). Den teuren Überziehungsrahmen für eine Investition zu nutzen, wäre unpassend."},en:{q:"Loopy needs €40,000 for a refrigerated display case and shop fittings. In addition, experience shows that up to €3,000 is short for a while in the quiet summer. Which financing makes most sense in the financial plan?",o:["Long-term loan for the fittings, overdraft for the shortfalls","Overdraft for both, because it is the most flexible","Overdraft for the fittings, long-term loan for the shortfalls","No financing, because the margin covers all costs at once"],e:"Long-term investments are financed long-term; short-term cash shortages with an overdraft facility. Using an expensive overdraft for an investment would be inappropriate."},hu:{q:"Loopynak 40 000 € kell hűtővitrinre és bolti berendezésre. Ráadásul a csendes nyári időszakban tapasztalat szerint rövid ideig legfeljebb 3 000 € hiányzik. Melyik finanszírozás a legésszerűbb a pénzügyi tervben?",o:["Hosszú lejáratú hitel a berendezésre, folyószámlahitel a pénzszűkére","Folyószámlahitel mindkettőre, mert az a legrugalmasabb","Folyószámlahitel a berendezésre, hosszú lejáratú hitel a pénzszűkére","Nincs finanszírozás, mert az árrés azonnal fedez minden kiadást"],e:"A hosszú távú beruházást hosszú lejáratú forrásból, a rövid távú pénzszűkét folyószámlahitellel (hitelkerettel) finanszírozzák. A drága folyószámlahitelt beruházásra használni nem lenne célszerű."}},{type:"number",level:2,value:1650,tol:.01,unit:{de:"€",en:"€",hu:"€"},de:{q:"Für ihren Businessplan rechnet Loopy: Eine Geschenkbox verkauft sie um 14,90 € (netto), Einkauf und Verpackung kosten 9,40 € pro Box. Sie plant, 300 Boxen pro Monat zu verkaufen. Wie hoch ist die gesamte Marge pro Monat?",e:"Marge pro Box = 14,90 − 9,40 = 5,50 €. Gesamte Marge = 5,50 · 300 = 1.650 €."},en:{q:"For her business plan Loopy calculates: she sells a gift box for €14.90 (net); purchasing and packaging cost €9.40 per box. She plans to sell 300 boxes per month. What is the total margin per month?",e:"Margin per box = 14.90 − 9.40 = €5.50. Total margin = 5.50 · 300 = €1,650."},hu:{q:"Üzleti tervéhez Loopy így számol: egy ajándékdobozt 14,90 €-ért (nettó) ad el, a beszerzés és a csomagolás dobozonként 9,40 €. Havonta 300 doboz eladását tervezi. Mekkora a teljes havi árrés?",e:"Árrés dobozonként = 14,90 − 9,40 = 5,50 €. Teljes árrés = 5,50 · 300 = 1 650 €."}}],"vertraege-mitarbeiter":[{type:"tf",level:1,correct:!1,de:{q:"Ein freier Dienstnehmer ist an Weisungen sowie an fixe Arbeitszeiten und einen fixen Arbeitsort gebunden",e:"Falsch. Das beschreibt den „echten“ Arbeitsvertrag. Der freie Dienstnehmer schuldet zwar Arbeitskraft, aber ohne persönliche Abhängigkeit – er ist frei bei Zeit und Ort und nicht weisungsgebunden."},en:{q:"A freelance service provider (freier Dienstnehmer) is bound by instructions as well as by fixed working hours and a fixed place of work",e:"False. That describes a ‘real’ employment contract. A freelance service provider owes their labour, but without personal dependence – they are free in time and place and not bound by instructions."},hu:{q:"A „szabad” szolgálati szerződéssel dolgozó (freier Dienstnehmer) utasításokhoz, valamint rögzített munkaidőhöz és munkahelyhez kötött",e:"Hamis. Ez a „valódi” munkaszerződést írja le. A szabad szolgálati szerződéssel dolgozó munkaerőt nyújt ugyan, de személyes függőség nélkül – szabadon dönt az időről és a helyről, és nem kötik utasítások."}},{type:"tf",level:2,correct:!0,de:{q:"Beim Werkvertrag bekommt der Auftragnehmer sein Geld grundsätzlich erst, wenn das Werk laut Vertrag fertig ist",e:"Richtig. Beim Werkvertrag wird ein Erfolg geschuldet, nicht bloß Arbeitszeit. Bezahlt wird daher erst bei vertragsgemäßer Fertigstellung – und für Fehler haftet man im Rahmen der Gewährleistung."},en:{q:"Under a contract for work, the contractor generally only gets paid once the work has been completed as agreed in the contract",e:"True. A contract for work owes a result, not just working time. Payment is therefore due only when the work is completed as agreed – and the contractor is liable for defects under the warranty rules."},hu:{q:"Vállalkozási szerződésnél a vállalkozó főszabály szerint csak akkor kapja meg a díját, ha a mű a szerződés szerint elkészült",e:"Igaz. A vállalkozási szerződés eredményre irányul, nem pusztán munkaidőre. Ezért fizetni csak a szerződésszerű elkészüléskor kell – a hibákért pedig a vállalkozó szavatossággal felel."}},{type:"tf",level:3,correct:!1,de:{q:"Auch wenn ein schriftlicher Arbeitsvertrag bereits alle Angaben eines Dienstzettels enthält, muss der Arbeitgeber zusätzlich einen Dienstzettel ausstellen",e:"Falsch. Ein Dienstzettel ist nötig, wenn es keinen schriftlichen Arbeitsvertrag gibt. Enthält der schriftliche Vertrag schon alle Angaben, ist das eine der Ausnahmen – ein zusätzlicher Dienstzettel ist nicht nötig."},en:{q:"Even if a written employment contract already contains all the details of a written statement of employment terms (Dienstzettel), the employer must issue a Dienstzettel in addition",e:"False. A Dienstzettel is required when there is no written employment contract. If the written contract already contains all the details, this is one of the exceptions – no additional Dienstzettel is needed."},hu:{q:"Ha az írásos munkaszerződés már tartalmazza a Dienstzettel (írásos munkaviszony-tájékoztató) összes adatát, a munkáltatónak akkor is ki kell állítania egy külön Dienstzettelt",e:"Hamis. Dienstzettel akkor kell, ha nincs írásos munkaszerződés. Ha az írásos szerződés már minden adatot tartalmaz, az az egyik kivétel – külön Dienstzettelre nincs szükség."}},{type:"multi",level:1,correct:[0,1,2,3],de:{q:"Welche Angaben gehören in einen Dienstzettel? Wähle alle zutreffenden aus.",o:["Beginn des Arbeitsverhältnisses und Probezeit","Kollektivvertrag und Einstufung","Urlaubsausmaß","Normalarbeitszeit","Religionsbekenntnis der Arbeitnehmerin","Familienstand und Anzahl der Kinder"],e:"Der Dienstzettel hält die wesentlichen Rechte und Pflichten fest: u. a. Parteien, Beginn, Probezeit, KV und Einstufung, Kündigung, Arbeitsort, Entgelt, Urlaub, Arbeitszeit, Vorsorgekasse. Private Daten wie Religion oder Familienstand gehören nicht hinein."},en:{q:"Which details belong in a written statement of employment terms (Dienstzettel)? Select all that apply.",o:["Start of employment and probationary period","Collective agreement and pay grade","Amount of annual leave","Normal working hours","The employee's religion","Marital status and number of children"],e:"The Dienstzettel records the essential rights and duties: e.g. parties, start date, probation, collective agreement and grade, notice, place of work, pay, leave, working hours, severance fund. Private data such as religion or marital status do not belong in it."},hu:{q:"Mely adatok tartoznak a Dienstzettelbe (írásos munkaviszony-tájékoztatóba)? Jelöld meg az összes helyeset.",o:["A munkaviszony kezdete és a próbaidő","Kollektív szerződés és besorolás","A szabadság mértéke","A rendes munkaidő","A munkavállaló vallása","Családi állapot és a gyermekek száma"],e:"A Dienstzettel a lényeges jogokat és kötelezettségeket rögzíti: pl. a felek, kezdés, próbaidő, kollektív szerződés és besorolás, felmondás, munkavégzés helye, bér, szabadság, munkaidő, előgondoskodási pénztár. Magánadatok, mint a vallás vagy a családi állapot, nem tartoznak bele."}},{type:"multi",level:3,correct:[0,1,2],de:{q:"Welche Aussagen treffen auf den freien Dienstvertrag zu? Wähle alle richtigen aus.",o:["Geschuldet wird Arbeitskraft, aber ohne persönliche Abhängigkeit","Der freie Dienstnehmer darf sich vertreten lassen","Die Arbeitsmittel stellt meist der Auftraggeber","Geschuldet wird ein fertiges Werk bzw. ein Erfolg","Das wirtschaftliche Risiko trägt der freie Dienstnehmer selbst"],e:"Beim freien Dienstvertrag schuldet man Arbeitskraft ohne persönliche Abhängigkeit, Vertretung ist möglich, die Arbeitsmittel kommen meist vom Auftraggeber, der auch das Risiko trägt. Erfolg und eigenes Risiko kennzeichnen dagegen den Werkvertrag."},en:{q:"Which statements apply to the freelance service contract (freier Dienstvertrag)? Select all that apply.",o:["Labour is owed, but without personal dependence","The freelancer may have someone stand in for them","The work equipment is usually provided by the client","A finished piece of work or a result is owed","The freelancer bears the economic risk themselves"],e:"Under a freelance service contract, labour is owed without personal dependence, substitution is possible, and the equipment usually comes from the client, who also bears the risk. A result and one's own risk, by contrast, characterise the contract for work."},hu:{q:"Mely állítások igazak a „szabad” szolgálati szerződésre (freier Dienstvertrag)? Jelöld meg az összes helyeset.",o:["Munkaerőt kell nyújtani, de személyes függőség nélkül","A szabad szolgálati szerződéssel dolgozó helyettesíttetheti magát","A munkaeszközöket többnyire a megbízó biztosítja","Kész művet, illetve eredményt kell szolgáltatni","A gazdasági kockázatot maga a szabad szolgálati szerződéssel dolgozó viseli"],e:"A szabad szolgálati szerződésnél személyes függőség nélküli munkaerő a szolgáltatás, a helyettesítés lehetséges, a munkaeszközök többnyire a megbízótól származnak, aki a kockázatot is viseli. Az eredmény és a saját kockázat viszont a vállalkozási szerződés ismérvei."}},{type:"match",level:2,de:{q:"Ordne jede Beschreibung der passenden Vertragsart zu.",p:[["Weisungsgebunden, fixe Zeit und fixer Ort, persönliche Arbeitspflicht","„Echter“ Arbeitsvertrag"],["Arbeitskraft ohne persönliche Abhängigkeit, Vertretung möglich","Freier Dienstvertrag"],["Schuldet einen Erfolg, eigene Arbeitsmittel, eigenes Risiko","Werkvertrag"]],e:"Entscheidend ist: Wird ein Erfolg geschuldet (Werkvertrag) oder Arbeitskraft? Bei Arbeitskraft entscheidet die persönliche Abhängigkeit – ja: echter Arbeitsvertrag, nein: freier Dienstvertrag."},en:{q:"Match each description with the correct type of contract.",p:[["Bound by instructions, fixed time and place, must work personally","‘Real’ employment contract"],["Labour without personal dependence, substitution possible","Freelance service contract"],["Owes a result, own equipment, own risk","Contract for work"]],e:"The key question: is a result owed (contract for work) or labour? For labour, personal dependence decides – yes: real employment contract, no: freelance service contract."},hu:{q:"Párosítsd az egyes leírásokat a megfelelő szerződéstípussal.",p:[["Utasításhoz kötött, kötött idő és hely, személyes munkavégzés","„Valódi” munkaszerződés"],["Munkaerő személyes függőség nélkül, helyettesítés lehetséges","„Szabad” szolgálati szerződés"],["Eredménnyel tartozik, saját eszközök, saját kockázat","Vállalkozási szerződés"]],e:"A döntő kérdés: eredménnyel tartozik-e valaki (vállalkozási szerződés), vagy munkaerővel? Munkaerőnél a személyes függőség dönt – ha van: valódi munkaszerződés, ha nincs: szabad szolgálati szerződés."}},{type:"match",level:1,de:{q:"Ordne jedem Begriff aus dem Arbeitsverhältnis die passende Erklärung zu.",p:[["Dienstzettel","Schriftliche Aufzeichnung der wesentlichen Rechte und Pflichten"],["Kollektivvertrag","Vertrag der Sozialpartner für eine Branche, z. B. Mindestlöhne"],["Probezeit","Anfangszeit, in der beide jederzeit lösen können"],["Mitarbeitervorsorgekasse","Verwaltet die Beiträge für die Abfertigung neu"]],e:"Im Dienstzettel stehen u. a. Probezeit, Kollektivvertrag und Mitarbeitervorsorgekasse – deshalb sollte man diese Begriffe klar unterscheiden können."},en:{q:"Match each employment term with its explanation.",p:[["Dienstzettel","Written record of the essential rights and duties"],["Collective agreement","Agreement of the social partners for a sector, e.g. minimum wages"],["Probationary period","Initial period in which both sides can end it at any time"],["Employee severance fund","Manages contributions for the new severance pay"]],e:"The Dienstzettel includes, among other things, the probationary period, collective agreement and severance fund – so you should be able to tell these terms apart clearly."},hu:{q:"Párosítsd a munkaviszonnyal kapcsolatos fogalmakat a magyarázatukkal.",p:[["Dienstzettel","A lényeges jogok és kötelezettségek írásos rögzítése"],["Kollektív szerződés","A szociális partnerek ágazati megállapodása, pl. minimálbérek"],["Próbaidő","Kezdeti időszak, amikor bármelyik fél bármikor megszüntetheti"],["Munkavállalói előgondoskodási pénztár","Kezeli az új végkielégítési rendszer befizetéseit"]],e:"A Dienstzettelben többek között a próbaidő, a kollektív szerződés és az előgondoskodási pénztár is szerepel – ezért ezeket a fogalmakat világosan meg kell tudni különböztetni."}},{type:"mc",level:2,correctIndex:0,de:{q:"Student Jonas erfasst für eine Bank Daten von zu Hause aus. Er teilt sich die Zeit frei ein, ist an keine Weisungen gebunden und darf eine Kollegin für sich arbeiten lassen. Den Laptop stellt die Bank. Welcher Vertrag liegt vor?",o:["Freier Dienstvertrag","„Echter“ Arbeitsvertrag","Werkvertrag","Befristeter Arbeitsvertrag"],e:"Jonas schuldet Arbeitskraft, aber ohne persönliche Abhängigkeit (freie Zeit, keine Weisungen, Vertretung möglich) – ein freier Dienstvertrag. Ein Werkvertrag läge vor, wenn er ein bestimmtes fertiges Ergebnis schulden würde."},en:{q:"Jonas, a student, enters data for a bank from home. He organises his time freely, is not bound by instructions and may let a colleague do the work for him. The bank provides the laptop. Which contract is this?",o:["Freelance service contract","‘Real’ employment contract","Contract for work","Fixed-term employment contract"],e:"Jonas owes labour, but without personal dependence (free time, no instructions, substitution possible) – a freelance service contract. It would be a contract for work if he owed a specific finished result."},hu:{q:"Jonas egyetemista otthonról rögzít adatokat egy banknak. Szabadon osztja be az idejét, nem kötik utasítások, és egy kolléganőjét is maga helyett dolgoztathatja. A laptopot a bank biztosítja. Milyen szerződésről van szó?",o:["„Szabad” szolgálati szerződés","„Valódi” munkaszerződés","Vállalkozási szerződés","Határozott idejű munkaszerződés"],e:"Jonas munkaerővel tartozik, de személyes függőség nélkül (szabad időbeosztás, nincs utasítás, helyettesítés lehetséges) – ez szabad szolgálati szerződés. Vállalkozási szerződés akkor lenne, ha egy meghatározott kész eredménnyel tartozna."}},{type:"mc",level:3,correctIndex:3,de:{q:"Loopy beauftragt die Elektro Huber e. U., ihre neue Kühlvitrine zum Pauschalpreis von 600 € anzuschließen. Huber schickt einen Gesellen mit eigenem Werkzeug. Eine Woche später fällt die Vitrine wegen eines falschen Anschlusses aus. Was gilt?",o:["Echter Arbeitsvertrag – Loopy trägt als Arbeitgeberin das Risiko","Freier Dienstvertrag – Huber schuldet nur Arbeitskraft, keinen Erfolg","Werkvertrag – Haftung entfällt, weil nur der Geselle gearbeitet hat","Werkvertrag – Huber haftet für den Fehler (Gewährleistung)"],e:"Geschuldet ist ein Erfolg (funktionierender Anschluss) zum Pauschalpreis, mit eigenem Werkzeug und eigenen Arbeitnehmern – ein Werkvertrag. Der Werkvertragsnehmer haftet für Fehler, auch wenn seine Mitarbeiter:innen die Arbeit erledigt haben."},en:{q:"Loopy hires Elektro Huber e. U. to connect her new refrigerated display case for a flat fee of €600. Huber sends a journeyman with his own tools. A week later the case breaks down because of a faulty connection. What applies?",o:["Real employment contract – Loopy bears the risk as employer","Freelance service contract – Huber only owes labour, no result","Contract for work – no liability, since only the journeyman worked","Contract for work – Huber is liable for the defect (warranty)"],e:"A result (a working connection) is owed for a flat fee, with own tools and own employees – a contract for work. The contractor is liable for defects even if their employees did the work."},hu:{q:"Loopy megbízza az Elektro Huber e. U.-t, hogy 600 €-s átalányárért kösse be az új hűtővitrinjét. Huber egy segédet küld saját szerszámokkal. Egy héttel később a vitrin hibás bekötés miatt leáll. Mi a helyzet?",o:["Valódi munkaszerződés – Loopy munkáltatóként viseli a kockázatot","Szabad szolgálati szerződés – Huber csak munkaerővel tartozik, eredménnyel nem","Vállalkozási szerződés – nincs felelősség, mert csak a segéd dolgozott","Vállalkozási szerződés – Huber felel a hibáért (szavatosság)"],e:"Eredménnyel (működő bekötés) tartozik átalányárért, saját szerszámmal és saját munkavállalókkal – ez vállalkozási szerződés. A vállalkozó akkor is felel a hibákért, ha a munkát az alkalmazottai végezték."}},{type:"text",level:1,de:{q:"Wie nennt man ein Arbeitsverhältnis, das von vornherein nur für einen bestimmten Zeitraum abgeschlossen wird (z. B. für die Wintersaison im Tourismus)?",a:["befristetes Arbeitsverhältnis","befristet","befristeter Arbeitsvertrag","befristetes Dienstverhältnis","Befristung"],e:"Ein befristetes Arbeitsverhältnis endet automatisch mit Ablauf der vereinbarten Zeit – typisch etwa für Saisonarbeit. Auf dem Dienstzettel muss dann auch das Ende angegeben sein."},en:{q:"What do you call an employment relationship that is concluded from the outset only for a specific period (e.g. for the winter season in tourism)?",a:["fixed-term employment","fixed-term","fixed term","fixed-term contract","fixed-term employment contract","temporary employment"],e:"A fixed-term employment relationship ends automatically when the agreed period expires – typical, for example, of seasonal work. The end date must then also be stated in the Dienstzettel."},hu:{q:"Hogyan nevezzük azt a munkaviszonyt, amelyet eleve csak meghatározott időre kötnek (pl. a turizmusban a téli szezonra)?",a:["határozott idejű munkaviszony","határozott idejű","határozott idejű munkaszerződés","határozott időre szóló munkaviszony"],e:"A határozott idejű munkaviszony a megállapodott idő leteltével automatikusan megszűnik – ez jellemző például a szezonális munkára. Ilyenkor a Dienstzettelben a befejezés időpontját is fel kell tüntetni."}}]},l=e(t,n,a,s,i);export{l as default};
